WITH county_avg AS ( SELECT SUM("Free Meal Count (K-12)") * 1.0 / SUM("Enrollment (K-12)") AS avg_rate FROM frpm WHERE "County Name" = 'Alameda' ), top_school AS ( SELECT "CDSCode", "School Name", ("Free Meal Count (K-12)" * 1.0 / "Enrollment (K-12)") AS free_meal_rate FROM frpm WHERE "County Name" = 'Alameda' ORDER BY free_meal_rate DESC LIMIT 1 ) SELECT ts."School Name", ts.free_meal_rate AS "Free Meal Rate", ca.avg_rate AS "County Average Free Meal Rate", ts.free_meal_rate - ca.avg_rate AS "Free Meal Rate Deviation", sc."Charter" AS "Charter", sc."GSserved" AS "Grades Served", CASE WHEN sat.cds IS NULL OR sat.AvgScrRead IS NULL OR sat.AvgScrMath IS NULL OR sat.AvgScrWrite IS NULL THEN 'No SAT Data' WHEN (sat.AvgScrRead + sat.AvgScrMath + sat.AvgScrWrite) < 1200 THEN 'Below Average' WHEN (sat.AvgScrRead + sat.AvgScrMath + sat.AvgScrWrite) <= 1500 THEN 'Average' ELSE 'Above Average' END AS "SAT Performance Level" FROM top_school ts CROSS JOIN county_avg ca LEFT JOIN schools sc ON ts."CDSCode" = sc."CDSCode" LEFT JOIN satscores sat ON ts."CDSCode" = sat.cds	california_schools
SELECT CAST("Free Meal Count (Ages 5-17)" AS REAL) / CAST("Enrollment (Ages 5-17)" AS REAL) AS eligible_free_rate FROM frpm WHERE "Educational Option Type" = 'Continuation School' AND "Free Meal Count (Ages 5-17)" IS NOT NULL AND "Enrollment (Ages 5-17)" IS NOT NULL ORDER BY eligible_free_rate ASC LIMIT 3	california_schools
WITH charter AS ( SELECT sch.CDSCode, sch.School, sch.Street, sch.City, sch.State, sch.Zip, frpm."Enrollment (K-12)" AS EnrollmentK12, frpm."FRPM Count (K-12)" AS FRPMCountK12, CAST(frpm."FRPM Count (K-12)" AS REAL) / NULLIF(frpm."Enrollment (K-12)", 0) * 100 AS FRPMEligibilityRate, sch.OpenDate, sch.StatusType FROM schools sch JOIN frpm ON frpm.CDSCode = sch.CDSCode WHERE sch.District = 'Fresno County Office of Education' AND frpm."Charter School (Y/N)" = 1 ) SELECT c.School AS SchoolName, c.Street, c.City, c.State, c.Zip, c.EnrollmentK12, c.FRPMCountK12, c.FRPMEligibilityRate, CASE WHEN c.FRPMEligibilityRate > 75 THEN 'High FRPM' WHEN c.FRPMEligibilityRate >= 50 THEN 'Medium FRPM' ELSE 'Low FRPM' END AS FRPMCategory, sat.AvgScrRead, sat.AvgScrMath, sat.AvgScrWrite, sat.NumTstTakr, sat.NumGE1500, CASE WHEN sat.NumTstTakr > 0 THEN CAST(sat.NumGE1500 AS REAL) / sat.NumTstTakr * 100 ELSE NULL END AS ExcellenceRate, RANK() OVER (ORDER BY sat.AvgScrRead DESC) AS ReadingRank, RANK() OVER (ORDER BY sat.AvgScrMath DESC) AS MathRank, RANK() OVER (ORDER BY sat.AvgScrWrite DESC) AS WritingRank, STRFTIME('%Y', c.OpenDate) AS YearOpened, c.StatusType FROM charter c LEFT JOIN satscores sat ON sat.cds = c.CDSCode ORDER BY c.School	california_schools
WITH top AS ( SELECT CDSCode FROM frpm WHERE "Charter School (Y/N)" = 0 AND "Enrollment (K-12)" > 100 ORDER BY "FRPM Count (K-12)" DESC LIMIT 1 ) SELECT sch.School AS school_name, sch.Street, sch.City, sch.State, sch.Zip, sch.MailStreet AS mailing_street, sch.MailCity AS mailing_city, sch.MailState AS mailing_state, sch.MailZip AS mailing_zip, sch.Website, fr."Enrollment (K-12)" AS enrollment_k12, fr."FRPM Count (K-12)" AS frpm_eligible_k12, ROUND(fr."Percent (%) Eligible FRPM (K-12)" * 100, 2) AS frpm_percent, sat.NumTstTakr AS sat_test_takers, sat.NumGE1500 AS sat_num_ge1500, ROUND(CAST(sat.NumGE1500 AS REAL) * 100 / sat.NumTstTakr, 2) AS sat_ge1500_percent, sat.AvgScrRead AS sat_avg_read, sat.AvgScrMath AS sat_avg_math, sat.AvgScrWrite AS sat_avg_write, CASE WHEN fr."Percent (%) Eligible FRPM (K-12)" * 100 > 70 AND CAST(sat.NumGE1500 AS REAL) * 100 / sat.NumTstTakr > 20 THEN 'unexpectedly well' WHEN fr."Percent (%) Eligible FRPM (K-12)" * 100 < 30 AND CAST(sat.NumGE1500 AS REAL) * 100 / sat.NumTstTakr < 10 THEN 'unexpectedly poorly' ELSE 'neither' END AS unexpected_performance FROM top JOIN frpm fr ON fr.CDSCode = top.CDSCode JOIN schools sch ON sch.CDSCode = top.CDSCode LEFT JOIN satscores sat ON sat.cds = top.CDSCode AND sat.rtype = 'S'	california_schools
SELECT schools.Phone FROM schools JOIN frpm ON schools.CDSCode = frpm.CDSCode WHERE frpm."Charter School (Y/N)" = 1 AND frpm."Charter Funding Type" = 'Directly funded' AND schools.OpenDate > '2000-01-01'	california_schools
SELECT sch.School AS school_name, sat.AvgScrMath AS avg_sat_math, sat.AvgScrRead AS avg_sat_read, sat.AvgScrWrite AS avg_sat_write, (sat.AvgScrRead + sat.AvgScrMath + sat.AvgScrWrite) AS total_sat_score, RANK() OVER (ORDER BY (sat.AvgScrRead + sat.AvgScrMath + sat.AvgScrWrite) DESC) AS sat_performance_rank, frpm."Enrollment (K-12)" AS enrollment_k12, frpm."Percent (%) Eligible FRPM (K-12)" AS frpm_percent FROM schools sch JOIN satscores sat ON sch.CDSCode = sat.cds JOIN frpm ON sch.CDSCode = frpm.CDSCode WHERE sch.Virtual = 'F' AND sat.AvgScrMath > 400 ORDER BY total_sat_score DESC	california_schools
WITH base AS ( SELECT s.School AS school_name, sat.AvgScrRead AS avg_reading_score, sat.AvgScrMath AS avg_math_score, sat.AvgScrWrite AS avg_writing_score, (sat.AvgScrRead + sat.AvgScrMath + sat.AvgScrWrite) AS total_avg_sat_score, f."Percent (%) Eligible FRPM (K-12)" AS frpm_proportion FROM schools s JOIN satscores sat ON s.CDSCode = sat.cds JOIN frpm f ON f.CDSCode = s.CDSCode WHERE s.Magnet = 1 AND sat.NumTstTakr > 500 ) SELECT school_name, avg_reading_score, avg_math_score, avg_writing_score, total_avg_sat_score, RANK() OVER (ORDER BY total_avg_sat_score DESC) AS performance_rank, ROUND(frpm_proportion * 100, 2) AS frpm_percent, CASE WHEN frpm_proportion >= 0.75 THEN 'High Poverty' WHEN frpm_proportion >= 0.50 THEN 'Moderate Poverty' WHEN frpm_proportion >= 0.25 THEN 'Low Poverty' ELSE 'Very Low Poverty' END AS poverty_level, CASE WHEN total_avg_sat_score >= 1800 THEN 'Excellent' WHEN total_avg_sat_score >= 1500 THEN 'Good' WHEN total_avg_sat_score >= 1200 THEN 'Average' ELSE 'Below Average' END AS performance_category FROM base ORDER BY total_avg_sat_score DESC	california_schools
SELECT s."Phone" FROM satscores AS sat JOIN schools AS s ON sat."cds" = s."CDSCode" WHERE sat."rtype" = 'S' ORDER BY sat."NumGE1500" DESC LIMIT 1	california_schools
SELECT s."School" AS school_name, s."Street" AS street, s."City" AS city, s."State" AS state, s."Zip" AS zip, fr."School Type" AS school_type, fr."FRPM Count (K-12)" AS frpm_count, fr."Percent (%) Eligible FRPM (K-12)" AS frpm_eligible_percent, fr."Free Meal Count (K-12)" AS free_meal_count, fr."Percent (%) Eligible Free (K-12)" AS free_meal_eligible_percent, sat."AvgScrRead" AS sat_avg_read, sat."AvgScrMath" AS sat_avg_math, sat."AvgScrWrite" AS sat_avg_write, sat."NumGE1500" AS sat_num_ge1500 FROM frpm AS fr LEFT JOIN schools AS s ON s."CDSCode" = fr."CDSCode" LEFT JOIN satscores AS sat ON sat."cds" = fr."CDSCode" ORDER BY fr."FRPM Count (K-12)" DESC LIMIT 10	california_schools
SELECT COUNT(*) AS school_count FROM satscores s JOIN schools sc ON s.cds = sc.CDSCode WHERE s.AvgScrMath > 560 AND sc.FundingType = 'Directly funded'	california_schools
WITH top AS ( SELECT CAST(cds AS INTEGER) AS cds_int, AvgScrRead, AvgScrMath, AvgScrWrite FROM satscores WHERE rtype = 'S' AND NumTstTakr > 10 ORDER BY AvgScrRead DESC LIMIT 1 ) SELECT sch.County, sch.District, sch.School, sch.Street, sch.City, sch.Zip, sch.State, s.AvgScrRead, s.AvgScrMath, s.AvgScrWrite, fr."FRPM Count (K-12)", fr."Percent (%) Eligible FRPM (K-12)", fr."Enrollment (K-12)", sch.Charter FROM top s JOIN schools sch ON sch.CDSCode = printf('%014d', s.cds_int) JOIN frpm fr ON fr.CDSCode = printf('%014d', s.cds_int)	california_schools
WITH school_data AS ( SELECT f."County Name" AS county_name, f."School Name" AS school_name, f."Enrollment (K-12)" AS enrollment_k12, f."Enrollment (Ages 5-17)" AS enrollment_ages_5_17, f."Enrollment (K-12)" + f."Enrollment (Ages 5-17)" AS total_enrollment, f."Percent (%) Eligible Free (K-12)" AS pct_free_k12, f."Percent (%) Eligible FRPM (K-12)" AS pct_frpm_k12, CASE WHEN f."Percent (%) Eligible FRPM (K-12)" >= 0.75 THEN 'High' WHEN f."Percent (%) Eligible FRPM (K-12)" >= 0.50 THEN 'Medium' ELSE 'Low' END AS frpm_level, f."Charter School (Y/N)" AS charter_status, s.NumTstTakr AS num_tst_takr, s.NumGE1500 AS num_ge1500, CASE WHEN s.NumTstTakr > 0 THEN CAST(s.NumGE1500 AS REAL) * 100.0 / s.NumTstTakr ELSE NULL END AS pct_sat_ge1500, s.AvgScrRead AS avg_scr_read, s.AvgScrMath AS avg_scr_math, s.AvgScrWrite AS avg_scr_write, s.AvgScrRead + s.AvgScrMath + s.AvgScrWrite AS total_sat FROM frpm f JOIN satscores s ON CAST(f.CDSCode AS INTEGER) = CAST(s.cds AS INTEGER) WHERE s.rtype = 'S' AND f."Enrollment (K-12)" + f."Enrollment (Ages 5-17)" > 500 AND ( f."Percent (%) Eligible FRPM (K-12)" > 0.60 OR ( s.NumTstTakr > 0 AND CAST(s.NumGE1500 AS REAL) * 100.0 / s.NumTstTakr > 30.0 ) ) ) SELECT county_name, school_name, enrollment_k12, enrollment_ages_5_17, total_enrollment, pct_free_k12, pct_frpm_k12, frpm_level, charter_status, num_tst_takr, num_ge1500, pct_sat_ge1500, avg_scr_read, avg_scr_math, avg_scr_write, total_sat, RANK() OVER (PARTITION BY county_name ORDER BY total_enrollment DESC) AS county_enrollment_rank, RANK() OVER (PARTITION BY frpm_level ORDER BY total_sat DESC) AS frpm_sat_rank FROM school_data ORDER BY county_name, frpm_level, county_enrollment_rank, frpm_sat_rank	california_schools
SELECT s.School, s.County, s.District, s.Street, s.City, s.Zip, s.Phone, s.Website, s.Charter, s.Magnet, s.Latitude, s.Longitude FROM satscores sat JOIN frpm f ON sat.cds = f.CDSCode JOIN schools s ON s.CDSCode = f.CDSCode WHERE s.StatusType = 'Active' AND sat.NumTstTakr > 0 AND f."Enrollment (Ages 5-17)" > 0 AND CAST(sat.NumGE1500 AS REAL) / sat.NumTstTakr > 0.3 ORDER BY CAST(f."Free Meal Count (Ages 5-17)" AS REAL) / f."Enrollment (Ages 5-17)" DESC LIMIT 1	california_schools
SELECT sc.School AS SchoolName, sc.Phone AS ContactNumber, sc.City AS City, sc.Charter AS CharterStatus, CASE WHEN f."Percent (%) Eligible FRPM (K-12)" > 0.75 THEN 'High Poverty' WHEN f."Percent (%) Eligible FRPM (K-12)" > 0.50 THEN 'Medium Poverty' WHEN f."Percent (%) Eligible FRPM (K-12)" > 0.25 THEN 'Low Poverty' ELSE 'Very Low Poverty' END AS PovertyClassification FROM satscores s JOIN schools sc ON s.cds = sc.CDSCode JOIN frpm f ON s.cds = f.CDSCode WHERE s.rtype = 'S' AND s.NumTstTakr > 0 AND s.NumGE1500 IS NOT NULL ORDER BY CAST(s.NumGE1500 AS REAL) / s.NumTstTakr DESC LIMIT 3	california_schools
SELECT s.NCESSchool FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode ORDER BY f."Enrollment (Ages 5-17)" DESC LIMIT 5	california_schools
SELECT s.dname FROM satscores s JOIN schools sc ON s.cds = sc.CDSCode WHERE s.rtype = 'D' AND sc.StatusType = 'Active' ORDER BY s.AvgScrRead DESC LIMIT 1	california_schools
SELECT COUNT(*) FROM schools s JOIN satscores t ON s.CDSCode = t.cds WHERE s.StatusType = 'Merged' AND s.County = 'Alameda' AND t.NumTstTakr < 100	california_schools
SELECT s.CharterNum FROM satscores sa JOIN schools s ON sa.cds = s.CDSCode WHERE sa.AvgScrWrite > 499 AND s.CharterNum IS NOT NULL ORDER BY sa.AvgScrWrite DESC	california_schools
SELECT CASE WHEN s.NumTstTakr < 50 THEN 'under 50 testers' WHEN s.NumTstTakr <= 100 THEN '50-100 testers' WHEN s.NumTstTakr <= 250 THEN '100-250 testers' END AS testing_volume, s.AvgScrRead, s.AvgScrMath, s.AvgScrWrite, sc.County, sc.District, sc.School, sc.Charter, sc.FundingType, sc.GSoffered, sc.GSserved, sc.Virtual, sc.Magnet FROM satscores s JOIN frpm f ON s.cds = f.CDSCode JOIN schools sc ON s.cds = sc.CDSCode WHERE f."Charter Funding Type" = 'Directly funded' AND sc.County = 'Fresno' AND sc.Charter = 1 AND s.NumTstTakr <= 250 ORDER BY CASE WHEN s.NumTstTakr < 50 THEN 1 WHEN s.NumTstTakr <= 100 THEN 2 WHEN s.NumTstTakr <= 250 THEN 3 END, s.NumTstTakr, sc.School	california_schools
SELECT s.School, s.Phone, s.Ext, s.Website, s.AdmEmail1, s.Street, s.City, s.Zip, s.State, ss.AvgScrRead, ss.AvgScrMath, ss.AvgScrWrite, ss.NumGE1500, f."Charter School (Y/N)", f."Enrollment (K-12)", f."Percent (%) Eligible FRPM (K-12)" FROM satscores ss JOIN schools s ON ss.cds = s.CDSCode LEFT JOIN frpm f ON f.CDSCode = s.CDSCode WHERE ss.rtype = 'S' AND s.StatusType = 'Active' AND ss.NumTstTakr >= 10 ORDER BY ss.AvgScrMath DESC LIMIT 1	california_schools
WITH hs AS ( SELECT * FROM frpm WHERE "County Name" = 'Amador' AND "Low Grade" = '9' AND "High Grade" = '12' ) SELECT COUNT(*) AS total_high_schools, AVG("Enrollment (K-12)") AS avg_enrollment, SUM(CASE WHEN "Charter School (Y/N)" = 1 THEN 1 ELSE 0 END) AS charter_schools, SUM(CASE WHEN "Charter School (Y/N)" = 0 THEN 1 ELSE 0 END) AS non_charter_schools, AVG("Percent (%) Eligible FRPM (K-12)") AS avg_poverty_rate, COUNT(DISTINCT "District Code") AS num_districts, AVG(s."AvgScrRead") AS avg_sat_read, AVG(s."AvgScrMath") AS avg_sat_math, AVG(s."AvgScrWrite") AS avg_sat_write, (SELECT h2."School Name" FROM hs h2 ORDER BY h2."Enrollment (K-12)" DESC LIMIT 1) AS largest_school, SUM(CASE WHEN "Percent (%) Eligible FRPM (K-12)" > 0.75 THEN 1 ELSE 0 END) AS high_poverty_schools FROM hs LEFT JOIN satscores s ON s."rtype" = 'S' AND s."cds" = substr(hs."CDSCode", 1, 2) || substr(hs."CDSCode", 4)	california_schools
SELECT AVG(frpm."Free Meal Count (K-12)" * 100.0 / frpm."Enrollment (K-12)") AS avg_free_meal_pct, SUM(CASE WHEN s.Charter = 1 THEN 1 ELSE 0 END) AS charter_count, SUM(CASE WHEN s.Charter = 0 THEN 1 ELSE 0 END) AS non_charter_count, SUM(sa.total_score * sa.NumTstTakr) / NULLIF(SUM(CASE WHEN sa.total_score IS NOT NULL THEN sa.NumTstTakr ELSE 0 END), 0) AS avg_sat_score, SUM(CASE WHEN frpm."Free Meal Count (K-12)" > 600 THEN 1 ELSE 0 END) AS very_high_count, SUM(CASE WHEN frpm."Free Meal Count (K-12)" > 500 AND frpm."Free Meal Count (K-12)" <= 600 THEN 1 ELSE 0 END) AS high_count, SUM(CASE WHEN frpm."Free Meal Count (K-12)" <= 500 THEN 1 ELSE 0 END) AS moderate_count FROM frpm JOIN schools s ON s.CDSCode = frpm.CDSCode LEFT JOIN ( SELECT cds, (AvgScrRead + AvgScrMath + AvgScrWrite) AS total_score, NumTstTakr FROM satscores ) sa ON sa.cds = frpm.CDSCode WHERE s.County = 'Los Angeles' AND frpm."Free Meal Count (K-12)" > 500 AND frpm."FRPM Count (K-12)" < 700	california_schools
SELECT sname FROM satscores WHERE cname = 'Contra Costa' AND rtype = 'S' ORDER BY NumTstTakr DESC LIMIT 1	california_schools
SELECT s.School, s.Street, s.City, s.State, s.Zip FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode WHERE ABS(f."Enrollment (K-12)" - f."Enrollment (Ages 5-17)") > 30	california_schools
SELECT s.sname FROM satscores s JOIN frpm f ON s.cds = f.CDSCode WHERE s.rtype = 'S' AND (f."Free Meal Count (K-12)" / f."Enrollment (K-12)") > 0.1 AND s.NumGE1500 > 0	california_schools
SELECT sc.School, f."Educational Option Type" FROM satscores s JOIN schools sc ON s.cds = sc.CDSCode JOIN frpm f ON s.cds = f.CDSCode WHERE sc.City = 'Riverside' AND s.rtype = 'S' AND s.AvgScrMath > 400	california_schools
SELECT s.School, s.Street, s.City, s.State, s.Zip FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode WHERE f."County Name" = 'Monterey' AND f."School Type" = 'High Schools (Public)' AND f."FRPM Count (Ages 5-17)" > 800	california_schools
SELECT sc.School, s.AvgScrWrite, sc.Phone FROM satscores s JOIN schools sc ON s.cds = sc.CDSCode WHERE sc.OpenDate > '1991-12-31' OR sc.ClosedDate < '2000-01-01'	california_schools
WITH locally_funded_diff AS ( SELECT s.School, s.DOCType, f."Enrollment (K-12)" - f."Enrollment (Ages 5-17)" AS EnrollmentDiff FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.FundingType = 'Locally funded' ) SELECT School, DOCType FROM locally_funded_diff WHERE EnrollmentDiff > (SELECT AVG(EnrollmentDiff) FROM locally_funded_diff)	california_schools
SELECT s."OpenDate" FROM schools s JOIN frpm f ON s."CDSCode" = f."CDSCode" WHERE s."GSoffered" = 'K-12' ORDER BY f."Enrollment (K-12)" DESC LIMIT 1	california_schools
SELECT s.City FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode GROUP BY s.City ORDER BY SUM(f."Enrollment (K-12)") ASC LIMIT 5	california_schools
WITH targets AS ( SELECT * FROM frpm ORDER BY "Enrollment (K-12)" DESC, "CDSCode" LIMIT 2 OFFSET 9 ) SELECT t."School Name", t."Enrollment (K-12)", t."Free Meal Count (K-12)", CAST(t."Free Meal Count (K-12)" AS REAL) / t."Enrollment (K-12)" AS "Free Meal Eligibility Rate", sc."Street", sc."City", sc."State", sc."Zip", t."School Type", t."Low Grade", t."High Grade", s."NumTstTakr", s."AvgScrRead", s."AvgScrMath", s."AvgScrWrite", s."NumGE1500" FROM targets t LEFT JOIN schools sc ON t."CDSCode" = sc."CDSCode" LEFT JOIN satscores s ON t."CDSCode" = s."cds" ORDER BY t."Enrollment (K-12)" DESC, t."CDSCode"	california_schools
WITH top_schools AS ( SELECT f.CDSCode, f."FRPM Count (K-12)" AS frpm_count, f."Enrollment (K-12)" AS enrollment_k12 FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode WHERE s.SOC = '66' ORDER BY f."FRPM Count (K-12)" DESC LIMIT 5 ) SELECT s.School AS school_name, CAST(t.frpm_count AS REAL) / t.enrollment_k12 AS eligibility_rate, sat.AvgScrRead AS avg_reading, sat.AvgScrMath AS avg_math, sat.AvgScrWrite AS avg_writing, CAST(sat.NumTstTakr AS REAL) / sat.enroll12 AS sat_participation_rate, CAST(sat.NumGE1500 AS REAL) / sat.NumTstTakr AS high_scorer_rate FROM top_schools t JOIN schools s ON s.CDSCode = t.CDSCode LEFT JOIN satscores sat ON sat.cds = t.CDSCode ORDER BY t.frpm_count DESC	california_schools
SELECT frpm."School Name" AS "School Name", schools.Website AS "Website" FROM frpm JOIN schools ON frpm.CDSCode = schools.CDSCode WHERE frpm."Free Meal Count (Ages 5-17)" BETWEEN 1900 AND 2000	california_schools
SELECT "frpm"."Free Meal Count (Ages 5-17)" * 1.0 / "frpm"."Enrollment (Ages 5-17)" AS free_rate FROM "schools" JOIN "frpm" ON "schools"."CDSCode" = "frpm"."CDSCode" WHERE "schools"."AdmFName1" = 'Kacey' AND "schools"."AdmLName1" = 'Gibson'	california_schools
SELECT s."AdmEmail1" FROM frpm f JOIN schools s ON f."CDSCode" = s."CDSCode" WHERE s."Charter" = 1 ORDER BY f."Enrollment (K-12)" ASC LIMIT 1	california_schools
SELECT sch.AdmFName1, sch.AdmLName1, sch.AdmFName2, sch.AdmLName2, sch.AdmFName3, sch.AdmLName3 FROM satscores s JOIN schools sch ON s.cds = sch.CDSCode WHERE s.rtype = 'S' ORDER BY s.NumGE1500 DESC LIMIT 1	california_schools
SELECT s.Street, s.City, s.Zip, s.State FROM satscores AS t JOIN schools AS s ON t.cds = s.CDSCode WHERE t.NumTstTakr > 0 AND t.NumGE1500 IS NOT NULL ORDER BY CAST(t.NumGE1500 AS REAL) / t.NumTstTakr ASC, t.cds ASC LIMIT 1	california_schools
SELECT schools.Website FROM schools JOIN satscores ON satscores.cds = schools.CDSCode WHERE schools.County = 'Los Angeles' AND satscores.NumTstTakr BETWEEN 2000 AND 3000 ORDER BY satscores.NumTstTakr DESC	california_schools
SELECT AVG(s."NumTstTakr") AS average_test_takers FROM "satscores" s JOIN "schools" sch ON s."cds" = sch."CDSCode" WHERE sch."County" = 'Fresno' AND sch."OpenDate" BETWEEN '1980-01-01' AND '1980-12-31'	california_schools
SELECT s.Phone FROM satscores AS sa JOIN schools AS s ON sa.cds = s.CDSCode WHERE sa.dname = 'Fresno Unified' ORDER BY sa.AvgScrRead IS NULL, sa.AvgScrRead ASC LIMIT 1	california_schools
WITH ranked AS ( SELECT s.School, s.County, s.Virtual, sat.AvgScrRead, ROW_NUMBER() OVER (PARTITION BY s.County ORDER BY sat.AvgScrRead DESC) AS rn FROM schools AS s JOIN satscores AS sat ON s.CDSCode = sat.cds WHERE sat.rtype = 'S' AND sat.AvgScrRead IS NOT NULL ) SELECT School FROM ranked WHERE Virtual = 'F' AND rn <= 5	california_schools
SELECT frpm."Educational Option Type" FROM satscores JOIN frpm ON satscores.cds = frpm.CDSCode ORDER BY satscores.AvgScrMath DESC LIMIT 1	california_schools
SELECT s.AvgScrMath AS avg_math_score, sch.County FROM satscores s JOIN schools sch ON s.cds = sch.CDSCode WHERE s.AvgScrMath IS NOT NULL AND s.AvgScrRead IS NOT NULL AND s.AvgScrWrite IS NOT NULL ORDER BY (s.AvgScrMath + s.AvgScrRead + s.AvgScrWrite) / 3.0 ASC LIMIT 1	california_schools
SELECT s.AvgScrWrite, sc.City FROM satscores s JOIN schools sc ON s.cds = sc.CDSCode WHERE s.rtype = 'S' ORDER BY s.NumGE1500 DESC LIMIT 1	california_schools
WITH target AS ( SELECT CDSCode FROM schools WHERE (AdmFName1 = 'Ricci' AND AdmLName1 = 'Ulrich') OR (AdmFName2 = 'Ricci' AND AdmLName2 = 'Ulrich') OR (AdmFName3 = 'Ricci' AND AdmLName3 = 'Ulrich') ), school_sat AS ( SELECT cds, dname, enroll12, NumTstTakr, AvgScrRead, AvgScrMath, AvgScrWrite, (AvgScrRead + AvgScrMath + AvgScrWrite) AS total_sat, RANK() OVER (ORDER BY (AvgScrRead + AvgScrMath + AvgScrWrite) DESC) AS sat_rank FROM satscores WHERE rtype = 'S' ), district_avg AS ( SELECT dname, AVG(AvgScrWrite) AS district_avg_writing FROM satscores WHERE rtype = 'S' GROUP BY dname ) SELECT COUNT(DISTINCT t.CDSCode) AS school_count, AVG(ss.AvgScrRead) AS avg_sat_read, AVG(ss.AvgScrMath) AS avg_sat_math, AVG(ss.AvgScrWrite) AS avg_sat_write, AVG(ss.total_sat) AS avg_total_sat, AVG(ss.sat_rank) AS avg_sat_rank, AVG(fr."Percent (%) Eligible FRPM (K-12)") AS avg_frpm_eligibility_rate, AVG(CAST(ss.NumTstTakr AS REAL) * 100 / ss.enroll12) AS avg_test_participation_rate, AVG(ss.AvgScrWrite - da.district_avg_writing) AS avg_writing_diff_vs_district_avg FROM target t JOIN school_sat ss ON ss.cds = t.CDSCode JOIN frpm fr ON fr.CDSCode = t.CDSCode JOIN district_avg da ON da.dname = ss.dname	california_schools
SELECT s.School FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.DOC = '31' ORDER BY f."Enrollment (K-12)" DESC LIMIT 1	california_schools
SELECT COUNT(*) / 12.0 AS monthly_average_schools FROM schools WHERE County = 'Alameda' AND DOC = '52' AND STRFTIME('%Y', OpenDate) = '1980'	california_schools
SELECT CAST(SUM(CASE WHEN DOC = '54' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN DOC = '52' THEN 1 ELSE 0 END) AS ratio FROM schools WHERE County = 'Orange' AND StatusType = 'Merged'	california_schools
SELECT "County", "School", "ClosedDate" FROM schools WHERE "StatusType" = 'Closed' AND "County" = ( SELECT "County" FROM schools WHERE "StatusType" = 'Closed' GROUP BY "County" ORDER BY COUNT(*) DESC LIMIT 1 ) ORDER BY "ClosedDate", "School"	california_schools
SELECT s.MailStreet, s.School FROM satscores t JOIN schools s ON t.cds = s.CDSCode WHERE t.rtype = 'S' ORDER BY t.AvgScrMath DESC LIMIT 1 OFFSET 6	california_schools
SELECT s.MailStreet, s.School FROM satscores sat JOIN schools s ON sat.cds = s.CDSCode WHERE sat.rtype = 'S' AND sat.AvgScrRead IS NOT NULL ORDER BY sat.AvgScrRead ASC LIMIT 1	california_schools
SELECT COUNT(*) FROM satscores JOIN schools ON satscores.cds = schools.CDSCode WHERE schools.MailCity = 'Lakeport' AND (satscores.AvgScrRead + satscores.AvgScrMath + satscores.AvgScrWrite) >= 1500	california_schools
SELECT SUM(s."NumTstTakr") AS total_test_takers FROM satscores s JOIN schools sch ON s.cds = sch.CDSCode WHERE sch.MailCity = 'Fresno'	california_schools
SELECT School, MailZip FROM schools WHERE (AdmFName1 = 'Avetik' AND AdmLName1 = 'Atoian') OR (AdmFName2 = 'Avetik' AND AdmLName2 = 'Atoian') OR (AdmFName3 = 'Avetik' AND AdmLName3 = 'Atoian')	california_schools
WITH county_stats AS ( SELECT sc.County AS county, COUNT(DISTINCT sc.CDSCode) AS total_schools, COUNT(DISTINCT CASE WHEN sc.Charter = 1 THEN sc.CDSCode END) AS charter_schools, COUNT(DISTINCT CASE WHEN f."Percent (%) Eligible FRPM (K-12)" > 0.5 THEN sc.CDSCode END) AS high_frpm_schools, AVG(sat.AvgScrRead + sat.AvgScrMath + sat.AvgScrWrite) AS avg_total_sat, SUM(f."FRPM Count (K-12)") AS total_frpm_students, SUM(f."Enrollment (K-12)") AS total_enrollment FROM schools sc LEFT JOIN satscores sat ON sat.cds = sc.CDSCode LEFT JOIN frpm f ON f.CDSCode = sc.CDSCode WHERE sc.County IN ('Colusa','Humboldt') GROUP BY sc.County ) SELECT CAST(MAX(CASE WHEN county = 'Colusa' THEN total_schools END) AS REAL) / MAX(CASE WHEN county = 'Humboldt' THEN total_schools END) AS ratio_total_schools, CAST(MAX(CASE WHEN county = 'Colusa' THEN charter_schools END) AS REAL) / MAX(CASE WHEN county = 'Humboldt' THEN charter_schools END) AS ratio_charter_schools, CAST(MAX(CASE WHEN county = 'Colusa' THEN high_frpm_schools END) AS REAL) / MAX(CASE WHEN county = 'Humboldt' THEN high_frpm_schools END) AS ratio_high_frpm_schools, MAX(CASE WHEN county = 'Colusa' THEN avg_total_sat END) / MAX(CASE WHEN county = 'Humboldt' THEN avg_total_sat END) AS ratio_avg_sat_score, CAST(MAX(CASE WHEN county = 'Colusa' THEN total_frpm_students END) AS REAL) / MAX(CASE WHEN county = 'Humboldt' THEN total_frpm_students END) AS ratio_total_frpm_students, CAST(MAX(CASE WHEN county = 'Colusa' THEN total_enrollment END) AS REAL) / MAX(CASE WHEN county = 'Humboldt' THEN total_enrollment END) AS ratio_total_enrollment FROM county_stats	california_schools
SELECT COUNT(*) FROM schools WHERE MailState = 'CA' AND StatusType = 'Active' AND City = 'San Joaquin'	california_schools
SELECT s.Phone, s.Ext FROM satscores ss JOIN schools s ON ss.cds = s.CDSCode WHERE ss.rtype = 'S' ORDER BY ss.AvgScrWrite DESC LIMIT 1 OFFSET 332	california_schools
SELECT "School", "Phone", "Ext" FROM schools WHERE "Zip" = '95203-3704'	california_schools
SELECT Website FROM schools WHERE (AdmFName1='Mike' AND AdmLName1='Larson') OR (AdmFName1='Dante' AND AdmLName1='Alvarez') OR (AdmFName2='Mike' AND AdmLName2='Larson') OR (AdmFName2='Dante' AND AdmLName2='Alvarez') OR (AdmFName3='Mike' AND AdmLName3='Larson') OR (AdmFName3='Dante' AND AdmLName3='Alvarez')	california_schools
WITH school_metrics AS ( SELECT s.School AS school_name, f."Enrollment (K-12)" AS enrollment_k_12, f."FRPM Count (K-12)" AS frpm_count_k_12, ROUND(f."Percent (%) Eligible FRPM (K-12)" * 100, 2) AS percent_eligible_frpm, CASE WHEN f."Percent (%) Eligible FRPM (K-12)" > 0.75 THEN 'High Poverty' WHEN f."Percent (%) Eligible FRPM (K-12)" >= 0.50 THEN 'Medium-High Poverty' WHEN f."Percent (%) Eligible FRPM (K-12)" >= 0.25 THEN 'Medium-Low Poverty' WHEN f."Percent (%) Eligible FRPM (K-12)" < 0.25 THEN 'Low Poverty' ELSE NULL END AS poverty_level, sat.NumTstTakr AS num_test_takers, sat.AvgScrRead AS avg_score_read, sat.AvgScrMath AS avg_score_math, sat.AvgScrWrite AS avg_score_write, sat.NumGE1500 AS num_ge1500, ROUND(100.0 * sat.NumGE1500 / NULLIF(sat.NumTstTakr, 0), 2) AS pct_ge1500, RANK() OVER (ORDER BY f."Enrollment (K-12)" DESC) AS enrollment_rank FROM schools s LEFT JOIN frpm f ON s.CDSCode = f.CDSCode LEFT JOIN satscores sat ON s.CDSCode = sat.cds AND sat.rtype = 'S' WHERE s.County = 'San Joaquin' AND s.Virtual = 'P' AND s.Charter = 1 ) SELECT school_name, enrollment_k_12, frpm_count_k_12, percent_eligible_frpm, poverty_level, num_test_takers, avg_score_read, avg_score_math, avg_score_write, num_ge1500, pct_ge1500, enrollment_rank FROM school_metrics ORDER BY enrollment_rank	california_schools
SELECT s.School, f."Enrollment (K-12)" AS enrollment_size, f."Percent (%) Eligible FRPM (K-12)" AS frpm_eligible_rate, sa.AvgScrRead, sa.AvgScrMath, sa.AvgScrWrite, sa.NumGE1500, RANK() OVER (PARTITION BY s.City ORDER BY f."Enrollment (K-12)" DESC) AS size_rank FROM schools s LEFT JOIN frpm f ON s.CDSCode = f.CDSCode LEFT JOIN satscores sa ON s.CDSCode = sa.cds WHERE s.City = 'Hickman' AND s.Charter = 1 AND s.DOC = '52' ORDER BY size_rank	california_schools
WITH la_noncharter AS ( SELECT "School Name", "Enrollment (K-12)", "Free Meal Count (K-12)", "Free Meal Count (K-12)" * 100.0 / "Enrollment (K-12)" AS exact_free_meal_pct FROM frpm WHERE "Charter School (Y/N)" = 0 AND "County Name" = 'Los Angeles' ), ranked AS ( SELECT "School Name", "Enrollment (K-12)", "Free Meal Count (K-12)", exact_free_meal_pct, RANK() OVER (ORDER BY exact_free_meal_pct ASC) AS rank_within_county, (SELECT COUNT(*) FROM la_noncharter WHERE exact_free_meal_pct < 0.18) AS low_free_meal_school_count FROM la_noncharter ) SELECT "School Name", "Enrollment (K-12)", "Free Meal Count (K-12)", exact_free_meal_pct, rank_within_county, low_free_meal_school_count FROM ranked WHERE exact_free_meal_pct < 0.18 ORDER BY exact_free_meal_pct ASC	california_schools
SELECT School, City, AdmFName1, AdmLName1, AdmFName2, AdmLName2, AdmFName3, AdmLName3 FROM schools WHERE Charter = 1 AND CharterNum = '00D2'	california_schools
SELECT COUNT(*) AS total_schools FROM schools WHERE "MailCity" = 'Hickman' AND "CharterNum" = '00D4'	california_schools
SELECT CAST(SUM(CASE WHEN "FundingType" = 'Locally funded' THEN 1 ELSE 0 END) AS REAL) * 100 / (COUNT(*) - SUM(CASE WHEN "FundingType" = 'Locally funded' THEN 1 ELSE 0 END)) AS ratio_pct FROM "schools" WHERE "County" = 'Santa Clara' AND "Charter" = 1	california_schools
WITH target AS ( SELECT s.CDSCode, s.School, s.District, f."Enrollment (K-12)" AS enrollment, CASE WHEN f."Enrollment (K-12)" IS NULL OR f."Enrollment (K-12)" = 0 THEN NULL ELSE CAST(f."FRPM Count (K-12)" AS REAL) * 100.0 / f."Enrollment (K-12)" END AS frpm_pct FROM schools s LEFT JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.FundingType = 'Directly funded' AND s.County = 'Stanislaus' AND s.OpenDate >= '2000-01-01' AND s.OpenDate < '2006-01-01' ), school_sat AS ( SELECT cds, SUM(AvgScrRead * NumTstTakr) * 1.0 / NULLIF(SUM(NumTstTakr), 0) AS sat_read, SUM(AvgScrMath * NumTstTakr) * 1.0 / NULLIF(SUM(NumTstTakr), 0) AS sat_math, SUM(AvgScrWrite * NumTstTakr) * 1.0 / NULLIF(SUM(NumTstTakr), 0) AS sat_write, SUM(NumTstTakr) AS num_test_takers FROM satscores WHERE rtype = 'S' GROUP BY cds ), county_frpm AS ( SELECT SUM("FRPM Count (K-12)") * 100.0 / NULLIF(SUM("Enrollment (K-12)"), 0) AS county_avg_frpm_pct FROM frpm WHERE "County Name" = 'Stanislaus' ), county_sat AS ( SELECT SUM(AvgScrRead * NumTstTakr) * 1.0 / NULLIF(SUM(NumTstTakr), 0) AS county_avg_sat_read, SUM(AvgScrMath * NumTstTakr) * 1.0 / NULLIF(SUM(NumTstTakr), 0) AS county_avg_sat_math, SUM(AvgScrWrite * NumTstTakr) * 1.0 / NULLIF(SUM(NumTstTakr), 0) AS county_avg_sat_write FROM satscores WHERE cname = 'Stanislaus' AND rtype = 'S' ) SELECT t.School, t.District, t.enrollment, t.frpm_pct, st.sat_read, st.sat_math, st.sat_write, cf.county_avg_frpm_pct, cs.county_avg_sat_read, cs.county_avg_sat_math, cs.county_avg_sat_write, RANK() OVER (ORDER BY t.frpm_pct DESC) AS frpm_rank, RANK() OVER (ORDER BY (st.sat_read + st.sat_math + st.sat_write) DESC) AS sat_performance_rank FROM target t LEFT JOIN school_sat st ON t.CDSCode = st.cds CROSS JOIN county_frpm cf CROSS JOIN county_sat cs ORDER BY frpm_rank, sat_performance_rank	california_schools
SELECT COUNT(DISTINCT "CDSCode") AS total_closures FROM "schools" WHERE "DOCType" = 'Community College District' AND "City" = 'San Francisco' AND STRFTIME('%Y', "ClosedDate") = '1989'	california_schools
SELECT County FROM schools WHERE SOC = '11' AND ClosedDate >= '1980-01-01' AND ClosedDate < '1990-01-01' GROUP BY County ORDER BY COUNT(*) DESC LIMIT 1	california_schools
SELECT s.NCESDist AS nces_district_id, s.School AS school_name, s.Charter AS charter_status, s.StatusType AS operational_status, s.OpenDate AS opening_date, f."Enrollment (K-12)" AS enrollment, CASE WHEN f."Percent (%) Eligible FRPM (K-12)" > 0.75 THEN 'High Poverty' WHEN f."Percent (%) Eligible FRPM (K-12)" > 0.50 THEN 'Medium Poverty' WHEN f."Percent (%) Eligible FRPM (K-12)" > 0.25 THEN 'Low Poverty' ELSE 'Very Low Poverty' END AS poverty_classification, t.AvgScrRead AS sat_reading, t.AvgScrMath AS sat_math, t.AvgScrWrite AS sat_writing, (t.AvgScrRead + t.AvgScrMath + t.AvgScrWrite) / 3.0 AS overall_avg_sat, RANK() OVER (ORDER BY f."Enrollment (K-12)" DESC) AS enrollment_ranking FROM schools s LEFT JOIN frpm f ON f.CDSCode = s.CDSCode LEFT JOIN satscores t ON t.cds = s.CDSCode WHERE s.DOCType = 'State Special Schools' AND (s.SOC = '31' OR s.SOC LIKE '3%') ORDER BY f."Enrollment (K-12)" DESC	california_schools
SELECT COUNT(*) AS school_count FROM schools WHERE County = 'Alpine' AND SOCType = 'District Community Day Schools' AND StatusType IN ('Active', 'Closed')	california_schools
SELECT DISTINCT f."District Code" FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.City = 'Fresno' AND s.Magnet = 0	california_schools
SELECT SUM(frpm."Enrollment (Ages 5-17)") AS total_enrolled FROM frpm JOIN schools ON frpm.CDSCode = schools.CDSCode WHERE schools.EdOpsCode = 'SSS' AND schools.City = 'Fremont' AND frpm."Academic Year" = '2014-2015'	california_schools
SELECT frpm."FRPM Count (Ages 5-17)" FROM frpm INNER JOIN schools ON frpm.CDSCode = schools.CDSCode WHERE schools."MailStreet" = 'PO Box 1040' AND schools."EdOpsName" = 'Youth Authority School'	california_schools
SELECT MIN(frpm."Low Grade") AS lowest_grade FROM schools JOIN frpm ON schools.CDSCode = frpm.CDSCode WHERE schools.NCESDist = '0613360' AND schools.EdOpsCode = 'SPECON'	california_schools
SELECT "School Type", "School Name" FROM frpm WHERE "County Code" = '37' AND "NSLP Provision Status" = 'Breakfast Provision 2'	california_schools
SELECT s.City FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode WHERE s.EILCode = 'HS' AND f."NSLP Provision Status" = 'Lunch Provision 2' AND f."Low Grade" = '9' AND f."High Grade" = '12' AND f."County Name" = 'Merced'	california_schools
WITH frpm_calc AS ( SELECT s.CDSCode, s.School, s.Charter, CAST(f."FRPM Count (Ages 5-17)" AS REAL) * 100.0 / f."Enrollment (Ages 5-17)" AS frpm_pct FROM schools s JOIN frpm f ON f.CDSCode = s.CDSCode WHERE s.County = 'Los Angeles' AND s.GSserved = 'K-9' ) SELECT fc.School AS school_name, CASE WHEN fc.frpm_pct >= 75 THEN 'High Poverty' WHEN fc.frpm_pct >= 50 THEN 'Medium Poverty' ELSE 'Low Poverty' END AS poverty_level, fc.frpm_pct AS frpm_percentage, CASE WHEN fc.Charter = 1 THEN 'Yes' ELSE 'No' END AS charter_status, sat.AvgScrRead, sat.AvgScrMath, sat.AvgScrWrite FROM frpm_calc fc LEFT JOIN satscores sat ON sat.cds = fc.CDSCode AND sat.rtype = 'S' ORDER BY fc.frpm_pct DESC	california_schools
WITH target_gs AS ( SELECT "GSserved" AS grade_span_served FROM schools WHERE "City" = 'Adelanto' AND "StatusType" = 'Active' AND "GSserved" IS NOT NULL GROUP BY "GSserved" ORDER BY COUNT(*) DESC, "GSserved" LIMIT 1 ) SELECT t.grade_span_served, AVG(f."Enrollment (K-12)") AS avg_enrollment_k12, AVG(f."FRPM Count (K-12)") AS avg_frpm_count_k12, AVG(f."Percent (%) Eligible FRPM (K-12)") * 100 AS avg_frpm_percent, CASE WHEN AVG(f."Percent (%) Eligible FRPM (K-12)") * 100 > 75 THEN 'High' WHEN AVG(f."Percent (%) Eligible FRPM (K-12)") * 100 >= 50 THEN 'Medium' ELSE 'Low' END AS poverty_level, SUM(s."AvgScrRead" * s."NumTstTakr") * 1.0 / NULLIF(SUM(s."NumTstTakr"), 0) AS avg_sat_read, SUM(s."AvgScrMath" * s."NumTstTakr") * 1.0 / NULLIF(SUM(s."NumTstTakr"), 0) AS avg_sat_math, SUM(s."AvgScrWrite" * s."NumTstTakr") * 1.0 / NULLIF(SUM(s."NumTstTakr"), 0) AS avg_sat_write FROM target_gs t JOIN schools sc ON sc."GSserved" = t.grade_span_served AND sc."City" = 'Adelanto' AND sc."StatusType" = 'Active' LEFT JOIN frpm f ON f.CDSCode = sc.CDSCode LEFT JOIN satscores s ON s.cds = sc.CDSCode GROUP BY t.grade_span_served	california_schools
SELECT v.School FROM virtual_schools v ORDER BY v.enrollment DESC LIMIT 1 ) AS largest_virtual_school FROM county_stats cs ORDER BY cs.virtual_school_count DESC LIMIT 1	california_schools
SELECT s.School, f."School Type", s.Latitude FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode ORDER BY s.Latitude DESC LIMIT 1	california_schools
SELECT s.City, f."Low Grade", s.School FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.State = 'CA' AND s.Latitude IS NOT NULL ORDER BY s.Latitude ASC LIMIT 1	california_schools
SELECT GSoffered FROM schools WHERE ABS(Longitude) = (SELECT MAX(ABS(Longitude)) FROM schools) AND School IS NOT NULL	california_schools
WITH city_school_counts AS ( SELECT s.City AS City, COUNT(*) AS School_Count FROM schools s WHERE s.GSserved = 'K-8' AND s.City IS NOT NULL GROUP BY s.City ), magnet_multiple_provision AS ( SELECT COUNT(*) AS Magnet_K8_MultipleProvision_Count FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.Magnet = 1 AND s.GSserved = 'K-8' AND f."NSLP Provision Status" = 'Multiple Provision Types' ) SELECT csc.City, csc.School_Count, (SELECT Magnet_K8_MultipleProvision_Count FROM magnet_multiple_provision) AS Magnet_K8_MultipleProvision_Count, (SELECT COUNT(*) FROM city_school_counts) AS Number_Of_Cities FROM city_school_counts csc ORDER BY csc.City	california_schools
WITH admin_names AS ( SELECT "AdmFName1" AS first_name, "District" AS district FROM schools WHERE "AdmFName1" IS NOT NULL AND "AdmFName1" <> '' UNION ALL SELECT "AdmFName2", "District" FROM schools WHERE "AdmFName2" IS NOT NULL AND "AdmFName2" <> '' UNION ALL SELECT "AdmFName3", "District" FROM schools WHERE "AdmFName3" IS NOT NULL AND "AdmFName3" <> '' ), top_names AS ( SELECT first_name, COUNT(*) AS cnt FROM admin_names GROUP BY first_name ORDER BY cnt DESC LIMIT 2 ) SELECT DISTINCT a.first_name, a.district FROM admin_names a JOIN top_names t ON a.first_name = t.first_name ORDER BY t.cnt DESC, a.first_name, a.district	california_schools
SELECT (frpm."Free Meal Count (K-12)" * 100.0 / frpm."Enrollment (K-12)") AS "Percent (%) Eligible Free (K-12)", frpm."District Code" FROM schools JOIN frpm ON schools.CDSCode = frpm.CDSCode WHERE schools."AdmFName1" = 'Alusine' OR schools."AdmFName2" = 'Alusine' OR schools."AdmFName3" = 'Alusine'	california_schools
SELECT AdmLName1, District, County, School FROM schools WHERE CAST(CharterNum AS INTEGER) = 40	california_schools
SELECT AdmEmail1 AS email FROM schools WHERE County = 'San Bernardino' AND City = 'San Bernardino' AND DOC = '54' AND SOC = '62' AND OpenDate BETWEEN '2009-01-01' AND '2010-12-31' AND AdmEmail1 IS NOT NULL UNION SELECT AdmEmail2 AS email FROM schools WHERE County = 'San Bernardino' AND City = 'San Bernardino' AND DOC = '54' AND SOC = '62' AND OpenDate BETWEEN '2009-01-01' AND '2010-12-31' AND AdmEmail2 IS NOT NULL UNION SELECT AdmEmail3 AS email FROM schools WHERE County = 'San Bernardino' AND City = 'San Bernardino' AND DOC = '54' AND SOC = '62' AND OpenDate BETWEEN '2009-01-01' AND '2010-12-31' AND AdmEmail3 IS NOT NULL	california_schools
SELECT s.AdmEmail1, s.School FROM satscores AS t INNER JOIN schools AS s ON t.cds = s.CDSCode WHERE t.rtype = 'S' ORDER BY t.NumGE1500 DESC LIMIT 1	california_schools
SELECT COUNT(DISTINCT account.account_id) FROM account JOIN district ON account.district_id = district.district_id WHERE account.frequency = 'POPLATEK PO OBRATU' AND district.A3 = 'east Bohemia'	financial
SELECT COUNT(DISTINCT a.account_id) AS eligible_account_count FROM account a JOIN district d ON a.district_id = d.district_id JOIN loan l ON a.account_id = l.account_id WHERE d.A3 = 'Prague' AND l.status IN ('A','C')	financial
SELECT CASE WHEN AVG(A12) > AVG(A13) THEN '1995' WHEN AVG(A12) < AVG(A13) THEN '1996' ELSE 'same' END AS unemploymant_year_with_higher_average_percentage FROM district	financial
WITH eligible_districts AS ( SELECT d.district_id FROM district d WHERE d.A11 BETWEEN 6000 AND 10000 AND d.district_id IN ( SELECT d2.district_id FROM district d2 WHERE d2.A3 = d.A3 AND d2.A11 BETWEEN 6000 AND 10000 ORDER BY d2.A11 DESC LIMIT 3 ) AND (SELECT COUNT(*) FROM client c WHERE c.district_id = d.district_id AND c.gender = 'F') >= 5 AND EXISTS ( SELECT 1 FROM account a JOIN loan l ON l.account_id = a.account_id WHERE a.district_id = d.district_id AND l.status = 'A' ) ) SELECT COUNT(*) AS female_client_count FROM client c WHERE c.gender = 'F' AND c.district_id IN (SELECT district_id FROM eligible_districts)	financial
SELECT COUNT(*) FROM client JOIN district ON client.district_id = district.district_id WHERE client.gender = 'M' AND district.A3 = 'north Bohemia' AND district.A11 > 8000	financial
SELECT a.account_id, (SELECT MAX(A11) FROM district) - d.A11 AS gap FROM client c JOIN disp dp ON c.client_id = dp.client_id JOIN account a ON dp.account_id = a.account_id JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'F' AND c.birth_date = (SELECT MIN(birth_date) FROM client WHERE gender = 'F') AND d.A11 = ( SELECT MIN(d2.A11) FROM client c2 JOIN district d2 ON c2.district_id = d2.district_id WHERE c2.gender = 'F' AND c2.birth_date = (SELECT MIN(birth_date) FROM client WHERE gender = 'F') )	financial
SELECT d.account_id FROM disp d WHERE d.client_id = ( SELECT c.client_id FROM client c WHERE c.district_id IN ( SELECT di.district_id FROM district di WHERE di.A11 = (SELECT MAX(A11) FROM district) ) ORDER BY c.birth_date DESC LIMIT 1 )	financial
SELECT c.gender, CASE WHEN CAST((julianday(a.date) - julianday(c.birth_date)) / 365.2425 AS INTEGER) < 30 THEN 'Young' WHEN CAST((julianday(a.date) - julianday(c.birth_date)) / 365.2425 AS INTEGER) BETWEEN 30 AND 50 THEN 'Middle-aged' ELSE 'Senior' END AS age_group, dst.A3 AS region, COUNT(DISTINCT c.client_id) AS owner_count, SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END) AS total_income, SUM(CASE WHEN t.type = 'VYDAJ' THEN t.amount ELSE 0 END) AS total_expense, AVG(t.balance) AS avg_balance FROM account a JOIN disp dp ON dp.account_id = a.account_id AND dp.type = 'OWNER' JOIN client c ON c.client_id = dp.client_id JOIN district dst ON dst.district_id = c.district_id JOIN trans t ON t.account_id = a.account_id WHERE a.frequency = 'POPLATEK TYDNE' GROUP BY c.gender, age_group, dst.A3	financial
WITH disps AS ( SELECT d.disp_id, d.client_id, d.account_id FROM disp d JOIN account a ON a.account_id = d.account_id WHERE d.type = 'DISPONENT' AND a.frequency = 'POPLATEK PO OBRATU' ), loan_stats AS ( SELECT l.account_id, COUNT(*) AS loan_count, SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END) AS active_loan_count, SUM(CASE WHEN l.status = 'B' THEN 1 ELSE 0 END) AS completed_loan_count, SUM(l.amount) AS total_loan_amount, SUM(l.payments) AS total_loan_payments FROM loan l GROUP BY l.account_id ), trans_stats AS ( SELECT t.account_id, COUNT(*) AS transaction_count, SUM(t.amount) AS transaction_volume FROM trans t GROUP BY t.account_id ) SELECT c.client_id, c.gender, c.birth_date, MAX(a.frequency) AS service_usage, COALESCE(SUM(ls.loan_count), 0) AS loan_count, COALESCE(SUM(ls.active_loan_count), 0) AS active_loan_count, COALESCE(SUM(ls.completed_loan_count), 0) AS completed_loan_count, COALESCE(SUM(ls.total_loan_amount), 0) AS total_loan_amount, COALESCE(SUM(ls.total_loan_payments), 0) AS total_loan_payments, COALESCE(SUM(ts.transaction_count), 0) AS transaction_count, COALESCE(SUM(ts.transaction_volume), 0) AS transaction_volume, GROUP_CONCAT(DISTINCT crd.type) AS credit_card_type FROM disps d JOIN account a ON a.account_id = d.account_id JOIN client c ON c.client_id = d.client_id LEFT JOIN loan_stats ls ON ls.account_id = d.account_id LEFT JOIN trans_stats ts ON ts.account_id = d.account_id LEFT JOIN card crd ON crd.disp_id = d.disp_id GROUP BY c.client_id, c.gender, c.birth_date ORDER BY transaction_volume DESC	financial
SELECT DISTINCT a.account_id FROM account a JOIN loan l ON a.account_id = l.account_id WHERE substr(l.date, 1, 4) = '1997' AND a.frequency = 'POPLATEK TYDNE' AND l.amount = ( SELECT MIN(l2.amount) FROM loan l2 JOIN account a2 ON a2.account_id = l2.account_id WHERE substr(l2.date, 1, 4) = '1997' AND a2.frequency = 'POPLATEK TYDNE' ) ORDER BY a.account_id	financial
SELECT a.account_id FROM account a JOIN loan l ON a.account_id = l.account_id WHERE l.duration > 12 AND a.date >= '1993-01-01' AND a.date < '1994-01-01' ORDER BY l.amount DESC LIMIT 1	financial
WITH accts AS ( SELECT DISTINCT a.account_id, a.date AS account_date, c.birth_date FROM client c JOIN disp d ON d.client_id = c.client_id AND d.type = 'OWNER' JOIN account a ON a.account_id = d.account_id JOIN district dist ON c.district_id = dist.district_id WHERE c.gender = 'F' AND c.birth_date < '1950-01-01' AND dist.A2 = 'Sokolov' ), loan_agg AS ( SELECT l.account_id, COUNT(*) AS total_loans, SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END) AS completed_loans, SUM(CASE WHEN l.status = 'D' THEN 1 ELSE 0 END) AS debt_loans FROM loan l GROUP BY l.account_id ) SELECT AVG((julianday(a.account_date) - julianday(a.birth_date)) / 365.25) AS avg_age_at_opening, SUM(COALESCE(l.total_loans, 0)) AS total_loans, SUM(COALESCE(l.completed_loans, 0)) AS completed_loans, SUM(COALESCE(l.debt_loans, 0)) AS debt_loans, MIN(STRFTIME('%Y', a.account_date)) AS earliest_year, MAX(STRFTIME('%Y', a.account_date)) AS latest_year FROM accts a LEFT JOIN loan_agg l ON l.account_id = a.account_id	financial
SELECT DISTINCT trans.account_id FROM trans WHERE trans.date = (SELECT MIN(trans.date) FROM trans WHERE trans.date >= '1995-01-01' AND trans.date < '1996-01-01') ORDER BY trans.account_id	financial
SELECT DISTINCT a.account_id FROM account a JOIN trans t ON a.account_id = t.account_id WHERE a.date < '1997-01-01' AND t.balance > 3000	financial
WITH base AS ( SELECT d.client_id, d.account_id, cl.gender, cl.birth_date, dstr.A2 AS district_name, dstr.A3 AS region, CAST((julianday(c.issued) - julianday(cl.birth_date)) / 365.25 AS INTEGER) AS age_at_issue FROM card c JOIN disp d ON c.disp_id = d.disp_id JOIN client cl ON d.client_id = cl.client_id LEFT JOIN district dstr ON cl.district_id = dstr.district_id WHERE date(c.issued) = '1994-03-03' ), loan_agg AS ( SELECT l.account_id, COUNT(*) AS loan_count, SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END) AS active_loan_count, SUM(l.amount) AS total_loan_amount FROM loan l GROUP BY l.account_id ), trans_agg AS ( SELECT t.account_id, COUNT(*) AS trans_count, SUM(t.amount) AS total_transaction_amount FROM trans t GROUP BY t.account_id ) SELECT b.client_id, b.gender, b.birth_date, b.age_at_issue, CASE WHEN COALESCE(l.loan_count, 0) > 0 AND b.age_at_issue < 30 THEN 'Young borrower' WHEN COALESCE(l.loan_count, 0) > 0 AND b.age_at_issue >= 30 THEN 'Mature borrower' ELSE 'Non-borrower' END AS borrower_category, RANK() OVER (PARTITION BY b.gender ORDER BY b.age_at_issue DESC) AS age_rank_within_gender, b.district_name, b.region, COALESCE(t.trans_count, 0) AS trans_count, COALESCE(t.total_transaction_amount, 0) AS total_transaction_amount, COALESCE(l.loan_count, 0) AS loan_count, COALESCE(l.active_loan_count, 0) AS active_loan_count, COALESCE(l.total_loan_amount, 0) AS total_loan_amount FROM base b LEFT JOIN loan_agg l ON b.account_id = l.account_id LEFT JOIN trans_agg t ON b.account_id = t.account_id ORDER BY b.gender, b.age_at_issue DESC	financial
SELECT date(a.date) AS account_opened_date, CAST(julianday('1998-10-14') - julianday(a.date) AS INTEGER) AS days_open, c.gender AS owner_gender, CAST(strftime('%Y','1998-10-14') AS INTEGER) - CAST(strftime('%Y', c.birth_date) AS INTEGER) - (strftime('%m-%d','1998-10-14') < strftime('%m-%d', c.birth_date)) AS owner_age, (SELECT COUNT(*) FROM trans t WHERE t.account_id=a.account_id AND date(t.date) <= '1998-10-14') AS total_transactions_up_to_date, (SELECT COUNT(*) FROM card cd JOIN disp dd ON cd.disp_id=dd.disp_id WHERE dd.account_id=a.account_id) AS cards_issued, CASE WHEN EXISTS (SELECT 1 FROM loan l WHERE l.account_id=a.account_id AND date(l.date) < '1998-10-14') THEN 1 ELSE 0 END AS had_loan_before FROM account a JOIN disp d ON d.account_id=a.account_id AND d.type='OWNER' JOIN client c ON c.client_id=d.client_id WHERE a.account_id = (SELECT t.account_id FROM trans t WHERE t.amount=840 AND date(t.date)='1998-10-14' LIMIT 1)	financial
WITH dr AS ( SELECT district_id, A2, A3, RANK() OVER (ORDER BY A11 DESC) AS avg_salary_rank, RANK() OVER (ORDER BY A12 ASC) AS unemployment_rank FROM district ) SELECT dr.A2 AS district_name, dr.A3 AS region, dr.avg_salary_rank, dr.unemployment_rank, CAST(julianday(l.date) - julianday(a.date) AS INTEGER) AS days_open_before_loan, (SELECT COUNT(*) FROM client c WHERE c.district_id = dr.district_id) AS total_clients, (SELECT COUNT(*) FROM client c WHERE c.district_id = dr.district_id AND c.gender = 'F') AS female_clients, (SELECT COUNT(*) FROM client c WHERE c.district_id = dr.district_id AND c.gender = 'M') AS male_clients, (SELECT AVG((julianday(l.date) - julianday(c.birth_date))/365.25) FROM client c WHERE c.district_id = dr.district_id) AS avg_age, (SELECT COUNT(*) FROM trans t WHERE t.account_id = l.account_id AND t.date < l.date) AS transaction_count, (SELECT SUM(t.amount) FROM trans t WHERE t.account_id = l.account_id AND t.date < l.date AND t.type = 'PRIJEM') AS total_income FROM loan l JOIN account a ON a.account_id = l.account_id JOIN dr ON dr.district_id = a.district_id WHERE l.date = '1994-08-25'	financial
WITH target AS ( SELECT d.client_id, d.account_id FROM card c JOIN disp d ON d.disp_id = c.disp_id WHERE date(c.issued) = '1996-10-21' ), largest_txn AS ( SELECT t.* FROM trans t JOIN target tg ON tg.account_id = t.account_id ORDER BY t.amount DESC, t.trans_id ASC LIMIT 1 ) SELECT lt.trans_id, lt.account_id AS transaction_account_id, lt.date AS transaction_date, lt.type AS transaction_type, lt.operation, lt.amount AS max_amount, lt.balance, lt.k_symbol AS transaction_k_symbol, lt.bank AS transaction_bank, lt.account AS transaction_counter_account, cl.client_id, cl.gender, cl.birth_date, dt.district_id, dt.A2 AS district_name, dt.A3 AS region, dt.A4, dt.A5, dt.A6, dt.A7, dt.A8, dt.A9, dt.A10, dt.A11, dt.A12, dt.A13, dt.A14, dt.A15, dt.A16, l.loan_id, l.account_id AS loan_account_id, l.date AS loan_date, l.amount AS loan_amount, l.duration, l.payments, l.status AS loan_status, o.order_id, o.account_id AS order_account_id, o.bank_to, o.account_to, o.amount AS order_amount, o.k_symbol AS order_k_symbol FROM largest_txn lt JOIN target tg ON tg.account_id = lt.account_id JOIN client cl ON cl.client_id = tg.client_id JOIN district dt ON dt.district_id = cl.district_id LEFT JOIN loan l ON l.account_id = tg.account_id LEFT JOIN "order" o ON o.account_id = tg.account_id	financial
SELECT c.gender FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE d.type = 'OWNER' AND a.district_id = ( SELECT district_id FROM district ORDER BY A11 DESC LIMIT 1 ) ORDER BY c.birth_date ASC LIMIT 1	financial
SELECT t.amount FROM loan l JOIN account a ON a.account_id = l.account_id JOIN trans t ON t.account_id = l.account_id WHERE l.loan_id = ( SELECT loan_id FROM loan ORDER BY amount DESC, loan_id ASC LIMIT 1 ) AND t.date > a.date ORDER BY t.date ASC, t.trans_id ASC LIMIT 1	financial
SELECT COUNT(DISTINCT c.client_id) AS women_clients_count FROM client c JOIN disp d ON d.client_id = c.client_id JOIN account a ON a.account_id = d.account_id JOIN district dist ON dist.district_id = a.district_id WHERE c.gender = 'F' AND d.type = 'OWNER' AND dist.A2 = 'Jesenik'	financial
SELECT DISTINCT d.disp_id FROM trans t JOIN disp d ON d.account_id = t.account_id WHERE t.amount = 5100 AND t.date LIKE '1998-09-02%'	financial
WITH accts AS ( SELECT a.account_id, a.date FROM account a JOIN district d ON d.district_id = a.district_id WHERE d.A2 = 'Litomerice' AND a.date >= '1996-01-01' AND a.date < '1997-01-01' ) SELECT (SELECT COUNT(*) FROM accts) AS total_accounts, (SELECT COUNT(DISTINCT c.client_id) FROM accts a JOIN disp di ON di.account_id = a.account_id JOIN client c ON c.client_id = di.client_id) AS total_clients, (SELECT COUNT(DISTINCT c.client_id) FROM accts a JOIN disp di ON di.account_id = a.account_id JOIN client c ON c.client_id = di.client_id WHERE c.gender = 'F') AS female_clients, (SELECT COUNT(DISTINCT c.client_id) FROM accts a JOIN disp di ON di.account_id = a.account_id JOIN client c ON c.client_id = di.client_id WHERE c.gender = 'M') AS male_clients, (SELECT AVG(1996 - CAST(STRFTIME('%Y', u.birth_date) AS REAL)) FROM ( SELECT DISTINCT c.client_id, c.birth_date FROM accts a JOIN disp di ON di.account_id = a.account_id JOIN client c ON c.client_id = di.client_id ) u) AS avg_age, (SELECT COALESCE(SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END), 0) FROM accts a JOIN trans t ON t.account_id = a.account_id) AS deposits, (SELECT COALESCE(SUM(CASE WHEN t.type = 'VYDAJ' THEN t.amount ELSE 0 END), 0) FROM accts a JOIN trans t ON t.account_id = a.account_id) AS withdrawals, (SELECT COALESCE(SUM(l.amount), 0) FROM accts a JOIN loan l ON l.account_id = a.account_id) AS total_loan_amount, (SELECT COUNT(*) FROM accts a JOIN loan l ON l.account_id = a.account_id WHERE l.status = 'A') AS good_loans, (SELECT COUNT(*) FROM accts a JOIN loan l ON l.account_id = a.account_id WHERE l.status = 'B') AS bad_loans, (SELECT COUNT(*) FROM accts WHERE STRFTIME('%m', date) IN ('01','02','03')) AS q1_accounts, (SELECT COUNT(*) FROM accts WHERE STRFTIME('%m', date) IN ('04','05','06')) AS q2_accounts, (SELECT COUNT(*) FROM accts WHERE STRFTIME('%m', date) IN ('07','08','09')) AS q3_accounts, (SELECT COUNT(*) FROM accts WHERE STRFTIME('%m', date) IN ('10','11','12')) AS q4_accounts	financial
SELECT a.account_id, d.A2 AS account_district_name, d.A3 AS account_region, a.frequency AS account_frequency, (SELECT COUNT(*) FROM trans t WHERE t.account_id = a.account_id AND t.type = 'PRIJEM') AS incoming_count, (SELECT COALESCE(SUM(t.amount), 0) FROM trans t WHERE t.account_id = a.account_id AND t.type = 'PRIJEM') AS incoming_total, (SELECT COUNT(*) FROM trans t WHERE t.account_id = a.account_id AND t.type = 'VYDAJ') AS outgoing_count, (SELECT COALESCE(SUM(t.amount), 0) FROM trans t WHERE t.account_id = a.account_id AND t.type = 'VYDAJ') AS outgoing_total, (SELECT COUNT(*) FROM card c JOIN disp dc ON c.disp_id = dc.disp_id WHERE dc.account_id = a.account_id) AS card_count, (SELECT COUNT(*) FROM loan l WHERE l.account_id = a.account_id) AS loan_count, (SELECT COUNT(*) FROM "order" o WHERE o.account_id = a.account_id) AS order_count, d.A10 AS urban_population_ratio, d.A11 AS avg_salary, d.A12 AS unemployment_rate_1995, d.A13 AS unemployment_rate_1996, d.A14 AS entrepreneurs_per_1000, d.A15 AS crimes_1995, d.A16 AS crimes_1996 FROM disp dp JOIN account a ON a.account_id = dp.account_id JOIN district d ON d.district_id = a.district_id WHERE dp.client_id = ( SELECT client_id FROM client WHERE gender = 'F' AND birth_date = '1976-01-29' ) AND dp.type = 'OWNER' ORDER BY a.account_id	financial
WITH target AS ( SELECT l.*, dp.disp_id, dp.client_id FROM loan l JOIN disp dp ON dp.account_id = l.account_id AND dp.type = 'OWNER' WHERE l.amount = 98832 AND l.date = '1996-01-03' ) SELECT c.birth_date AS birthday, CAST((julianday(tgt.date) - julianday(c.birth_date)) / 365.25 AS INTEGER) AS age_at_loan_application, d.A2 AS location, (SELECT COUNT(*) FROM trans t WHERE t.account_id = tgt.account_id AND t.date < tgt.date) AS transaction_count_before_loan, ROUND( (SELECT SUM(CASE WHEN t.type = 'VYDAJ' THEN t.amount ELSE 0 END) * 100.0 / NULLIF(SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END), 0) FROM trans t WHERE t.account_id = tgt.account_id AND t.date < tgt.date), 2) AS expense_to_income_ratio_pct, (SELECT MIN(t.balance) FROM trans t WHERE t.account_id = tgt.account_id AND t.date < tgt.date) AS min_balance, (SELECT MAX(t.balance) FROM trans t WHERE t.account_id = tgt.account_id AND t.date < tgt.date) AS max_balance, cd.type AS credit_card_type, cd.issued AS credit_card_issued, (SELECT COUNT(*) FROM loan l2 WHERE l2.date < tgt.date AND l2.account_id IN (SELECT di.account_id FROM disp di WHERE di.client_id = tgt.client_id) ) AS previous_loan_count FROM target tgt JOIN client c ON c.client_id = tgt.client_id LEFT JOIN district d ON d.district_id = c.district_id LEFT JOIN card cd ON cd.disp_id = tgt.disp_id	financial
SELECT account.account_id FROM account JOIN district ON account.district_id = district.district_id WHERE district.A3 = 'Prague' ORDER BY account.date ASC LIMIT 1	financial
SELECT d.A2 AS district_name, d.A4 AS number_of_inhabitants, COUNT(c.client_id) AS total_clients, SUM(CASE WHEN c.gender = 'M' THEN 1 ELSE 0 END) AS male_clients, CAST(SUM(CASE WHEN c.gender = 'M' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(c.client_id) AS percentage_male_clients FROM district d JOIN client c ON c.district_id = d.district_id WHERE d.A3 = 'south Bohemia' GROUP BY d.district_id, d.A2, d.A4 ORDER BY d.A4 DESC LIMIT 1	financial
WITH target_account AS ( SELECT account_id FROM loan WHERE substr(date, 1, 10) = '1993-07-05' ORDER BY loan_id LIMIT 1 ), start_balance AS ( SELECT balance FROM trans WHERE account_id = (SELECT account_id FROM target_account) AND substr(date, 1, 10) <= '1993-03-22' ORDER BY date DESC, trans_id DESC LIMIT 1 ), end_balance AS ( SELECT balance FROM trans WHERE account_id = (SELECT account_id FROM target_account) AND substr(date, 1, 10) <= '1998-12-27' ORDER BY date DESC, trans_id DESC LIMIT 1 ) SELECT CAST((end_balance.balance - start_balance.balance) AS REAL) * 100.0 / start_balance.balance AS increase_rate FROM start_balance, end_balance	financial
SELECT d.A3 AS region, 100.0 * SUM(CASE WHEN l.status = 'A' THEN l.amount ELSE 0 END) / SUM(l.amount) AS pct_amount_fully_paid, 100.0 * COUNT(CASE WHEN l.status = 'A' THEN 1 END) / COUNT(*) AS pct_loans_completed, AVG(CASE WHEN l.status = 'A' THEN l.payments * l.duration - l.amount END) AS avg_interest_successful, AVG(l.payments * l.duration - l.amount) AS avg_interest_all FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id GROUP BY d.A3 ORDER BY d.A3	financial
WITH under_loans AS ( SELECT l.loan_id, l.amount, l.status, d.A3 AS region, CASE WHEN l.amount < 50000 THEN 'Small' ELSE 'Medium' END AS loan_size_category FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.amount < 100000 ), overall AS ( SELECT 100.0 * SUM(CASE WHEN status = 'C' THEN 1 ELSE 0 END) / COUNT(*) AS overall_pct FROM under_loans ) SELECT u.region, u.loan_size_category, 100.0 * SUM(CASE WHEN u.status = 'C' THEN 1 ELSE 0 END) / COUNT(*) AS pct_running_no_issues, o.overall_pct AS overall_pct_running_no_issues, 100.0 * SUM(CASE WHEN u.status = 'C' THEN 1 ELSE 0 END) / COUNT(*) - o.overall_pct AS diff_from_overall_pct FROM under_loans u CROSS JOIN overall o GROUP BY u.region, u.loan_size_category, o.overall_pct ORDER BY u.region, u.loan_size_category	financial
WITH base_accounts AS ( SELECT account_id, district_id FROM account WHERE frequency = 'POPLATEK PO OBRATU' AND substr(date, 1, 4) = '1993' ), district_list AS ( SELECT DISTINCT district_id FROM base_accounts ), txn AS ( SELECT b.district_id, COUNT(t.trans_id) AS transaction_count, SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END) AS total_income, SUM(CASE WHEN t.type = 'VYDAJ' THEN t.amount ELSE 0 END) AS total_expense FROM base_accounts b JOIN trans t ON t.account_id = b.account_id GROUP BY b.district_id ), client_agg AS ( SELECT b.district_id, COUNT(DISTINCT c.client_id) AS client_count, COUNT(DISTINCT CASE WHEN c.gender = 'M' THEN c.client_id END) AS male_client_count, COUNT(DISTINCT CASE WHEN c.gender = 'F' THEN c.client_id END) AS female_client_count FROM base_accounts b JOIN disp d ON d.account_id = b.account_id JOIN client c ON c.client_id = d.client_id GROUP BY b.district_id ), loan_agg AS ( SELECT b.district_id, COUNT(l.loan_id) AS loan_count, SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END) AS running_loan_count, SUM(CASE WHEN l.status = 'B' THEN 1 ELSE 0 END) AS finished_loan_count, SUM(CASE WHEN l.status = 'C' THEN 1 ELSE 0 END) AS defaulted_loan_count FROM base_accounts b JOIN loan l ON l.account_id = b.account_id GROUP BY b.district_id ) SELECT d.A2 AS district_name, d.A3 AS region, d.A10 AS urban_ratio, COALESCE(t.transaction_count, 0) AS transaction_count, COALESCE(t.total_income, 0) AS total_income, COALESCE(t.total_expense, 0) AS total_expense, COALESCE(c.client_count, 0) AS client_count, COALESCE(c.male_client_count, 0) AS male_client_count, COALESCE(c.female_client_count, 0) AS female_client_count, COALESCE(l.loan_count, 0) AS loan_count, COALESCE(l.running_loan_count, 0) AS running_loan_count, COALESCE(l.finished_loan_count, 0) AS finished_loan_count, COALESCE(l.defaulted_loan_count, 0) AS defaulted_loan_count, CASE WHEN COALESCE(l.loan_count, 0) = 0 THEN 0.0 ELSE ROUND(100.0 * COALESCE(l.defaulted_loan_count, 0) / COALESCE(l.loan_count, 0), 2) END AS default_rate FROM district_list dl JOIN district d ON d.district_id = dl.district_id LEFT JOIN txn t ON t.district_id = dl.district_id LEFT JOIN client_agg c ON c.district_id = dl.district_id LEFT JOIN loan_agg l ON l.district_id = dl.district_id ORDER BY d.A2	financial
SELECT DISTINCT account.account_id, account.frequency FROM account JOIN disp ON disp.account_id = account.account_id JOIN client ON client.client_id = disp.client_id JOIN district ON client.district_id = district.district_id WHERE disp.type = 'OWNER' AND district.A3 = 'east Bohemia' AND account.date >= '1995-01-01' AND account.date < '2001-01-01'	financial
WITH acct AS ( SELECT a.account_id, d.A2 AS district_name, a.date AS account_opened_date, a.frequency AS account_frequency FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Prachatice' ), owner_demographics AS ( SELECT di.account_id, c.gender AS owner_gender, c.birth_date AS owner_birth_date FROM disp di JOIN client c ON di.client_id = c.client_id WHERE di.type = 'OWNER' ), txn_stats AS ( SELECT account_id, SUM(CASE WHEN type = 'PRIJEM' THEN amount ELSE 0 END) AS total_income, SUM(CASE WHEN type = 'VYDAJ' THEN amount ELSE 0 END) AS total_expense, COUNT(trans_id) AS transaction_count FROM trans GROUP BY account_id ), loan_stats AS ( SELECT account_id, COUNT(loan_id) AS loan_count, SUM(amount) AS total_loan_amount FROM loan GROUP BY account_id ) SELECT acct.account_id, acct.district_name, acct.account_opened_date, acct.account_frequency, od.owner_gender, od.owner_birth_date, COALESCE(ts.total_income, 0) AS total_income, COALESCE(ts.total_expense, 0) AS total_expense, COALESCE(ts.total_income, 0) - COALESCE(ts.total_expense, 0) AS net_balance, COALESCE(ts.transaction_count, 0) AS transaction_count, COALESCE(ls.loan_count, 0) AS loan_count, COALESCE(ls.total_loan_amount, 0) AS total_loan_amount, CASE WHEN COALESCE(ls.loan_count, 0) > 0 AND COALESCE(ts.transaction_count, 0) > 10 THEN 'High Activity' WHEN COALESCE(ls.loan_count, 0) > 0 THEN 'Loan Customer' WHEN COALESCE(ts.transaction_count, 0) > 10 THEN 'Active Customer' ELSE 'Regular Customer' END AS customer_category FROM acct LEFT JOIN owner_demographics od ON acct.account_id = od.account_id LEFT JOIN txn_stats ts ON acct.account_id = ts.account_id LEFT JOIN loan_stats ls ON acct.account_id = ls.account_id ORDER BY net_balance DESC	financial
WITH target AS ( SELECT l.loan_id, l.account_id, l.date AS loan_date, l.amount, l.duration, l.payments, l.status, a.district_id FROM loan l JOIN account a ON a.account_id = l.account_id WHERE l.loan_id = 4990 ) SELECT t.loan_id, c.gender, c.birth_date, t.loan_date, t.amount, t.duration, t.payments, CASE t.status WHEN 'A' THEN 'Running - OK' WHEN 'B' THEN 'Running - Issues' WHEN 'C' THEN 'Finished - No Issues' WHEN 'D' THEN 'Finished - Issues' ELSE t.status END AS status_description, d.A2 AS district_name, d.A3 AS region, d.A11 AS average_salary, d.A12 AS unemployment_rate_1995, ( SELECT COUNT(*) + 1 FROM loan l2 JOIN account a2 ON a2.account_id = l2.account_id WHERE a2.district_id = t.district_id AND l2.loan_id <> 4990 AND l2.amount > t.amount ) AS district_loan_rank FROM target t JOIN disp dp ON dp.account_id = t.account_id AND dp.type = 'OWNER' JOIN client c ON c.client_id = dp.client_id JOIN district d ON d.district_id = t.district_id	financial
WITH tx_stats AS ( SELECT account_id, COUNT(*) AS transaction_count, SUM(CASE WHEN type = 'PRIJEM' THEN amount ELSE 0 END) AS total_income, SUM(CASE WHEN type = 'VYDAJ' THEN amount ELSE 0 END) AS total_expense FROM trans GROUP BY account_id ), all_loan_ranks AS ( SELECT a.account_id, d.A3 AS region, MAX(l.amount) AS max_loan_amount, RANK() OVER (PARTITION BY d.A3 ORDER BY MAX(l.amount) DESC) AS region_loan_rank FROM account a JOIN district d ON d.district_id = a.district_id JOIN loan l ON l.account_id = a.account_id GROUP BY a.account_id, d.A3 ), candidates AS ( SELECT a.account_id, d.A2 AS district, d.A3 AS region, l.amount AS loan_amount, l.duration AS loan_duration, l.payments AS loan_payments, l.status AS loan_status, c.gender, c.birth_date, CASE WHEN COALESCE(tx.total_income, 0) > 1000000 THEN 'High Income' WHEN COALESCE(tx.total_income, 0) > 500000 THEN 'Medium Income' ELSE 'Low Income' END AS income_classification, COALESCE(tx.transaction_count, 0) AS transaction_count, CASE WHEN tx.total_income IS NULL OR tx.total_income = 0 THEN NULL ELSE CAST(tx.total_income - tx.total_expense AS REAL) / tx.total_income END AS savings_ratio, alr.region_loan_rank FROM account a JOIN district d ON d.district_id = a.district_id JOIN loan l ON l.account_id = a.account_id JOIN all_loan_ranks alr ON alr.account_id = a.account_id JOIN disp dp ON dp.account_id = a.account_id AND dp.type = 'OWNER' JOIN client c ON c.client_id = dp.client_id LEFT JOIN tx_stats tx ON tx.account_id = a.account_id WHERE l.amount > 300000 AND d.A11 > (SELECT AVG(A11) FROM district) AND (tx.account_id IS NULL OR tx.total_income - tx.total_expense > 0) ) SELECT account_id, district, region, loan_amount, loan_duration, loan_payments, loan_status, gender, birth_date, income_classification, transaction_count, savings_ratio, region_loan_rank FROM candidates ORDER BY loan_amount DESC LIMIT 100	financial
WITH ranked AS ( SELECT l.loan_id, l.account_id, l.date AS loan_date, l.amount, l.duration, l.payments, l.status, a.district_id, ROW_NUMBER() OVER ( PARTITION BY a.district_id ORDER BY l.amount DESC, l.loan_id ASC ) AS rn FROM loan AS l JOIN account AS a ON l.account_id = a.account_id WHERE l.duration = 60 ) SELECT d.A2 AS district_name, d.A11 AS average_salary, r.loan_id, r.loan_date, r.amount AS loan_amount, r.duration AS loan_duration_months, r.payments AS monthly_payment, r.status AS loan_status, c.gender AS client_gender, c.birth_date AS client_birth_date, t.date AS transaction_date, t.amount AS transaction_amount, (r.payments * r.duration - r.amount) * 100.0 / r.amount AS interest_rate FROM ranked AS r JOIN district AS d ON d.district_id = r.district_id JOIN disp AS dp ON dp.account_id = r.account_id AND dp.type = 'OWNER' JOIN client AS c ON c.client_id = dp.client_id LEFT JOIN trans AS t ON t.account_id = r.account_id WHERE r.rn <= 3 ORDER BY d.A11 DESC, r.amount DESC, r.loan_id ASC, t.date ASC	financial
SELECT DISTINCT d.A2 AS district, ((d.A13 - d.A12) / d.A12) * 100 AS unemployment_rate_increment_pct FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.status = 'D'	financial
WITH monthly AS ( SELECT substr(a.date,6,2) AS month, 100.0 * COUNT(DISTINCT CASE WHEN d.A2='Decin' THEN a.account_id END) / COUNT(DISTINCT a.account_id) AS decin_pct, AVG(CASE WHEN t.type='PRIJEM' THEN t.amount END) AS avg_income_amount, AVG(CASE WHEN t.type='VYDAJ' THEN t.amount END) AS avg_expense_amount FROM account a LEFT JOIN district d ON d.district_id = a.district_id LEFT JOIN trans t ON t.account_id = a.account_id WHERE substr(a.date,1,4) = '1993' GROUP BY substr(a.date,6,2) ), yearly AS ( SELECT AVG(decin_pct) AS overall_avg_pct FROM monthly ) SELECT m.month, m.decin_pct AS decin_percentage, m.avg_income_amount, m.avg_expense_amount, CASE WHEN m.decin_pct > y.overall_avg_pct THEN 'above' WHEN m.decin_pct < y.overall_avg_pct THEN 'below' ELSE 'equal' END AS decin_pct_vs_yearly_avg FROM monthly m CROSS JOIN yearly y ORDER BY m.month	financial
WITH monthly_accounts AS ( SELECT account_id FROM account WHERE frequency = 'POPLATEK MESICNE' ), owner_client AS ( SELECT d.account_id, c.gender, c.birth_date, dist.A2 AS client_district_name FROM disp d JOIN client c ON d.client_id = c.client_id LEFT JOIN district dist ON c.district_id = dist.district_id WHERE d.type = 'OWNER' ), trans_agg AS ( SELECT t.account_id, COUNT(*) AS transaction_count, COALESCE(SUM(t.amount), 0) AS transaction_volume, COALESCE(SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END), 0) AS total_income, COALESCE(SUM(CASE WHEN t.type IN ('VYDAJ', 'VYBER') THEN t.amount ELSE 0 END), 0) AS total_expense, COALESCE(SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN t.type IN ('VYDAJ', 'VYBER') THEN t.amount ELSE 0 END), 0) AS net_cash_flow FROM trans t WHERE t.account_id IN (SELECT account_id FROM monthly_accounts) GROUP BY t.account_id ), loan_agg AS ( SELECT l.account_id, COUNT(*) AS loan_count, COALESCE(SUM(l.amount), 0) AS total_loan_amount, COALESCE(AVG(l.amount), 0) AS avg_loan_amount, COALESCE(AVG(l.duration), 0) AS avg_loan_duration, COALESCE(SUM(l.payments), 0) AS total_loan_payments, COALESCE(SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END), 0) AS active_loan_count, COALESCE(SUM(CASE WHEN l.status = 'B' THEN 1 ELSE 0 END), 0) AS completed_loan_count FROM loan l WHERE l.account_id IN (SELECT account_id FROM monthly_accounts) GROUP BY l.account_id ), profile AS ( SELECT ma.account_id, oc.gender, oc.birth_date, oc.client_district_name, COALESCE(ta.transaction_count, 0) AS transaction_count, COALESCE(ta.transaction_volume, 0) AS transaction_volume, COALESCE(ta.total_income, 0) AS total_income, COALESCE(ta.total_expense, 0) AS total_expense, COALESCE(ta.net_cash_flow, 0) AS net_cash_flow, COALESCE(la.loan_count, 0) AS loan_count, COALESCE(la.total_loan_amount, 0) AS total_loan_amount, COALESCE(la.avg_loan_amount, 0) AS avg_loan_amount, COALESCE(la.avg_loan_duration, 0) AS avg_loan_duration, COALESCE(la.total_loan_payments, 0) AS total_loan_payments, COALESCE(la.active_loan_count, 0) AS active_loan_count, COALESCE(la.completed_loan_count, 0) AS completed_loan_count FROM monthly_accounts ma LEFT JOIN owner_client oc ON ma.account_id = oc.account_id LEFT JOIN trans_agg ta ON ma.account_id = ta.account_id LEFT JOIN loan_agg la ON ma.account_id = la.account_id ) SELECT account_id, gender, birth_date, client_district_name, transaction_count, transaction_volume, total_income, total_expense, net_cash_flow, loan_count, total_loan_amount, avg_loan_amount, avg_loan_duration, total_loan_payments, active_loan_count, completed_loan_count, RANK() OVER (ORDER BY transaction_volume DESC) AS transaction_volume_rank, RANK() OVER (ORDER BY net_cash_flow DESC) AS cash_flow_rank FROM profile ORDER BY transaction_volume_rank, cash_flow_rank	financial
SELECT d.A2 AS district, COUNT(c.client_id) AS female_account_holders FROM district d LEFT JOIN client c ON c.district_id = d.district_id AND c.gender = 'F' GROUP BY d.A2 ORDER BY female_account_holders DESC LIMIT 9	financial
SELECT d.A2 AS district_name FROM trans t JOIN account a ON t.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE t.type = 'VYDAJ' AND t.date LIKE '1996-01%' GROUP BY d.A2 ORDER BY SUM(t.amount) DESC LIMIT 10	financial
SELECT COUNT(DISTINCT d.client_id) FROM disp AS d JOIN account AS a ON d.account_id = a.account_id JOIN district AS dis ON a.district_id = dis.district_id WHERE dis.A3 = 'south Bohemia' AND d.type = 'OWNER' AND NOT EXISTS ( SELECT 1 FROM disp AS d2 JOIN card AS c ON c.disp_id = d2.disp_id WHERE d2.client_id = d.client_id )	financial
SELECT d.A3 AS district_name FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.status IN ('C','D') GROUP BY d.district_id, d.A3 ORDER BY COUNT(l.loan_id) DESC LIMIT 1	financial
SELECT AVG(loan.amount) AS avg_loan_amount FROM loan JOIN disp ON loan.account_id = disp.account_id JOIN client ON disp.client_id = client.client_id WHERE client.gender = 'M' AND disp.type = 'OWNER'	financial
SELECT A3 AS branch_location, A2 AS district_name FROM district WHERE A13 = (SELECT MAX(A13) FROM district)	financial
SELECT d.A2 AS district_name, d.A3 AS region, d.A4 AS population, d.A16 AS number_of_crimes_1996, CAST((d.A16 - d.A15) AS REAL) * 100 / d.A15 AS percentage_increase, (SELECT COUNT(*) FROM account a WHERE a.district_id = d.district_id) AS accounts_opened FROM district d WHERE d.district_id = (SELECT district_id FROM district ORDER BY A16 DESC LIMIT 1)	financial
WITH qual_acct AS ( SELECT DISTINCT a.account_id FROM account a JOIN trans t ON t.account_id = a.account_id WHERE a.frequency = 'POPLATEK MESICNE' AND t.operation = 'VYBER KARTOU' AND t.balance < 0 ), card_counts AS ( SELECT q.account_id, COUNT(c.card_id) AS card_count FROM qual_acct q LEFT JOIN disp d ON d.account_id = q.account_id LEFT JOIN card c ON c.disp_id = d.disp_id GROUP BY q.account_id ), owner_info AS ( SELECT d.account_id, c.gender, (julianday('2000-01-01') - julianday(c.birth_date)) / 365.25 AS age FROM disp d JOIN client c ON c.client_id = d.client_id WHERE d.type = 'OWNER' ) SELECT (SELECT AVG(t.balance) FROM trans t JOIN account a ON a.account_id = t.account_id WHERE t.operation = 'VYBER KARTOU' AND t.balance < 0 AND a.frequency = 'POPLATEK MESICNE') AS avg_negative_balance, (SELECT MAX(t.amount) FROM trans t JOIN account a ON a.account_id = t.account_id WHERE t.operation = 'VYBER KARTOU' AND t.balance < 0 AND a.frequency = 'POPLATEK MESICNE') AS max_withdrawal_amount, (SELECT AVG(card_count) FROM card_counts) AS avg_cards_per_account, (SELECT COUNT(c.card_id) FROM card c JOIN disp d ON d.disp_id = c.disp_id WHERE d.account_id IN (SELECT account_id FROM qual_acct) AND c.type = 'gold') AS total_gold_cards, (SELECT AVG(age) FROM owner_info WHERE account_id IN (SELECT account_id FROM qual_acct)) AS avg_owner_age, (SELECT COUNT(*) FROM owner_info WHERE account_id IN (SELECT account_id FROM qual_acct) AND gender = 'F') AS female_owners, (SELECT COUNT(*) FROM owner_info WHERE account_id IN (SELECT account_id FROM qual_acct) AND gender = 'M') AS male_owners	financial
SELECT COUNT(*) AS loan_count FROM loan JOIN account ON loan.account_id = account.account_id WHERE loan.date >= '1995-01-01' AND loan.date < '1998-01-01' AND loan.amount >= 250000 AND account.frequency = 'POPLATEK MESICNE'	financial
WITH target AS ( SELECT a.account_id, d.disp_id, d.client_id FROM account a JOIN disp d ON d.account_id = a.account_id AND d.type = 'OWNER' JOIN loan l ON l.account_id = a.account_id AND l.status IN ('C','D') WHERE a.district_id = 1 ), loan_stats AS ( SELECT AVG(l.amount - l.payments * l.duration) AS avg_remaining_debt FROM target t JOIN loan l ON l.account_id = t.account_id AND l.status IN ('C','D') ), client_stats AS ( SELECT SUM(CASE WHEN c.gender = 'F' THEN 1 ELSE 0 END) AS female_count, SUM(CASE WHEN c.gender = 'M' THEN 1 ELSE 0 END) AS male_count, AVG(CAST(STRFTIME('%Y','now') AS INTEGER) - CAST(STRFTIME('%Y', c.birth_date) AS INTEGER)) AS avg_age FROM target t JOIN client c ON c.client_id = t.client_id ), card_stats AS ( SELECT COUNT(c.card_id) AS card_count FROM target t LEFT JOIN card c ON c.disp_id = t.disp_id ), transaction_stats AS ( SELECT COUNT(tr.trans_id) AS transaction_count FROM target t LEFT JOIN trans tr ON tr.account_id = t.account_id ), latest_balance AS ( SELECT t.account_id, tr.balance, ROW_NUMBER() OVER (PARTITION BY t.account_id ORDER BY tr.date DESC, tr.trans_id DESC) AS rn FROM target t JOIN trans tr ON tr.account_id = t.account_id ), balance_stats AS ( SELECT AVG(balance) AS avg_latest_balance FROM latest_balance WHERE rn = 1 ) SELECT ls.avg_remaining_debt, cs.female_count, cs.male_count, cs.avg_age, cds.card_count, ts.transaction_count, bs.avg_latest_balance FROM loan_stats ls CROSS JOIN client_stats cs CROSS JOIN card_stats cds CROSS JOIN transaction_stats ts CROSS JOIN balance_stats bs	financial
WITH target_district AS ( SELECT district_id, A15 AS crime_count_1995 FROM district ORDER BY A15 DESC LIMIT 1 OFFSET 1 ), male_clients AS ( SELECT c.client_id, c.birth_date FROM client c JOIN target_district t ON c.district_id = t.district_id WHERE c.gender = 'M' ) SELECT (SELECT COUNT(*) FROM male_clients) AS total_male_clients, (SELECT crime_count_1995 FROM target_district) AS crime_count_1995, (SELECT COUNT(DISTINCT d.account_id) FROM disp d WHERE d.client_id IN (SELECT client_id FROM male_clients)) AS total_accounts, (SELECT COUNT(DISTINCT l.loan_id) FROM loan l WHERE l.account_id IN (SELECT d.account_id FROM disp d WHERE d.client_id IN (SELECT client_id FROM male_clients))) AS total_loans, (SELECT COUNT(DISTINCT cd.card_id) FROM card cd WHERE cd.disp_id IN (SELECT d.disp_id FROM disp d WHERE d.client_id IN (SELECT client_id FROM male_clients))) AS total_credit_cards, (SELECT CAST(COUNT(*) AS REAL) / (SELECT COUNT(*) FROM male_clients) FROM disp d WHERE d.client_id IN (SELECT client_id FROM male_clients)) AS avg_dispositions_per_client, (SELECT COUNT(DISTINCT d.client_id) FROM disp d JOIN loan l ON l.account_id = d.account_id WHERE d.client_id IN (SELECT client_id FROM male_clients)) AS clients_with_loans, (SELECT COUNT(*) FROM male_clients WHERE (julianday('now') - julianday(birth_date)) / 365.25 < 30) AS young_under_30, (SELECT COUNT(*) FROM male_clients WHERE (julianday('now') - julianday(birth_date)) / 365.25 BETWEEN 30 AND 50) AS middle_30_50, (SELECT COUNT(*) FROM male_clients WHERE (julianday('now') - julianday(birth_date)) / 365.25 > 50) AS senior_over_50	financial
WITH account_avg AS (SELECT account_id, AVG(balance) AS avg_balance FROM trans GROUP BY account_id HAVING AVG(balance) > 1000), gold_owners AS (SELECT DISTINCT disp.client_id, disp.account_id FROM card JOIN disp ON card.disp_id = disp.disp_id WHERE card.type = 'gold' AND disp.type = 'OWNER') SELECT c.gender AS gender, COUNT(DISTINCT go.client_id) AS number_of_clients, AVG(aa.avg_balance) AS avg_account_balance FROM gold_owners go JOIN account_avg aa ON go.account_id = aa.account_id JOIN client c ON go.client_id = c.client_id GROUP BY c.gender	financial
WITH target AS ( SELECT district_id FROM district WHERE A2 = 'Pisek' ) SELECT (SELECT COUNT(*) FROM account a WHERE a.district_id = target.district_id) AS total_accounts, (SELECT CAST(COUNT(t.trans_id) AS REAL) / NULLIF(COUNT(DISTINCT a.account_id), 0) FROM account a LEFT JOIN trans t ON t.account_id = a.account_id WHERE a.district_id = target.district_id) AS avg_transactions_per_account, (SELECT COALESCE(SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END), 0) FROM account a LEFT JOIN trans t ON t.account_id = a.account_id WHERE a.district_id = target.district_id) AS total_deposits, (SELECT COALESCE(SUM(CASE WHEN t.type = 'VYDAJ' THEN t.amount ELSE 0 END), 0) FROM account a LEFT JOIN trans t ON t.account_id = a.account_id WHERE a.district_id = target.district_id) AS total_withdrawals, (SELECT AVG(x.max_balance) FROM ( SELECT MAX(t.balance) AS max_balance FROM account a LEFT JOIN trans t ON t.account_id = a.account_id WHERE a.district_id = target.district_id GROUP BY a.account_id ) x) AS avg_max_balance, (SELECT COUNT(c.card_id) FROM card c JOIN disp dp ON c.disp_id = dp.disp_id JOIN account a ON dp.account_id = a.account_id WHERE a.district_id = target.district_id) AS total_credit_cards_issued, (SELECT COUNT(l.loan_id) FROM loan l JOIN account a ON l.account_id = a.account_id WHERE a.district_id = target.district_id) AS total_loans_issued, (SELECT CASE WHEN COALESCE(SUM(l.amount), 0) = 0 THEN 0 ELSE CAST(SUM(CASE WHEN l.status = 'A' THEN l.amount ELSE 0 END) AS REAL) * 100.0 / SUM(l.amount) END FROM loan l JOIN account a ON l.account_id = a.account_id WHERE a.district_id = target.district_id) AS active_loan_amount_percentage, (SELECT COUNT(DISTINCT dp.client_id) FROM disp dp JOIN account a ON dp.account_id = a.account_id WHERE a.district_id = target.district_id AND dp.type = 'OWNER') AS unique_account_owners FROM target	financial
SELECT DISTINCT d.A2 AS district_name FROM trans t JOIN account a ON t.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE t.amount > 10000 AND t.date >= '1997-01-01' AND t.date < '1998-01-01' ORDER BY d.A2	financial
SELECT DISTINCT o.account_id FROM "order" AS o JOIN account AS a ON o.account_id = a.account_id JOIN district AS d ON a.district_id = d.district_id WHERE o.k_symbol = 'SIPO' AND d.A2 = 'Pisek' ORDER BY o.account_id	financial
WITH gold_accounts AS ( SELECT d.account_id, COUNT(c.card_id) AS num_gold_cards FROM card c JOIN disp d ON d.disp_id = c.disp_id WHERE c.type = 'gold' GROUP BY d.account_id ), txn_stats AS ( SELECT account_id, SUM(CASE WHEN type = 'PRIJEM' THEN amount ELSE 0 END) AS total_income, SUM(CASE WHEN type = 'VYDAJ' THEN amount ELSE 0 END) AS total_expense, AVG(balance) AS avg_balance FROM trans GROUP BY account_id ), loan_stats AS ( SELECT account_id, COUNT(loan_id) AS num_loans, SUM(CASE WHEN status = 'A' THEN 1 ELSE 0 END) AS good_loans, SUM(CASE WHEN status = 'B' THEN 1 ELSE 0 END) AS bad_loans FROM loan GROUP BY account_id ) SELECT ga.account_id, ga.num_gold_cards, di.A2 AS district_name, di.A3 AS region, COALESCE(t.total_income, 0) AS total_income, COALESCE(t.total_expense, 0) AS total_expense, t.avg_balance, COALESCE(l.num_loans, 0) AS num_loans, COALESCE(l.good_loans, 0) AS good_loans, COALESCE(l.bad_loans, 0) AS bad_loans, RANK() OVER (ORDER BY t.avg_balance DESC) AS balance_rank FROM gold_accounts ga LEFT JOIN account a ON a.account_id = ga.account_id LEFT JOIN district di ON di.district_id = a.district_id LEFT JOIN txn_stats t ON t.account_id = ga.account_id LEFT JOIN loan_stats l ON l.account_id = ga.account_id ORDER BY balance_rank	financial
SELECT d.A3 AS region, d.A2 AS district, c.gender AS gender, cd.type AS card_type, AVG(t.amount) AS avg_transaction_amount, SUM(t.amount) AS total_spending, d.A11 AS district_avg_salary, CAST(SUM(t.amount) AS REAL) / d.A11 AS total_spending_vs_salary_ratio FROM trans t JOIN account a ON t.account_id = a.account_id JOIN district d ON a.district_id = d.district_id JOIN disp dp ON dp.account_id = a.account_id AND dp.type = 'OWNER' JOIN client c ON c.client_id = dp.client_id JOIN card cd ON cd.disp_id = dp.disp_id WHERE t.operation = 'VYBER KARTOU' AND substr(t.date, 1, 4) = '1998' GROUP BY d.district_id, d.A3, d.A2, d.A11, c.gender, cd.type ORDER BY d.A3, d.A2, c.gender, cd.type	financial
SELECT DISTINCT d.client_id FROM disp d JOIN trans t ON d.account_id = t.account_id WHERE d.type = 'OWNER' AND t.operation = 'VYBER KARTOU' AND t.date >= '1998-01-01' AND t.date < '1999-01-01' AND t.amount < ( SELECT AVG(t2.amount) FROM trans t2 WHERE t2.operation = 'VYBER KARTOU' AND t2.date >= '1998-01-01' AND t2.date < '1999-01-01' )	financial
WITH adult_female AS ( SELECT client_id, district_id FROM client WHERE gender = 'F' AND birth_date <= date('now', '-18 years') ), card_owners AS ( SELECT c.client_id, c.district_id, MAX(ca.type) AS card_type, MAX(ca.issued) AS card_issued FROM adult_female c JOIN disp d ON d.client_id = c.client_id AND d.type = 'OWNER' JOIN card ca ON ca.disp_id = d.disp_id GROUP BY c.client_id, c.district_id ), loan_agg AS ( SELECT ld.client_id, SUM(l.amount) AS total_loan_amount, GROUP_CONCAT(DISTINCT CASE l.status WHEN 'A' THEN 'Good Standing' WHEN 'B' THEN 'Default' WHEN 'C' THEN 'Running OK' WHEN 'D' THEN 'Client in debt' ELSE l.status END, ', ') AS loan_status FROM (SELECT DISTINCT client_id, account_id FROM disp) ld JOIN loan l ON l.account_id = ld.account_id WHERE ld.client_id IN (SELECT client_id FROM card_owners) GROUP BY ld.client_id ), trans_agg AS ( SELECT ld.client_id, COUNT(t.trans_id) AS transaction_count, SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END) AS total_income, SUM(CASE WHEN t.type IN ('VYDAJ', 'VYBER') THEN t.amount ELSE 0 END) AS total_expense FROM (SELECT DISTINCT client_id, account_id FROM disp) ld LEFT JOIN trans t ON t.account_id = ld.account_id WHERE ld.client_id IN (SELECT client_id FROM card_owners) GROUP BY ld.client_id ), ranked AS ( SELECT co.client_id, co.card_type, co.card_issued, la.loan_status, COALESCE(ta.transaction_count, 0) AS transaction_count, COALESCE(ta.total_income, 0) AS total_income, COALESCE(ta.total_expense, 0) AS total_expense, CASE WHEN COALESCE(ta.total_income, 0) = 0 THEN NULL ELSE (COALESCE(ta.total_income, 0) - COALESCE(ta.total_expense, 0)) * 100.0 / COALESCE(ta.total_income, 0) END AS savings_rate, RANK() OVER ( PARTITION BY COALESCE(dr.A3, CAST(co.district_id AS TEXT)) ORDER BY la.total_loan_amount DESC ) AS regional_loan_rank, la.total_loan_amount FROM card_owners co JOIN loan_agg la ON la.client_id = co.client_id LEFT JOIN trans_agg ta ON ta.client_id = co.client_id LEFT JOIN district dr ON dr.district_id = co.district_id ) SELECT client_id, card_type, card_issued, loan_status, transaction_count, total_income, total_expense, savings_rate, regional_loan_rank FROM ranked ORDER BY total_loan_amount DESC LIMIT 100	financial
WITH owner_accounts AS ( SELECT c.client_id, c.birth_date, d.district_id, d.A2 AS district_name, dp.account_id FROM client c JOIN disp dp ON dp.client_id = c.client_id JOIN district d ON d.district_id = c.district_id WHERE c.gender = 'F' AND d.A3 = 'south Bohemia' AND dp.type = 'OWNER' ), tx_agg AS ( SELECT account_id, COUNT(trans_id) AS transaction_count, SUM(CASE WHEN type = 'PRIJEM' THEN amount ELSE 0 END) AS total_income, SUM(CASE WHEN type = 'VYDAJ' THEN amount ELSE 0 END) AS total_expense FROM trans GROUP BY account_id ), loan_agg AS ( SELECT account_id, SUM(amount) AS total_loan_amount, COUNT(loan_id) AS loan_count, SUM(CASE WHEN status = 'A' THEN 1 ELSE 0 END) AS active_loan_count FROM loan GROUP BY account_id ) SELECT o.district_name, CASE WHEN o.birth_date > '1980-12-31' THEN 'Young' WHEN o.birth_date >= '1960-01-01' THEN 'Middle-aged' ELSE 'Senior' END AS age_group, AVG(COALESCE(tx.transaction_count, 0)) AS avg_transaction_activity, SUM(COALESCE(tx.total_income, 0)) - SUM(COALESCE(tx.total_expense, 0)) AS net_balance, CASE WHEN COALESCE(SUM(l.loan_count), 0) = 0 THEN 0 ELSE CAST(COALESCE(SUM(l.total_loan_amount), 0) AS REAL) / SUM(l.loan_count) END AS avg_loan_amount, CASE WHEN COALESCE(SUM(l.loan_count), 0) = 0 THEN 0 ELSE CAST(COALESCE(SUM(l.active_loan_count), 0) AS REAL) * 100 / SUM(l.loan_count) END AS active_loan_rate FROM owner_accounts o LEFT JOIN tx_agg tx ON tx.account_id = o.account_id LEFT JOIN loan_agg l ON l.account_id = o.account_id GROUP BY o.district_id, o.district_name, age_group ORDER BY o.district_name, age_group	financial
WITH owner_accounts AS ( SELECT d.client_id, d.account_id, c.gender, c.birth_date FROM disp d JOIN client c ON c.client_id = d.client_id JOIN district dist ON dist.district_id = c.district_id WHERE d.type = 'OWNER' AND dist.A2 = 'Tabor' ), txn_agg AS ( SELECT d.client_id, COUNT(t.trans_id) AS transaction_count, COALESCE(SUM(t.amount), 0) AS total_transaction_amount, AVG(t.balance) AS avg_balance FROM owner_accounts d LEFT JOIN trans t ON t.account_id = d.account_id GROUP BY d.client_id ), loan_agg AS ( SELECT d.client_id, COUNT(l.loan_id) AS loan_count, COALESCE(SUM(l.amount), 0) AS total_loan_amount, SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END) AS good_loan_count, SUM(CASE WHEN l.status = 'B' THEN 1 ELSE 0 END) AS bad_loan_count, CASE WHEN SUM(CASE WHEN l.status = 'B' THEN 1 ELSE 0 END) > 0 THEN 'B' WHEN SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END) > 0 THEN 'A' ELSE 'None' END AS credit_status FROM owner_accounts d LEFT JOIN loan l ON l.account_id = d.account_id GROUP BY d.client_id ) SELECT o.client_id, o.gender, o.birth_date, (strftime('%Y', 'now') - strftime('%Y', o.birth_date)) AS age, COALESCE(ta.transaction_count, 0) AS transaction_count, COALESCE(ta.total_transaction_amount, 0) AS total_transaction_amount, ta.avg_balance, COALESCE(la.loan_count, 0) AS loan_count, COALESCE(la.total_loan_amount, 0) AS total_loan_amount, COALESCE(la.good_loan_count, 0) AS good_loan_count, COALESCE(la.bad_loan_count, 0) AS bad_loan_count, la.credit_status, RANK() OVER (ORDER BY COALESCE(ta.avg_balance, 0) DESC) AS priority_rank FROM (SELECT DISTINCT client_id, gender, birth_date FROM owner_accounts) o LEFT JOIN txn_agg ta ON ta.client_id = o.client_id LEFT JOIN loan_agg la ON la.client_id = o.client_id ORDER BY priority_rank	financial
SELECT d.type, AVG(dist.A11) AS avg_income FROM disp d JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE d.type <> 'OWNER' AND dist.A11 > 8000 AND dist.A11 <= 9000 GROUP BY d.type	financial
SELECT COUNT(DISTINCT a.account_id) FROM account a JOIN district d ON a.district_id = d.district_id JOIN trans t ON t.account_id = a.account_id WHERE d.A3 = 'north Bohemia' AND t.bank = 'AB'	financial
SELECT district_name, total_withdrawals, total_withdrawal_amount, population, unemployment_level, withdrawal_per_capita, RANK() OVER (ORDER BY total_withdrawal_amount DESC) AS rank_by_total_withdrawal_amount FROM ( SELECT d.A2 AS district_name, COUNT(t.trans_id) AS total_withdrawals, SUM(t.amount) AS total_withdrawal_amount, d.A4 AS population, CASE WHEN d.A12 > 2.0 THEN 'High' WHEN d.A12 >= 1.0 AND d.A12 <= 2.0 THEN 'Medium' WHEN d.A12 < 1.0 THEN 'Low' ELSE 'Unknown' END AS unemployment_level, CAST(SUM(t.amount) AS REAL) / d.A4 AS withdrawal_per_capita FROM trans t JOIN account a ON t.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE t.type = 'VYDAJ' GROUP BY d.district_id, d.A2, d.A4, d.A12 ) x ORDER BY total_withdrawal_amount DESC	financial
SELECT AVG(d.A15) FROM district d WHERE d.A15 > 4000 AND EXISTS (SELECT 1 FROM account a WHERE a.district_id = d.district_id AND a.date >= '1997-01-01')	financial
WITH classic_owner AS ( SELECT d.client_id, d.account_id, a.district_id FROM card c JOIN disp d ON c.disp_id = d.disp_id JOIN account a ON d.account_id = a.account_id WHERE c.type = 'classic' AND d.type = 'OWNER' ), classic_accounts AS ( SELECT DISTINCT account_id, district_id FROM classic_owner ), holder_counts AS ( SELECT district_id, COUNT(DISTINCT client_id) AS holder_count FROM classic_owner GROUP BY district_id ), loan_metrics AS ( SELECT ca.district_id, AVG(l.amount) AS avg_loan_amount, SUM(CASE WHEN l.status = 'A' THEN 1.0 ELSE 0.0 END) * 100.0 / NULLIF(SUM(CASE WHEN l.status IN ('A','B') THEN 1.0 ELSE 0.0 END), 0) AS loan_performance FROM classic_accounts ca JOIN loan l ON l.account_id = ca.account_id GROUP BY ca.district_id ), balance_metrics AS ( SELECT district_id, AVG(acct_balance) AS avg_account_balance FROM ( SELECT ca.account_id, ca.district_id, SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE -t.amount END) AS acct_balance FROM classic_accounts ca JOIN trans t ON t.account_id = ca.account_id GROUP BY ca.account_id, ca.district_id ) GROUP BY district_id ) SELECT d.A2 AS district_name, COALESCE(h.holder_count, 0) AS classic_owner_holder_count, lm.avg_loan_amount, bm.avg_account_balance, lm.loan_performance, d.A11 AS district_salary, d.A12 AS unemployment_rate FROM district d LEFT JOIN holder_counts h ON d.district_id = h.district_id LEFT JOIN loan_metrics lm ON d.district_id = lm.district_id LEFT JOIN balance_metrics bm ON d.district_id = bm.district_id ORDER BY d.district_id	financial
WITH base AS ( SELECT c.client_id, CASE WHEN DATE(c.birth_date) > DATE((SELECT MAX(date) FROM trans), '-30 years') THEN 'Young' WHEN DATE(c.birth_date) BETWEEN DATE((SELECT MAX(date) FROM trans), '-50 years') AND DATE((SELECT MAX(date) FROM trans), '-30 years') THEN 'Middle-aged' ELSE 'Senior' END AS age_group FROM client c JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'M' AND d.A2 = 'Hl.m. Praha' ), client_accounts AS ( SELECT DISTINCT b.client_id, b.age_group, dp.account_id FROM base b LEFT JOIN disp dp ON dp.client_id = b.client_id AND dp.type = 'OWNER' ), account_agg AS ( SELECT client_id, age_group, COUNT(account_id) AS account_count FROM client_accounts GROUP BY client_id, age_group ), loan_agg AS ( SELECT ca.client_id, ca.age_group, COUNT(l.loan_id) AS loan_count, SUM(CASE WHEN l.status = 'A' THEN 1 ELSE 0 END) AS good_loans, SUM(CASE WHEN l.status = 'B' THEN 1 ELSE 0 END) AS bad_loans, COALESCE(SUM(l.amount), 0) AS total_loan_amount FROM client_accounts ca LEFT JOIN loan l ON l.account_id = ca.account_id GROUP BY ca.client_id, ca.age_group ), trans_agg AS ( SELECT ca.client_id, ca.age_group, COUNT(t.trans_id) AS transaction_count, COALESCE(SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END), 0) AS total_income, COALESCE(SUM(CASE WHEN t.type = 'VYDAJ' THEN t.amount ELSE 0 END), 0) AS total_expense FROM client_accounts ca LEFT JOIN trans t ON t.account_id = ca.account_id GROUP BY ca.client_id, ca.age_group ) SELECT b.age_group, COUNT(b.client_id) AS client_count, COALESCE(SUM(aa.account_count), 0) AS account_count, COALESCE(SUM(la.loan_count), 0) AS loan_count, COALESCE(SUM(la.good_loans), 0) AS good_loans, COALESCE(SUM(la.bad_loans), 0) AS bad_loans, COALESCE(SUM(la.total_loan_amount), 0) AS total_loan_amount, COALESCE(SUM(ta.transaction_count), 0) AS transaction_count, COALESCE(SUM(ta.total_income), 0) AS total_income, COALESCE(SUM(ta.total_expense), 0) AS total_expense FROM base b LEFT JOIN account_agg aa ON aa.client_id = b.client_id LEFT JOIN loan_agg la ON la.client_id = b.client_id LEFT JOIN trans_agg ta ON ta.client_id = b.client_id GROUP BY b.age_group ORDER BY CASE b.age_group WHEN 'Young' THEN 1 WHEN 'Middle-aged' THEN 2 ELSE 3 END	financial
WITH gold_cards AS ( SELECT c.card_id, d.A3, CASE WHEN c.issued < '1998-01-01' THEN 1 ELSE 0 END AS is_pre FROM card c JOIN disp dp ON c.disp_id = dp.disp_id JOIN account a ON dp.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE c.type = 'gold' ) SELECT 'Overall' AS region, ROUND(100.0 * SUM(is_pre) / COUNT(*), 2) AS percentage FROM gold_cards UNION ALL SELECT A3 AS region, ROUND(100.0 * SUM(is_pre) / COUNT(*), 2) AS percentage FROM gold_cards GROUP BY A3 ORDER BY region	financial
WITH target AS ( SELECT l.account_id, d.client_id, l.date AS loan_date FROM loan l JOIN disp d ON d.account_id = l.account_id AND d.type = 'OWNER' ORDER BY l.amount DESC LIMIT 1 ), tx AS ( SELECT account_id, SUM(CASE WHEN type = 'PRIJEM' THEN amount ELSE 0 END) AS total_income, SUM(CASE WHEN type IN ('VYDAJ', 'VYBER') THEN amount ELSE 0 END) AS total_expense FROM trans WHERE account_id = (SELECT account_id FROM target) GROUP BY account_id ) SELECT c.gender, CASE WHEN CAST((julianday(target.loan_date) - julianday(c.birth_date)) / 365.25 AS INTEGER) < 30 THEN 'Young' WHEN CAST((julianday(target.loan_date) - julianday(c.birth_date)) / 365.25 AS INTEGER) <= 50 THEN 'Middle-aged' ELSE 'Senior' END AS age_category, ROUND((tx.total_income - tx.total_expense) * 100.0 / NULLIF(tx.total_income, 0), 2) AS savings_rate, CASE WHEN d.A13 > 1.0 THEN 'High unemployment area' ELSE 'Low unemployment area' END AS economic_status FROM target JOIN client c ON c.client_id = target.client_id JOIN district d ON d.district_id = c.district_id LEFT JOIN tx ON tx.account_id = target.account_id	financial
SELECT CASE WHEN d.A16 > d.A15 THEN 'increase' WHEN d.A16 < d.A15 THEN 'decrease' ELSE 'no change' END AS crime_trend, (SELECT COUNT(*) + 1 FROM district d2 WHERE d2.A16 > d.A16) AS crime_rank, ROUND((d.A16 - d.A15) * 100.0 / d.A15, 2) AS pct_change_crimes_1995_1996, (SELECT COUNT(*) FROM loan l WHERE l.account_id = a.account_id) AS loan_count, (SELECT COUNT(*) FROM trans t WHERE t.account_id = a.account_id) AS transaction_count, ROUND(d.A16 * 1.0 / d.A4, 4) AS district_crime_rate_1996, ROUND((SELECT AVG(d2.A16 * 1.0 / d2.A4) FROM district d2), 4) AS avg_crime_rate_all_districts, ROUND(d.A16 * 1.0 / d.A4 - (SELECT AVG(d2.A16 * 1.0 / d2.A4) FROM district d2), 4) AS rate_difference FROM account a JOIN district d ON d.district_id = a.district_id WHERE a.account_id = 532	financial
WITH owner AS ( SELECT d.account_id, d.client_id, d.type FROM disp d WHERE d.account_id = (SELECT account_id FROM "order" WHERE order_id = 33333) AND d.type = 'OWNER' ), district_ranked AS ( SELECT district_id, A2 AS district_name, A11 AS district_avg_salary, RANK() OVER (ORDER BY A11 DESC) AS district_salary_rank FROM district ) SELECT a.account_id, dr.district_name, dr.district_avg_salary, dr.district_salary_rank, t.date AS transaction_date, CASE WHEN t.type = 'PRIJEM' THEN 'incoming' WHEN t.type = 'VYDAJ' THEN 'outgoing' ELSE t.type END AS transaction_type, t.operation AS transaction_operation, t.amount AS transaction_amount, t.balance AS transaction_balance, o.client_id AS owner_client_id, o.type AS ownership_type, l.status AS loan_status, ord.order_id, ord.bank_to AS order_bank_to, ord.account_to AS order_account_to, ord.amount AS order_amount FROM "order" ord JOIN account a ON a.account_id = ord.account_id JOIN district_ranked dr ON dr.district_id = a.district_id LEFT JOIN owner o ON o.account_id = a.account_id LEFT JOIN loan l ON l.account_id = a.account_id LEFT JOIN trans t ON t.account_id = a.account_id WHERE ord.order_id = 33333 ORDER BY t.date, t.trans_id	financial
SELECT trans.trans_id, trans.date, trans.type, trans.amount, trans.balance, trans.k_symbol, trans.bank, trans.account FROM trans JOIN disp ON disp.account_id = trans.account_id WHERE disp.client_id = 3356 AND trans.operation = 'VYBER'	financial
SELECT COUNT(DISTINCT a.account_id) FROM account a JOIN loan l ON l.account_id = a.account_id WHERE a.frequency = 'POPLATEK TYDNE' AND l.amount < 200000	financial
SELECT c.client_id, c.gender, c.birth_date, d.A2 AS district_name, d.A11 AS average_salary, (SELECT COUNT(*)+1 FROM district d2 WHERE d2.A11 > d.A11) AS salary_rank, cd.type AS card_type, cd.issued AS card_issued, CASE WHEN cd.type = 'gold' THEN 'Premium' WHEN cd.type = 'classic' AND DATE(cd.issued) <= DATE('now', '-5 years') THEN 'Long-term Classic' ELSE 'Standard' END AS customer_segment, COALESCE((SELECT SUM(t.amount) FROM trans t WHERE t.account_id = a.account_id AND t.type = 'PRIJEM'), 0) AS income, COALESCE((SELECT SUM(t.amount) FROM trans t WHERE t.account_id = a.account_id AND t.type = 'VYDAJ'), 0) AS expense, (SELECT COUNT(*) FROM loan l WHERE l.account_id = a.account_id) AS loan_count FROM client c JOIN district d ON d.district_id = c.district_id JOIN disp dp ON dp.client_id = c.client_id AND dp.type = 'OWNER' JOIN account a ON a.account_id = dp.account_id LEFT JOIN card cd ON cd.disp_id = dp.disp_id WHERE c.client_id = 13539	financial
SELECT a.account_id, da.A3 AS region, a.frequency, a.date AS account_date, l.date AS loan_date, l.amount AS loan_amount, l.duration AS loan_duration, l.payments AS loan_payments, l.status AS loan_status, COALESCE(t.transaction_count, 0) AS transaction_count, COALESCE(t.total_income, 0) AS total_income, COALESCE(t.total_expense, 0) AS total_expense, COALESCE(t.total_income, 0) - COALESCE(t.total_expense, 0) AS net_balance, (SELECT COUNT(DISTINCT c2.client_id) FROM client c2 JOIN district dd ON dd.district_id = c2.district_id WHERE dd.A3 = da.A3 AND c2.client_id <> 3541 ) AS other_clients_same_region FROM disp d JOIN account a ON a.account_id = d.account_id JOIN district da ON da.district_id = a.district_id LEFT JOIN loan l ON l.account_id = a.account_id LEFT JOIN ( SELECT account_id, COUNT(*) AS transaction_count, SUM(CASE WHEN type = 'PRIJEM' THEN amount ELSE 0 END) AS total_income, SUM(CASE WHEN type = 'VYDAJ' THEN amount ELSE 0 END) AS total_expense FROM trans GROUP BY account_id ) t ON t.account_id = a.account_id WHERE d.client_id = 3541 ORDER BY transaction_count	financial
SELECT d.A2 AS district FROM account a JOIN loan l ON a.account_id = l.account_id JOIN district d ON a.district_id = d.district_id WHERE l.status = 'A' GROUP BY d.district_id, d.A2 ORDER BY COUNT(DISTINCT a.account_id) DESC LIMIT 1	financial
SELECT (SELECT c.gender FROM disp d JOIN client c ON c.client_id = d.client_id WHERE d.account_id = o.account_id AND d.type = 'OWNER' LIMIT 1) AS owner_gender, (SELECT c.birth_date FROM disp d JOIN client c ON c.client_id = d.client_id WHERE d.account_id = o.account_id AND d.type = 'OWNER' LIMIT 1) AS owner_birth_date, (SELECT dis.A2 FROM disp d JOIN client c ON c.client_id = d.client_id JOIN district dis ON dis.district_id = c.district_id WHERE d.account_id = o.account_id AND d.type = 'OWNER' LIMIT 1) AS owner_district, o.order_id, o.amount AS order_amount, o.bank_to, o.account_to, o.k_symbol, (SELECT l.status FROM loan l WHERE l.account_id = o.account_id LIMIT 1) AS loan_status, (SELECT COALESCE(SUM(t.amount),0) FROM trans t WHERE t.account_id = o.account_id AND t.type = 'PRIJEM') AS total_income, (SELECT COALESCE(SUM(t.amount),0) FROM trans t WHERE t.account_id = o.account_id AND t.type = 'VYDAJ') AS total_expense, (SELECT COALESCE(SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount WHEN t.type = 'VYDAJ' THEN -t.amount ELSE 0 END),0) FROM trans t WHERE t.account_id = o.account_id) AS net_balance, (SELECT COUNT(*) FROM card ca JOIN disp cd ON ca.disp_id = cd.disp_id WHERE cd.account_id = o.account_id AND cd.type = 'OWNER') AS num_credit_cards FROM "order" o WHERE o.order_id = 32423	financial
SELECT t.trans_id, t.account_id, t.date, t.type, t.operation, t.amount, t.balance, t.k_symbol, t.bank, t.account FROM trans t JOIN account a ON t.account_id = a.account_id WHERE a.district_id = 5	financial
SELECT (SELECT COUNT(DISTINCT a.account_id) FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Jesenik') AS total_accounts, (SELECT COUNT(*) FROM trans t JOIN account a ON t.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Jesenik' AND t.type = 'PRIJEM') AS incoming_transactions, (SELECT COUNT(*) FROM trans t JOIN account a ON t.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Jesenik' AND t.type = 'VYDAJ') AS outgoing_transactions, (SELECT COUNT(*) FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Jesenik' AND l.status = 'A') AS good_loans, (SELECT COUNT(*) FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Jesenik' AND l.status = 'B') AS bad_loans, (SELECT AVG(t.balance) FROM trans t JOIN account a ON t.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Jesenik') AS average_balance, (SELECT COUNT(DISTINCT di.client_id) FROM disp di JOIN account a ON di.account_id = a.account_id JOIN district d ON a.district_id = d.district_id JOIN client c ON di.client_id = c.client_id WHERE d.A2 = 'Jesenik' AND c.gender = 'F') AS female_clients, (SELECT COUNT(DISTINCT di.client_id) FROM disp di JOIN account a ON di.account_id = a.account_id JOIN district d ON a.district_id = d.district_id JOIN client c ON di.client_id = c.client_id WHERE d.A2 = 'Jesenik' AND c.gender = 'M') AS male_clients	financial
SELECT DISTINCT d.client_id FROM card c JOIN disp d ON c.disp_id = d.disp_id WHERE c.type = 'junior' AND c.issued >= '1997-01-01'	financial
SELECT 100.0 * COUNT(DISTINCT CASE WHEN c.gender = 'F' THEN c.client_id END) / COUNT(DISTINCT c.client_id) AS percentage FROM client c JOIN disp d ON d.client_id = c.client_id JOIN account a ON a.account_id = d.account_id JOIN district dist ON dist.district_id = a.district_id WHERE dist.A11 > 10000 AND d.type = 'OWNER'	financial
SELECT (SUM(CASE WHEN substr(loan.date,1,4) = '1997' THEN loan.amount ELSE 0 END) - SUM(CASE WHEN substr(loan.date,1,4) = '1996' THEN loan.amount ELSE 0 END)) * 100.0 / SUM(CASE WHEN substr(loan.date,1,4) = '1996' THEN loan.amount ELSE 0 END) AS growth_rate FROM loan WHERE EXISTS ( SELECT 1 FROM disp JOIN client ON client.client_id = disp.client_id WHERE disp.account_id = loan.account_id AND client.gender = 'M' ) AND substr(loan.date,1,4) IN ('1996','1997')	financial
SELECT COUNT(*) FROM trans WHERE operation = 'VYBER KARTOU' AND date >= '1996-01-01'	financial
SELECT SUM(CASE WHEN A3 = 'north Bohemia' THEN A16 ELSE 0 END) - SUM(CASE WHEN A3 = 'east Bohemia' THEN A16 ELSE 0 END) AS difference FROM district	financial
SELECT COUNT(*) AS disposition_count FROM disp WHERE account_id BETWEEN 1 AND 10 AND type IN ('OWNER','DISPONENT')	financial
SELECT a.frequency FROM account a WHERE a.account_id = 3) AS frequency, t.k_symbol, SUM(t.amount) AS total_debited FROM trans AS t WHERE t.account_id = 3539 AND t.type = 'VYDAJ' GROUP BY t.k_symbol	financial
SELECT STRFTIME('%Y', c.birth_date) AS birth_year FROM disp d JOIN client c ON d.client_id = c.client_id WHERE d.account_id = 130 AND d.type = 'OWNER'	financial
WITH target_accounts AS ( SELECT a.account_id, d.A2 AS district_name, d.A3 AS region, d.A11 AS district_salary FROM account a JOIN district d ON a.district_id = d.district_id JOIN disp dp ON dp.account_id = a.account_id AND dp.type = 'OWNER' WHERE a.frequency = 'POPLATEK PO OBRATU' ), loan_agg AS ( SELECT l.account_id, COUNT(*) AS loan_cnt, SUM(l.amount) AS total_loan_amount FROM loan l JOIN target_accounts ta ON l.account_id = ta.account_id GROUP BY l.account_id ), trans_agg AS ( SELECT t.account_id, COUNT(*) AS trans_cnt FROM trans t JOIN target_accounts ta ON t.account_id = ta.account_id GROUP BY t.account_id ), latest_trans AS ( SELECT t.account_id, t.balance AS latest_balance FROM trans t JOIN ( SELECT trans.account_id, MAX(trans.trans_id) AS max_trans_id FROM trans JOIN target_accounts ta ON trans.account_id = ta.account_id GROUP BY trans.account_id ) m ON m.account_id = t.account_id AND m.max_trans_id = t.trans_id ) SELECT t.region, t.district_name, COUNT(DISTINCT t.account_id) AS num_accounts, AVG(t.district_salary) AS avg_district_salary, CAST(COUNT(DISTINCT la.account_id) AS REAL) * 100.0 / COUNT(DISTINCT t.account_id) AS loan_adoption_rate, COALESCE(CAST(SUM(la.total_loan_amount) AS REAL) / NULLIF(SUM(la.loan_cnt), 0), 0) AS avg_loan_amount, COALESCE(SUM(ta.trans_cnt), 0) AS transaction_activity, COALESCE(AVG(lb.latest_balance), 0) AS avg_account_balance FROM target_accounts t LEFT JOIN loan_agg la ON la.account_id = t.account_id LEFT JOIN trans_agg ta ON ta.account_id = t.account_id LEFT JOIN latest_trans lb ON lb.account_id = t.account_id GROUP BY t.region, t.district_name ORDER BY t.region, t.district_name	financial
SELECT l.amount, l.status FROM disp d JOIN loan l ON d.account_id = l.account_id WHERE d.client_id = 992	financial
SELECT t.balance, c.gender FROM trans t JOIN disp d ON t.account_id = d.account_id AND d.type = 'OWNER' JOIN client c ON d.client_id = c.client_id WHERE t.trans_id = 851 AND c.client_id = 4	financial
SELECT c.gender, c.birth_date, card.type AS credit_card_type, card.issued AS card_issued, CASE WHEN card.type = 'gold' THEN 'Premium Customer' WHEN card.type = 'classic' THEN 'Regular Customer' ELSE 'Unknown' END AS customer_status, (SELECT COUNT(DISTINCT d2.account_id) FROM disp d2 WHERE d2.client_id = c.client_id AND d2.type = 'OWNER') AS total_accounts_owned, CAST(julianday('now') - julianday(card.issued) AS INTEGER) AS days_with_most_recent_card FROM client c JOIN disp d ON d.client_id = c.client_id JOIN card ON card.disp_id = d.disp_id WHERE c.client_id = 9 ORDER BY card.issued DESC LIMIT 1	financial
SELECT SUM(t.amount) AS total_paid FROM disp d JOIN trans t ON d.account_id = t.account_id WHERE d.client_id = 617 AND t.type = 'VYDAJ' AND t.date >= '1998-01-01' AND t.date < '1999-01-01'	financial
SELECT DISTINCT c.client_id, a.account_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE dist.A3 = 'east Bohemia' AND c.birth_date >= '1983-01-01' AND c.birth_date < '1988-01-01' ORDER BY c.client_id, a.account_id	financial
WITH ranked_loans AS ( SELECT c.client_id, c.birth_date, c.district_id, l.loan_id, l.account_id, l.amount, l.payments, l.duration, l.status, ROW_NUMBER() OVER ( PARTITION BY c.client_id ORDER BY l.amount DESC, l.loan_id ) AS rn FROM client c JOIN disp dsp ON c.client_id = dsp.client_id JOIN loan l ON dsp.account_id = l.account_id WHERE c.gender = 'F' ), top3 AS ( SELECT * FROM ranked_loans WHERE rn = 1 ORDER BY amount DESC LIMIT 3 ), acct_tx AS ( SELECT account_id, COUNT(trans_id) AS tx_count, SUM(CASE WHEN type = 'PRIJEM' THEN amount ELSE 0 END) AS total_income FROM trans GROUP BY account_id ) SELECT (top3.payments * top3.duration) AS total_payments, (top3.payments * top3.duration - top3.amount) AS interest_paid, top3.status AS loan_status, d.A2 AS location, COALESCE(acct_tx.tx_count, 0) AS transaction_activity, CASE WHEN COALESCE(acct_tx.total_income, 0) > 2 * top3.amount THEN 'High' WHEN COALESCE(acct_tx.total_income, 0) > top3.amount THEN 'Medium' ELSE 'Low' END AS income_category, (CAST(STRFTIME('%Y', 'now') AS INTEGER) - CAST(STRFTIME('%Y', top3.birth_date) AS INTEGER)) AS age FROM top3 JOIN district d ON top3.district_id = d.district_id LEFT JOIN acct_tx ON top3.account_id = acct_tx.account_id ORDER BY top3.amount DESC	financial
SELECT COUNT(DISTINCT c.client_id) AS male_count FROM client c JOIN disp d ON d.client_id = c.client_id JOIN "order" o ON o.account_id = d.account_id WHERE c.gender = 'M' AND c.birth_date >= '1974-01-01' AND c.birth_date < '1977-01-01' AND o.k_symbol = 'SIPO' AND o.amount > 4000	financial
WITH beroun_accounts AS ( SELECT a.account_id, CAST(SUBSTR(a.date,1,4) AS INTEGER) AS year FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Beroun' AND CAST(SUBSTR(a.date,1,4) AS INTEGER) > 1996 ), owner_stats AS ( SELECT ba.year, SUM(CASE WHEN c.gender = 'F' THEN 1 ELSE 0 END) AS female_count, SUM(CASE WHEN c.gender = 'M' THEN 1 ELSE 0 END) AS male_count, AVG(ba.year - CAST(SUBSTR(c.birth_date,1,4) AS INTEGER)) AS avg_age FROM beroun_accounts ba JOIN disp dp ON dp.account_id = ba.account_id JOIN client c ON c.client_id = dp.client_id WHERE dp.type = 'OWNER' GROUP BY ba.year ), txn_stats AS ( SELECT ba.year, SUM(CASE WHEN t.type = 'PRIJEM' THEN t.amount ELSE 0 END) AS total_income, SUM(CASE WHEN t.type = 'VYDAJ' THEN t.amount ELSE 0 END) AS total_expenses FROM beroun_accounts ba JOIN trans t ON t.account_id = ba.account_id GROUP BY ba.year ), loan_stats AS ( SELECT ba.year, SUM(CASE WHEN l.status IN ('A','C') THEN 1 ELSE 0 END) AS successful_loans, COUNT(*) AS total_loans FROM beroun_accounts ba JOIN loan l ON l.account_id = ba.account_id GROUP BY ba.year ), card_stats AS ( SELECT ba.year, SUM(CASE WHEN ca.type = 'classic' THEN 1 ELSE 0 END) AS classic_cards, SUM(CASE WHEN ca.type = 'junior' THEN 1 ELSE 0 END) AS junior_cards, SUM(CASE WHEN ca.type = 'gold' THEN 1 ELSE 0 END) AS gold_cards FROM beroun_accounts ba JOIN disp dp ON dp.account_id = ba.account_id JOIN card ca ON ca.disp_id = dp.disp_id GROUP BY ba.year ), years AS ( SELECT DISTINCT year FROM beroun_accounts ) SELECT y.year, COALESCE(o.female_count,0) AS female_count, COALESCE(o.male_count,0) AS male_count, o.avg_age AS avg_age, COALESCE(t.total_income,0) AS total_income, COALESCE(t.total_expenses,0) AS total_expenses, CASE WHEN l.total_loans > 0 THEN CAST(l.successful_loans AS REAL) / l.total_loans ELSE 0 END AS loan_success_rate, COALESCE(ca.classic_cards,0) AS classic_cards, COALESCE(ca.junior_cards,0) AS junior_cards, COALESCE(ca.gold_cards,0) AS gold_cards FROM years y LEFT JOIN owner_stats o ON y.year = o.year LEFT JOIN txn_stats t ON y.year = t.year LEFT JOIN loan_stats l ON y.year = l.year LEFT JOIN card_stats ca ON y.year = ca.year ORDER BY y.year	financial
SELECT COUNT(DISTINCT c.client_id) AS female_junior_card_customers FROM card JOIN disp ON card.disp_id = disp.disp_id JOIN client c ON disp.client_id = c.client_id WHERE card.type = 'junior' AND c.gender = 'F'	financial
SELECT CAST(COUNT(DISTINCT CASE WHEN c.gender = 'F' THEN c.client_id END) AS REAL) * 100 / COUNT(DISTINCT c.client_id) AS female_ratio_pct FROM client c JOIN disp d ON d.client_id = c.client_id JOIN account a ON a.account_id = d.account_id JOIN district dist ON dist.district_id = a.district_id WHERE dist.A3 = 'Prague'	financial
SELECT CAST(COUNT(DISTINCT CASE WHEN c.gender = 'M' THEN c.client_id END) AS REAL) * 100 / COUNT(DISTINCT c.client_id) AS percentage_male_weekly FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id WHERE a.frequency = 'POPLATEK TYDNE'	financial
WITH weekly_owner AS ( SELECT d.client_id, d.account_id, d.disp_id FROM disp d JOIN account a ON d.account_id = a.account_id WHERE d.type = 'OWNER' AND a.frequency = 'POPLATEK TYDNE' ), per_owner AS ( SELECT w.client_id, COUNT(t.trans_id) AS tx_count, SUM(t.amount) AS total_amount FROM weekly_owner w LEFT JOIN trans t ON t.account_id = w.account_id GROUP BY w.client_id ), latest_balance AS ( SELECT t.account_id, t.balance FROM trans t JOIN ( SELECT account_id, MAX(trans_id) AS max_trans_id FROM trans GROUP BY account_id ) lb ON t.account_id = lb.account_id AND t.trans_id = lb.max_trans_id WHERE t.account_id IN (SELECT account_id FROM weekly_owner) ), weekly_cards AS ( SELECT DISTINCT w.client_id FROM weekly_owner w JOIN card c ON c.disp_id = w.disp_id ) SELECT (SELECT COUNT(*) FROM per_owner) AS num_owners, (SELECT AVG(tx_count) FROM per_owner) AS avg_transactions, (SELECT COUNT(*) FROM weekly_cards) AS credit_card_owners, (SELECT COUNT(*) FROM per_owner WHERE total_amount > 10000) AS high_volume_clients, (SELECT COUNT(DISTINCT cl.district_id) FROM client cl WHERE cl.client_id IN (SELECT client_id FROM weekly_owner)) AS num_districts, (SELECT AVG(balance) FROM latest_balance) AS avg_account_balance	financial
WITH min_loan AS ( SELECT MIN(l.amount) AS amount FROM loan l JOIN account a ON a.account_id = l.account_id WHERE l.duration > 24 AND a.date < '1997-01-01' ), target AS ( SELECT l.account_id, MIN(l.amount) AS smallest_loan_amount, MIN(l.duration) AS loan_duration, MIN(a.date) AS account_open_date FROM loan l JOIN account a ON a.account_id = l.account_id WHERE l.duration > 24 AND a.date < '1997-01-01' GROUP BY l.account_id HAVING MIN(l.amount) = (SELECT amount FROM min_loan) ) SELECT t.account_id, t.smallest_loan_amount, t.loan_duration, t.account_open_date, COALESCE((SELECT SUM(CASE WHEN tr.type = 'PRIJEM' THEN tr.amount ELSE 0 END) FROM trans tr WHERE tr.account_id = t.account_id), 0) AS income, COALESCE((SELECT SUM(CASE WHEN tr.type = 'VYDAJ' THEN tr.amount ELSE 0 END) FROM trans tr WHERE tr.account_id = t.account_id), 0) AS expense, (SELECT GROUP_CONCAT(DISTINCT c.type) FROM card c JOIN disp d ON d.disp_id = c.disp_id WHERE d.account_id = t.account_id) AS card_type, (SELECT MIN(c.issued) FROM card c JOIN disp d ON d.disp_id = c.disp_id WHERE d.account_id = t.account_id) AS card_issued, (SELECT cl.gender FROM disp d JOIN client cl ON cl.client_id = d.client_id WHERE d.account_id = t.account_id AND d.type = 'OWNER' LIMIT 1) AS gender, (SELECT cl.birth_date FROM disp d JOIN client cl ON cl.client_id = d.client_id WHERE d.account_id = t.account_id AND d.type = 'OWNER' LIMIT 1) AS birth_date, (SELECT cl.district_id FROM disp d JOIN client cl ON cl.client_id = d.client_id WHERE d.account_id = t.account_id AND d.type = 'OWNER' LIMIT 1) AS district_id, (SELECT COUNT(*) FROM "order" o WHERE o.account_id = t.account_id) AS order_count, COALESCE((SELECT SUM(o.amount) FROM "order" o WHERE o.account_id = t.account_id), 0) AS total_order_amount FROM target t ORDER BY t.account_id	financial
SELECT DISTINCT a.account_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON c.district_id = dist.district_id WHERE c.gender = 'F' AND dist.A11 = (SELECT MIN(A11) FROM district) AND c.birth_date = ( SELECT MIN(c2.birth_date) FROM client c2 JOIN district d2 ON c2.district_id = d2.district_id WHERE c2.gender = 'F' AND d2.A11 = (SELECT MIN(A11) FROM district) ) ORDER BY a.account_id	financial
WITH target AS ( SELECT c.client_id, c.gender, c.district_id FROM client c JOIN district r ON r.district_id = c.district_id WHERE c.birth_date >= '1920-01-01' AND c.birth_date <= '1920-12-31' AND r.A3 = 'east Bohemia' ), acct_ids AS ( SELECT DISTINCT d.account_id FROM disp d JOIN target t ON t.client_id = d.client_id ) SELECT (SELECT COUNT(*) FROM target) AS client_count, (SELECT COUNT(*) FROM target WHERE gender = 'F') AS female_count, (SELECT COUNT(*) FROM target WHERE gender = 'M') AS male_count, (SELECT COUNT(*) FROM acct_ids) AS account_count, (SELECT COUNT(*) FROM acct_ids a JOIN account acc ON acc.account_id = a.account_id WHERE acc.frequency = 'POPLATEK MESICNE') AS monthly_fee_accounts, (SELECT COUNT(*) FROM acct_ids a JOIN account acc ON acc.account_id = a.account_id WHERE acc.frequency = 'POPLATEK TYDNE') AS weekly_fee_accounts, (SELECT COUNT(*) FROM acct_ids a JOIN account acc ON acc.account_id = a.account_id WHERE acc.frequency = 'POPLATEK PO OBRATU') AS after_transaction_fee_accounts, (SELECT COUNT(*) FROM loan l WHERE l.account_id IN (SELECT account_id FROM acct_ids)) AS loan_count, COALESCE((SELECT SUM(l.amount) FROM loan l WHERE l.account_id IN (SELECT account_id FROM acct_ids)), 0) AS total_loan_amount, COALESCE((SELECT AVG(l.amount) FROM loan l WHERE l.account_id IN (SELECT account_id FROM acct_ids)), 0) AS avg_loan_amount, COALESCE((SELECT AVG(l.duration) FROM loan l WHERE l.account_id IN (SELECT account_id FROM acct_ids)), 0) AS avg_loan_duration, COALESCE((SELECT AVG(l.payments) FROM loan l WHERE l.account_id IN (SELECT account_id FROM acct_ids)), 0) AS avg_loan_payments, (SELECT COUNT(*) FROM trans t WHERE t.account_id IN (SELECT account_id FROM acct_ids)) AS transaction_count, (SELECT COUNT(*) FROM trans t WHERE t.account_id IN (SELECT account_id FROM acct_ids) AND t.type = 'PRIJEM') AS income_transaction_count, (SELECT COUNT(*) FROM trans t WHERE t.account_id IN (SELECT account_id FROM acct_ids) AND t.type = 'VYDAJ') AS expense_transaction_count, COALESCE((SELECT SUM(t.amount) FROM trans t WHERE t.account_id IN (SELECT account_id FROM acct_ids) AND t.type = 'PRIJEM'), 0) AS income_transaction_amount, COALESCE((SELECT SUM(t.amount) FROM trans t WHERE t.account_id IN (SELECT account_id FROM acct_ids) AND t.type = 'VYDAJ'), 0) AS expense_transaction_amount, (SELECT r2.A2 FROM target t2 JOIN district r2 ON r2.district_id = t2.district_id GROUP BY r2.district_id, r2.A2 ORDER BY COUNT(*) DESC, r2.A2 LIMIT 1) AS most_common_district	financial
WITH top AS ( SELECT l.loan_id, l.account_id, l.amount, l.duration, l.payments, l.status, a.district_id FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.duration = 24 AND a.frequency = 'POPLATEK TYDNE' AND EXISTS ( SELECT 1 FROM disp d WHERE d.account_id = l.account_id AND d.type = 'OWNER' ) ORDER BY l.amount DESC LIMIT 50 ) SELECT COUNT(*) AS total_count, AVG(t.amount) AS avg_loan_amount, MIN(t.amount) AS min_loan_amount, MAX(t.amount) AS max_loan_amount, AVG(t.payments) AS avg_monthly_payment, MIN(t.payments) AS min_monthly_payment, MAX(t.payments) AS max_monthly_payment, SUM(t.payments) AS total_monthly_payments, AVG((t.payments * t.duration - t.amount) * 100.0 / t.amount) AS avg_interest_rate_pct, MIN((t.payments * t.duration - t.amount) * 100.0 / t.amount) AS min_interest_rate_pct, MAX((t.payments * t.duration - t.amount) * 100.0 / t.amount) AS max_interest_rate_pct, SUM(CASE WHEN t.status = 'A' THEN 1 ELSE 0 END) AS status_A_count, SUM(CASE WHEN t.status = 'B' THEN 1 ELSE 0 END) AS status_B_count, SUM(CASE WHEN t.status = 'C' THEN 1 ELSE 0 END) AS status_C_count, SUM(CASE WHEN t.status = 'D' THEN 1 ELSE 0 END) AS status_D_count, AVG(d.A11) AS avg_district_avg_salary, AVG(d.A12) AS avg_unemployment_95, AVG(d.A13) AS avg_unemployment_96, AVG(d.A14) AS avg_entrepreneurs_per_1000, AVG(d.A15) AS avg_crimes_95, AVG(d.A16) AS avg_crimes_96 FROM top t JOIN district d ON t.district_id = d.district_id	financial
SELECT AVG(l.amount) AS avg_amount FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.status IN ('C','D') AND a.frequency = 'POPLATEK PO OBRATU'	financial
SELECT DISTINCT c.client_id, c.district_id FROM client c JOIN disp d ON c.client_id = d.client_id WHERE d.type = 'OWNER'	financial
SELECT c.client_id, CAST(STRFTIME('%Y', 'now') AS INTEGER) - CAST(SUBSTR(c.birth_date, 1, 4) AS INTEGER) - (STRFTIME('%m-%d', 'now') < SUBSTR(c.birth_date, 6, 5)) AS age FROM card JOIN disp ON card.disp_id = disp.disp_id JOIN client c ON disp.client_id = c.client_id WHERE card.type = 'gold' AND disp.type = 'OWNER' ORDER BY c.client_id	financial
WITH target AS ( SELECT bond_type FROM bond GROUP BY bond_type ORDER BY COUNT(bond_id) DESC LIMIT 1 ) SELECT t.bond_type AS bond_type, (SELECT COUNT(*) FROM bond b WHERE b.bond_type = t.bond_type) AS total_occurrences, (SELECT COUNT(DISTINCT b.molecule_id) FROM bond b WHERE b.bond_type = t.bond_type) AS molecules_containing_type, CAST((SELECT COUNT(*) FROM bond b WHERE b.bond_type = t.bond_type) AS REAL) / (SELECT COUNT(DISTINCT b.molecule_id) FROM bond b WHERE b.bond_type = t.bond_type) AS avg_bonds_per_molecule, (SELECT COUNT(DISTINCT CASE WHEN a1.element <= a2.element THEN a1.element ELSE a2.element END || '-' || CASE WHEN a1.element <= a2.element THEN a2.element ELSE a1.element END) FROM connected c JOIN bond b ON b.bond_id = c.bond_id JOIN atom a1 ON a1.atom_id = c.atom_id JOIN atom a2 ON a2.atom_id = c.atom_id2 WHERE b.bond_type = t.bond_type) AS unique_element_pair_count, (SELECT GROUP_CONCAT(DISTINCT m.label, ', ') FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE b.bond_type = t.bond_type) AS molecule_labels FROM target t	toxicology
WITH cl_mols AS ( SELECT DISTINCT m.molecule_id FROM molecule m JOIN atom a ON a.molecule_id = m.molecule_id WHERE m.label = '-' AND a.element = 'cl' ), per_mol AS ( SELECT cm.molecule_id, (SELECT COUNT(*) FROM atom a WHERE a.molecule_id = cm.molecule_id AND a.element = 'cl') AS cl_count, (SELECT COUNT(*) FROM bond b WHERE b.molecule_id = cm.molecule_id) AS bond_count, (SELECT COUNT(*) FROM bond b WHERE b.molecule_id = cm.molecule_id AND b.bond_type = '-') AS single_count, (SELECT COUNT(*) FROM bond b WHERE b.molecule_id = cm.molecule_id AND b.bond_type = '=') AS double_count, (SELECT COUNT(*) FROM bond b WHERE b.molecule_id = cm.molecule_id AND EXISTS ( SELECT 1 FROM connected c JOIN atom a ON a.atom_id = c.atom_id OR a.atom_id = c.atom_id2 WHERE c.bond_id = b.bond_id AND a.element = 'cl' ) ) AS cl_bond_count FROM cl_mols cm ) SELECT COUNT(*) AS molecule_count, AVG(cl_count) AS avg_chlorine_atoms, MAX(cl_count) AS max_chlorine_atoms, AVG(bond_count) AS avg_bonds, SUM(CASE WHEN single_count > double_count THEN 1 ELSE 0 END) AS molecules_more_single_than_double, AVG(cl_bond_count) AS avg_chlorine_bonds FROM per_mol	toxicology
WITH molecule_oxygen AS ( SELECT a.molecule_id, SUM(CASE WHEN a.element = 'o' THEN 1 ELSE 0 END) AS oxygen_count FROM atom a WHERE a.molecule_id IN ( SELECT molecule_id FROM bond WHERE bond_type = '-' ) GROUP BY a.molecule_id ) SELECT AVG(oxygen_count) AS avg_oxygen_atoms FROM molecule_oxygen	toxicology
SELECT CAST((SELECT SUM(b.bond_type = '-') FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE m.label = '+') AS REAL) / (SELECT COUNT(a.atom_id) FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE m.label = '+') AS avg_single_bonds_per_atom	toxicology
SELECT COUNT(DISTINCT m.molecule_id) AS non_carcinogenic_sodium_molecule_count FROM molecule m JOIN atom a ON a.molecule_id = m.molecule_id WHERE a.element = 'na' AND m.label = '-'	toxicology
SELECT COUNT(*) FROM molecule m WHERE m.label = '+' AND EXISTS ( SELECT 1 FROM bond b WHERE b.molecule_id = m.molecule_id AND b.bond_type = '#' )	toxicology
SELECT CAST(SUM(element = 'c') AS REAL) * 100 / COUNT(atom_id) AS carbon_percentage FROM atom WHERE molecule_id IN (SELECT molecule_id FROM bond WHERE bond_type = '=')	toxicology
SELECT COUNT(*) FROM bond WHERE bond_type = '#'	toxicology
WITH conn_counts AS ( SELECT aid AS atom_id, COUNT(DISTINCT bond_id) AS connection_count FROM ( SELECT atom_id AS aid, bond_id FROM connected UNION ALL SELECT atom_id2 AS aid, bond_id FROM connected ) GROUP BY aid ), scope_molecules AS ( SELECT molecule_id FROM bond UNION SELECT molecule_id FROM atom GROUP BY molecule_id HAVING COUNT(*) > 1 ), eligible_atoms AS ( SELECT a.atom_id, COALESCE(cc.connection_count, 0) AS connection_count FROM atom a JOIN scope_molecules sm ON sm.molecule_id = a.molecule_id LEFT JOIN conn_counts cc ON cc.atom_id = a.atom_id WHERE a.element != 'br' ) SELECT AVG(connection_count) AS avg_connections, SUM(CASE WHEN connection_count > 2 THEN 1 ELSE 0 END) AS atoms_with_more_than_2_connections FROM eligible_atoms	toxicology
SELECT AVG(atom_count) AS avg_atom_count, AVG(carbon_count) AS avg_carbon_count, AVG(bond_count) AS avg_bond_count, AVG(double_bond_count) AS avg_double_bond_count, AVG(connected_atom_count) AS avg_connected_atom_count, AVG(cc_ratio) AS avg_carbon_carbon_connection_ratio FROM ( SELECT m.molecule_id, (SELECT COUNT(*) FROM atom a WHERE a.molecule_id = m.molecule_id) AS atom_count, (SELECT COUNT(*) FROM atom a WHERE a.molecule_id = m.molecule_id AND a.element = 'c') AS carbon_count, (SELECT COUNT(*) FROM bond b WHERE b.molecule_id = m.molecule_id) AS bond_count, (SELECT COUNT(*) FROM bond b WHERE b.molecule_id = m.molecule_id AND b.bond_type = '=') AS double_bond_count, (SELECT COUNT(DISTINCT endpoint) FROM ( SELECT c.atom_id AS endpoint FROM connected c JOIN bond b ON c.bond_id = b.bond_id WHERE b.molecule_id = m.molecule_id UNION SELECT c.atom_id2 AS endpoint FROM connected c JOIN bond b ON c.bond_id = b.bond_id WHERE b.molecule_id = m.molecule_id ) AS endpoints) AS connected_atom_count, (SELECT CASE WHEN COUNT(DISTINCT c.bond_id) = 0 THEN 0 ELSE CAST(COUNT(DISTINCT CASE WHEN a1.element = 'c' AND a2.element = 'c' THEN c.bond_id END) AS REAL) / COUNT(DISTINCT c.bond_id) END FROM connected c JOIN bond b ON c.bond_id = b.bond_id JOIN atom a1 ON c.atom_id = a1.atom_id JOIN atom a2 ON c.atom_id2 = a2.atom_id WHERE b.molecule_id = m.molecule_id ) AS cc_ratio FROM molecule m WHERE m.molecule_id BETWEEN 'TR000' AND 'TR099' AND m.label = '+' AND EXISTS ( SELECT 1 FROM atom a WHERE a.molecule_id = m.molecule_id AND a.element IN ('c','h') ) ) AS t	toxicology
WITH atom_stats AS ( SELECT molecule_id, COUNT(*) AS atom_count, SUM(CASE WHEN element = 'c' THEN 1 ELSE 0 END) AS carbon_count, SUM(CASE WHEN element = 'cl' THEN 1 ELSE 0 END) AS chlorine_count FROM atom GROUP BY molecule_id HAVING SUM(CASE WHEN element = 'c' THEN 1 ELSE 0 END) > 0 ), bond_stats AS ( SELECT molecule_id, COUNT(*) AS bond_count, SUM(CASE WHEN bond_type = '=' THEN 1 ELSE 0 END) AS double_bond_count FROM bond GROUP BY molecule_id ), connection_stats AS ( SELECT b.molecule_id, COUNT(*) AS connection_count FROM connected c JOIN bond b ON c.bond_id = b.bond_id GROUP BY b.molecule_id ) SELECT a.molecule_id, a.atom_count, COALESCE(b.bond_count, 0) AS bond_count, a.carbon_count, a.chlorine_count, COALESCE(b.double_bond_count, 0) AS double_bond_count, COALESCE(c.connection_count, 0) AS connection_count FROM atom_stats a LEFT JOIN bond_stats b ON a.molecule_id = b.molecule_id LEFT JOIN connection_stats c ON a.molecule_id = c.molecule_id ORDER BY a.carbon_count DESC, a.atom_count DESC	toxicology
SELECT DISTINCT a.element FROM connected c JOIN atom a ON (a.atom_id = c.atom_id OR a.atom_id = c.atom_id2) WHERE c.bond_id = 'TR004_8_9'	toxicology
WITH dba AS ( SELECT c.atom_id AS atom_id, b.molecule_id AS molecule_id FROM connected c JOIN bond b ON b.bond_id = c.bond_id AND b.bond_type = '=' UNION SELECT c.atom_id2 AS atom_id, b.molecule_id AS molecule_id FROM connected c JOIN bond b ON b.bond_id = c.bond_id AND b.bond_type = '=' ) SELECT a.element AS element, COUNT(DISTINCT a.atom_id) AS atom_count, COUNT(DISTINCT dba.molecule_id) AS molecule_count, ROUND(100.0 * COUNT(DISTINCT a.atom_id) / (SELECT COUNT(*) FROM atom), 2) AS percentage_all_atoms, (SELECT GROUP_CONCAT(example, ', ') FROM ( SELECT DISTINCT m.molecule_id || ' (' || m.label || ')' AS example FROM dba d2 JOIN atom a2 ON a2.atom_id = d2.atom_id JOIN molecule m ON m.molecule_id = d2.molecule_id WHERE a2.element = a.element ORDER BY example LIMIT 3 ) ) AS example_molecules FROM dba JOIN atom a ON a.atom_id = dba.atom_id GROUP BY a.element ORDER BY a.element	toxicology
SELECT target.label, (SELECT COUNT(*) FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE m.label = target.label AND a.element = 'h') AS total_hydrogen_atoms, CAST((SELECT COUNT(*) FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE m.label = target.label AND a.element = 'h') AS REAL) / (SELECT COUNT(*) FROM molecule WHERE label = target.label) AS avg_hydrogen_per_molecule, CAST((SELECT COUNT(*) FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE m.label = target.label) AS REAL) / (SELECT COUNT(*) FROM molecule WHERE label = target.label) AS avg_bonds_per_molecule, (SELECT COUNT(*) FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE m.label = target.label AND b.bond_type = '-') AS total_single_bonds, (SELECT COUNT(*) FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE m.label = target.label AND b.bond_type = '=') AS total_double_bonds FROM ( SELECT m.label FROM molecule m JOIN atom a ON a.molecule_id = m.molecule_id AND a.element = 'h' GROUP BY m.label ORDER BY COUNT(*) DESC LIMIT 1 ) AS target	toxicology
SELECT b.bond_type, COUNT(DISTINCT c.bond_id) AS bond_frequency, COUNT(DISTINCT CASE WHEN a1.element = 'cl' AND a2.element <> 'cl' THEN a2.atom_id WHEN a2.element = 'cl' AND a1.element <> 'cl' THEN a1.atom_id ELSE NULL END) AS non_cl_atom_count FROM connected c JOIN bond b ON c.bond_id = b.bond_id JOIN atom a1 ON c.atom_id = a1.atom_id JOIN atom a2 ON c.atom_id2 = a2.atom_id WHERE a1.element = 'cl' OR a2.element = 'cl' GROUP BY b.bond_type ORDER BY bond_frequency DESC	toxicology
SELECT c.atom_id, c.atom_id2 FROM connected c JOIN bond b ON c.bond_id = b.bond_id WHERE b.bond_type = '-'	toxicology
SELECT c.atom_id, c.atom_id2 FROM connected c JOIN bond b ON c.bond_id = b.bond_id JOIN molecule m ON b.molecule_id = m.molecule_id WHERE m.label = '-'	toxicology
SELECT a.element FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE m.label = '-' GROUP BY a.element ORDER BY COUNT(*) ASC LIMIT 1	toxicology
SELECT DISTINCT b.bond_type FROM connected c JOIN bond b ON b.bond_id = c.bond_id WHERE (c.atom_id = 'TR004_8' AND c.atom_id2 = 'TR004_20') OR (c.atom_id = 'TR004_20' AND c.atom_id2 = 'TR004_8')	toxicology
SELECT DISTINCT m.label FROM molecule m WHERE NOT EXISTS ( SELECT 1 FROM molecule m2 JOIN atom a ON a.molecule_id = m2.molecule_id WHERE m2.label = m.label AND a.element = 'sn' )	toxicology
SELECT COUNT(DISTINCT a.atom_id) AS atom_count FROM atom a JOIN bond b ON a.molecule_id = b.molecule_id WHERE b.bond_type = '-' AND a.element IN ('i','s')	toxicology
SELECT c.atom_id, c.atom_id2 FROM connected c JOIN bond b ON c.bond_id = b.bond_id WHERE b.bond_type = '#'	toxicology
SELECT DISTINCT a2.atom_id FROM connected c JOIN atom a1 ON c.atom_id = a1.atom_id JOIN atom a2 ON c.atom_id2 = a2.atom_id WHERE a1.molecule_id = 'TR181' UNION SELECT DISTINCT a2.atom_id FROM connected c JOIN atom a1 ON c.atom_id2 = a1.atom_id JOIN atom a2 ON c.atom_id = a2.atom_id WHERE a1.molecule_id = 'TR181'	toxicology
SELECT 100.0 * SUM(CASE WHEN f_count = 0 THEN 1 ELSE 0 END) / COUNT(*) AS pct_without_fluorine, AVG(atoms) AS avg_atoms_per_molecule, AVG(CASE WHEN f_count > 0 THEN bonds END) AS avg_bonds_with_fluorine, AVG(CASE WHEN f_count = 0 THEN bonds END) AS avg_bonds_without_fluorine, ( SELECT AVG(CASE b.bond_type WHEN '-' THEN 1 WHEN '=' THEN 2 WHEN '#' THEN 3 END) FROM bond b JOIN molecule m2 ON m2.molecule_id = b.molecule_id WHERE m2.label = '+' ) AS avg_bond_strength FROM ( SELECT c.molecule_id, COUNT(a.atom_id) AS atoms, (SELECT COUNT(*) FROM bond b WHERE b.molecule_id = c.molecule_id) AS bonds, SUM(CASE WHEN a.element = 'f' THEN 1 ELSE 0 END) AS f_count FROM molecule c LEFT JOIN atom a ON a.molecule_id = c.molecule_id WHERE c.label = '+' GROUP BY c.molecule_id ) stats	toxicology
SELECT CAST(SUM(CASE WHEN bond.bond_type = '#' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(bond.bond_id) AS percent FROM bond INNER JOIN molecule ON bond.molecule_id = molecule.molecule_id WHERE molecule.label = '+'	toxicology
SELECT element FROM (SELECT element, COUNT(*) AS cnt FROM atom WHERE molecule_id = 'TR000' GROUP BY element ORDER BY cnt DESC, element ASC LIMIT 3) AS top_elements ORDER BY element ASC	toxicology
SELECT DISTINCT a.atom_id, a.element FROM connected c JOIN atom a ON a.atom_id = c.atom_id OR a.atom_id = c.atom_id2 WHERE c.bond_id = 'TR001_2_6' AND a.molecule_id = 'TR001'	toxicology
SELECT SUM(CASE WHEN label = '+' THEN 1 ELSE 0 END) - SUM(CASE WHEN label = '-' THEN 1 ELSE 0 END) AS difference FROM molecule	toxicology
SELECT atom_id, atom_id2 FROM connected WHERE bond_id = 'TR000_2_5'	toxicology
SELECT c.bond_id, c.atom_id, c.atom_id2, a1.element AS atom1_element, a2.element AS atom2_element, b.bond_type, CASE WHEN a1.element = 'cl' OR a2.element = 'cl' THEN 'Contains Chlorine' WHEN a1.element = 'c' AND a2.element = 'c' THEN 'Carbon-Carbon Bond' ELSE 'Other Bond Type' END AS bond_classification, (SELECT COUNT(*) FROM atom am WHERE am.molecule_id = b.molecule_id) AS molecule_atom_count, (SELECT COUNT(*) FROM bond bm WHERE bm.molecule_id = b.molecule_id) AS molecule_bond_count FROM connected c JOIN bond b ON b.bond_id = c.bond_id JOIN atom a1 ON a1.atom_id = c.atom_id JOIN atom a2 ON a2.atom_id = c.atom_id2 WHERE c.atom_id2 = 'TR000_2' ORDER BY c.bond_id	toxicology
SELECT DISTINCT m.molecule_id FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE b.bond_type = '=' ORDER BY m.molecule_id LIMIT 5	toxicology
SELECT ROUND(100.0 * SUM(CASE WHEN bond_type = '=' THEN 1 ELSE 0 END) / COUNT(bond_id), 5) AS percent FROM bond WHERE molecule_id = 'TR008'	toxicology
SELECT ROUND(CAST(SUM(label = '+') AS REAL) * 100 / COUNT(molecule_id), 3) AS percentage FROM molecule	toxicology
SELECT printf('%.4f', 100.0 * SUM(element = 'h') / COUNT(atom_id)) AS percent FROM atom WHERE molecule_id = 'TR206'	toxicology
WITH directed_pairs AS ( SELECT b.bond_type, b.bond_id, a1.element AS element1, a2.element AS element2 FROM bond b JOIN connected c ON c.bond_id = b.bond_id JOIN atom a1 ON a1.atom_id = c.atom_id JOIN atom a2 ON a2.atom_id = c.atom_id2 WHERE b.molecule_id = 'TR000' ), unique_pair_per_bond AS ( SELECT DISTINCT bond_type, bond_id, CASE WHEN element1 <= element2 THEN element1 ELSE element2 END AS elem1, CASE WHEN element1 <= element2 THEN element2 ELSE element1 END AS elem2 FROM directed_pairs ), type_pair_stats AS ( SELECT bond_type, COUNT(*) AS unique_element_pairs FROM ( SELECT DISTINCT bond_type, elem1, elem2 FROM unique_pair_per_bond ) GROUP BY bond_type ), type_bond_counts AS ( SELECT bond_type, COUNT(*) AS bond_count FROM bond WHERE molecule_id = 'TR000' GROUP BY bond_type ) SELECT c.bond_type, c.bond_count, p.unique_element_pairs, CASE WHEN c.bond_count > 1 THEN 'multiple times' ELSE 'once' END AS appearance, m.label FROM type_bond_counts c JOIN type_pair_stats p ON p.bond_type = c.bond_type JOIN molecule m ON m.molecule_id = 'TR000' ORDER BY c.bond_count DESC	toxicology
SELECT DISTINCT a.element, m.label FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE a.molecule_id = 'TR060'	toxicology
