SELECT d.forename AS forename, d.surname AS surname, ps.duration AS duration FROM pitStops ps JOIN races r ON ps.raceId = r.raceId JOIN drivers d ON ps.driverId = d.driverId WHERE r.year = 2011 AND r.name = 'Australian Grand Prix'	formula_1
SELECT lapTimes.time AS lap_record FROM lapTimes JOIN drivers ON lapTimes.driverId = drivers.driverId WHERE drivers.forename = 'Lewis' AND drivers.surname = 'Hamilton' ORDER BY lapTimes.milliseconds ASC LIMIT 1	formula_1
SELECT d.forename, d.surname FROM lapTimes lt JOIN drivers d ON d.driverId = lt.driverId WHERE lt.driverId IN ( SELECT ds.driverId FROM driverStandings ds WHERE ds.position <= 20 ) ORDER BY lt.milliseconds ASC, d.surname ASC, d.forename ASC LIMIT 1	formula_1
SELECT c.lat, c.lng FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId JOIN races r ON lt.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton' ORDER BY lt.time ASC LIMIT 1	formula_1
SELECT lt.time FROM lapTimes lt JOIN races r ON lt.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Austria' ORDER BY lt.milliseconds ASC LIMIT 1	formula_1
SELECT c.name AS circuit_name, MIN(r.fastestLapTime) AS lap_record_time FROM circuits c JOIN races ra ON c.circuitId = ra.circuitId JOIN results r ON r.raceId = ra.raceId WHERE c.country = 'Italy' AND r.fastestLapTime IS NOT NULL AND r.fastestLapTime != '' GROUP BY c.circuitId, c.name ORDER BY c.name	formula_1
SELECT r.name FROM lapTimes lt JOIN races r ON lt.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Austria' ORDER BY lt.milliseconds ASC LIMIT 1	formula_1
WITH record AS ( SELECT lt.raceId, lt.driverId FROM lapTimes lt JOIN races r ON r.raceId = lt.raceId JOIN circuits c ON c.circuitId = r.circuitId WHERE c.country = 'Austria' ORDER BY lt.milliseconds ASC LIMIT 1 ) SELECT p.duration FROM pitStops p JOIN record rec ON rec.raceId = p.raceId AND rec.driverId = p.driverId	formula_1
SELECT DISTINCT c.lat, c.lng FROM circuits c JOIN races r ON c.circuitId = r.circuitId JOIN lapTimes l ON r.raceId = l.raceId WHERE l.time = '1:29.488'	formula_1
SELECT AVG(p.milliseconds) AS avg_pit_stop_milliseconds FROM pitStops p JOIN drivers d ON p.driverId = d.driverId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton'	formula_1
SELECT AVG(lt.milliseconds) AS avg_lap_time_milliseconds FROM lapTimes lt JOIN races r ON lt.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Italy'	formula_1
SELECT player_api_id FROM Player_Attributes ORDER BY overall_rating DESC LIMIT 1	european_football_2
SELECT height, player_name FROM Player ORDER BY height DESC LIMIT 1	european_football_2
SELECT preferred_foot FROM Player_Attributes WHERE potential = (SELECT MIN(potential) FROM Player_Attributes) LIMIT 1	european_football_2
SELECT COUNT(DISTINCT player_api_id) AS player_count FROM Player_Attributes WHERE overall_rating >= 60 AND overall_rating <= 65 AND defensive_work_rate = 'low'	european_football_2
SELECT Player.id FROM Player JOIN Player_Attributes ON Player.player_api_id = Player_Attributes.player_api_id GROUP BY Player.id ORDER BY MAX(Player_Attributes.crossing) DESC LIMIT 5	european_football_2
SELECT League.name FROM Match JOIN League ON Match.league_id = League.id WHERE Match.season = '2015/2016' GROUP BY League.id, League.name ORDER BY SUM(Match.home_team_goal + Match.away_team_goal) DESC LIMIT 1	european_football_2
SELECT t.team_long_name FROM Match m JOIN Team t ON m.home_team_api_id = t.team_api_id WHERE m.season = '2015/2016' AND m.home_team_goal < m.away_team_goal GROUP BY m.home_team_api_id, t.team_long_name ORDER BY COUNT(*) ASC LIMIT 1	european_football_2
SELECT p.player_name FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id GROUP BY p.player_api_id, p.player_name ORDER BY MAX(pa.penalties) DESC LIMIT 10	european_football_2
SELECT t.team_long_name FROM Match m JOIN League l ON m.league_id = l.id JOIN Team t ON m.away_team_api_id = t.team_api_id WHERE l.name = 'Scotland Premier League' AND m.season = '2009/2010' AND m.away_team_goal > m.home_team_goal GROUP BY t.team_api_id, t.team_long_name ORDER BY COUNT(*) DESC LIMIT 1	european_football_2
SELECT t.team_long_name FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id GROUP BY t.team_api_id, t.team_long_name ORDER BY buildUpPlaySpeed DESC LIMIT 4	european_football_2
SELECT l.name AS league_name FROM Match m JOIN League l ON m.league_id = l.id WHERE m.season = '2015/2016' AND m.home_team_goal = m.away_team_goal GROUP BY m.league_id, l.name ORDER BY COUNT(*) DESC LIMIT 1	european_football_2
SELECT p.player_name, CAST((julianday('now') - julianday(p.birthday)) / 365.25 AS INTEGER) AS age FROM Player p WHERE EXISTS ( SELECT 1 FROM Player_Attributes pa WHERE pa.player_api_id = p.player_api_id AND pa.sprint_speed >= 97 AND STRFTIME('%Y', pa.date) >= '2013' AND STRFTIME('%Y', pa.date) <= '2015' )	european_football_2
SELECT l.name AS league_name, COUNT(m.league_id) AS matches_played FROM Match m JOIN League l ON m.league_id = l.id GROUP BY m.league_id, l.name ORDER BY COUNT(m.league_id) DESC LIMIT 1	european_football_2
SELECT CAST(SUM(height) AS REAL) / COUNT(id) AS average_height FROM Player WHERE birthday >= '1990-01-01 00:00:00' AND birthday < '1996-01-01 00:00:00'	european_football_2
SELECT player_api_id FROM Player_Attributes WHERE substr(date,1,4) = '2010' AND overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes WHERE substr(date,1,4) = '2010') GROUP BY player_api_id	european_football_2
SELECT DISTINCT team_fifa_api_id FROM Team_Attributes WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60	european_football_2
SELECT DISTINCT t.team_long_name FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id WHERE substr(ta.date, 1, 4) = '2012' AND ta.buildUpPlayPassing > ( SELECT AVG(ta2.buildUpPlayPassing) FROM Team_Attributes ta2 WHERE substr(ta2.date, 1, 4) = '2012' )	european_football_2
SELECT SUM(CASE WHEN pa.preferred_foot = 'left' THEN 1 ELSE 0 END) * 100.0 / COUNT(pa.player_fifa_api_id) AS left_foot_percentage FROM Player_Attributes pa JOIN Player p ON pa.player_fifa_api_id = p.player_fifa_api_id WHERE STRFTIME('%Y', p.birthday) BETWEEN '1987' AND '1992'	european_football_2
SELECT l.name FROM League l JOIN Match m ON l.id = m.league_id GROUP BY l.name ORDER BY SUM(m.home_team_goal + m.away_team_goal) ASC LIMIT 5	european_football_2
SELECT CAST(SUM(pa.long_shots) AS REAL) / COUNT(pa.player_fifa_api_id) AS avg_long_shots FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Ahmed Samir Farag'	european_football_2
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON pa.player_api_id = p.player_api_id WHERE p.height > 180 GROUP BY p.player_api_id, p.player_name ORDER BY CAST(SUM(pa.heading_accuracy) AS REAL) / COUNT(pa.player_fifa_api_id) DESC LIMIT 10	european_football_2
SELECT t.team_long_name FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id WHERE ta.buildUpPlayDribblingClass = 'Normal' AND SUBSTR(ta.date, 1, 4) = '2014' AND ta.chanceCreationPassing < ( SELECT AVG(chanceCreationPassing) FROM Team_Attributes WHERE buildUpPlayDribblingClass = 'Normal' AND SUBSTR(date, 1, 4) = '2014' ) ORDER BY ta.chanceCreationPassing DESC	european_football_2
SELECT l.name FROM Match m JOIN League l ON m.league_id = l.id WHERE m.season = '2009/2010' GROUP BY l.id, l.name HAVING AVG(m.home_team_goal) > AVG(m.away_team_goal)	european_football_2
SELECT team_short_name FROM Team WHERE team_long_name = 'Queens Park Rangers'	european_football_2
SELECT player_name FROM Player WHERE STRFTIME('%Y', birthday) = '1970' AND STRFTIME('%m', birthday) = '10' ORDER BY player_name	european_football_2
SELECT pa.attacking_work_rate FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Franco Zennaro' ORDER BY pa.date DESC LIMIT 1	european_football_2
SELECT DISTINCT "buildUpPlayPositioningClass" FROM Team_Attributes JOIN Team ON Team_Attributes.team_api_id = Team.team_api_id WHERE Team.team_long_name = 'ADO Den Haag'	european_football_2
SELECT pa.heading_accuracy FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Francois Affolter' AND pa.date = '2014-09-18 00:00:00'	european_football_2
SELECT pa.overall_rating FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Gabriel Tamas' AND STRFTIME('%Y', pa.date) = '2011'	european_football_2
SELECT COUNT(*) FROM Match m JOIN League l ON m.league_id = l.id WHERE m.season = '2015/2016' AND l.name = 'Scotland Premier League'	european_football_2
SELECT pa.preferred_foot FROM (SELECT player_api_id FROM Player ORDER BY birthday DESC LIMIT 1) AS youngest JOIN Player_Attributes pa ON pa.player_api_id = youngest.player_api_id ORDER BY pa.date DESC LIMIT 1	european_football_2
SELECT DISTINCT p.player_name, pa.potential FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.potential = (SELECT MAX(potential) FROM Player_Attributes)	european_football_2
SELECT COUNT(DISTINCT p.player_api_id) FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.weight < 130 AND pa.preferred_foot = 'left'	european_football_2
SELECT DISTINCT Team.team_short_name FROM Team_Attributes JOIN Team ON Team_Attributes.team_api_id = Team.team_api_id WHERE Team_Attributes.chanceCreationPassingClass = 'Risky'	european_football_2
SELECT pa.defensive_work_rate FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'David Wilson' ORDER BY pa.date DESC LIMIT 1	european_football_2
SELECT Player.birthday FROM Player_Attributes JOIN Player ON Player_Attributes.player_api_id = Player.player_api_id ORDER BY Player_Attributes.overall_rating DESC LIMIT 1	european_football_2
SELECT League.name FROM League JOIN Country ON League.country_id = Country.id WHERE Country.name = 'Netherlands'	european_football_2
SELECT AVG(Match.home_team_goal) AS avg_home_team_goal FROM Match JOIN Country ON Match.country_id = Country.id WHERE Country.name = 'Poland' AND Match.season = '2010/2011'	european_football_2
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.height = (SELECT MAX(height) FROM Player) OR p.height = (SELECT MIN(height) FROM Player) GROUP BY p.player_api_id, p.player_name ORDER BY AVG(pa.finishing) DESC LIMIT 1	european_football_2
SELECT player_name FROM Player WHERE height > 180	european_football_2
SELECT COUNT(*) FROM Player WHERE strftime('%Y', birthday) > '1990'	european_football_2
SELECT COUNT(*) AS num_players FROM Player WHERE (player_name = 'Adam' OR player_name LIKE 'Adam %') AND weight > 170	european_football_2
SELECT DISTINCT Player.player_name FROM Player_Attributes JOIN Player ON Player_Attributes.player_api_id = Player.player_api_id WHERE Player_Attributes.overall_rating > 80 AND strftime('%Y', Player_Attributes.date) BETWEEN '2008' AND '2010'	european_football_2
SELECT PA.potential FROM Player_Attributes PA JOIN Player P ON PA.player_api_id = P.player_api_id WHERE P.player_name = 'Aaron Doran' ORDER BY PA.date DESC LIMIT 1	european_football_2
SELECT DISTINCT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.preferred_foot = 'left'	european_football_2
SELECT DISTINCT t.team_long_name FROM Team t JOIN Team_Attributes ta ON t.team_api_id = ta.team_api_id WHERE ta.buildUpPlaySpeedClass = 'Fast'	european_football_2
