SELECT pa.heading_accuracy FROM Player p JOIN Player_Attributes pa ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Ariel Borysiuk' ORDER BY pa.date DESC LIMIT 1	european_football_2
