SELECT COUNT(*) FROM Match JOIN Country ON Match.country_id = Country.id WHERE Match.season = '2008/2009' AND Country.name = 'Belgium'	european_football_2
SELECT pa.long_passing FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY p.birthday ASC LIMIT 1	european_football_2
SELECT COUNT(*) FROM Match JOIN League ON Match.league_id = League.id WHERE League.name = 'Belgium Jupiler League' AND SUBSTR(Match.date, 1, 7) = '2009-04'	european_football_2
SELECT League.name FROM Match JOIN League ON Match.league_id = League.id WHERE Match.season = '2008/2009' GROUP BY Match.league_id, League.name ORDER BY COUNT(*) DESC LIMIT 1	european_football_2
SELECT CAST(SUM(pa.overall_rating) AS REAL) / COUNT(pa.id) AS avg_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE strftime('%Y', p.birthday) < '1986'	european_football_2
WITH cte_ariel AS ( SELECT pa.overall_rating FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Ariel Borysiuk' ORDER BY pa.date DESC LIMIT 1 ), cte_paulin AS ( SELECT pa.overall_rating FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Paulin Puel' ORDER BY pa.date DESC LIMIT 1 ) SELECT ((SELECT overall_rating FROM cte_ariel) - (SELECT overall_rating FROM cte_paulin)) * 100.0 / (SELECT overall_rating FROM cte_paulin) AS percentage_higher	european_football_2
SELECT AVG(ta.buildUpPlaySpeed) AS avg_build_up_play_speed FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'Heart of Midlothian'	european_football_2
