SELECT (100.0 * (la.overall_rating - ja.overall_rating) / la.overall_rating) AS percentage FROM (SELECT pa.overall_rating FROM Player_Attributes pa JOIN Player p ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Landon Donovan' AND pa.date = '2013-07-12 00:00:00') AS la, (SELECT pa.overall_rating FROM Player_Attributes pa JOIN Player p ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Jordan Bowery' AND pa.date = '2013-07-12 00:00:00') AS ja	european_football_2
