SELECT DISTINCT Player.player_name FROM Player JOIN Player_Attributes ON Player.player_api_id = Player_Attributes.player_api_id WHERE Player_Attributes.attacking_work_rate = 'high'	european_football_2
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.finishing = 1 GROUP BY p.player_api_id, p.player_name ORDER BY MAX(julianday(datetime(CURRENT_TIMESTAMP,'localtime')) - julianday(p.birthday)) DESC LIMIT 1	european_football_2
SELECT DISTINCT p.player_name FROM Match m JOIN Country c ON m.country_id = c.id JOIN Player p ON p.player_api_id IN (m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5, m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11, m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5, m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11) WHERE c.name = 'Belgium'	european_football_2
SELECT DISTINCT p.player_name, c.name AS country_name FROM Player_Attributes pa JOIN Player p ON p.player_api_id = pa.player_api_id JOIN Match m ON p.player_api_id IN ( m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5, m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11, m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5, m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11 ) JOIN Country c ON c.id = m.country_id WHERE pa.vision > 89	european_football_2
WITH appearances AS ( SELECT country_id, home_player_1 AS player_api_id FROM Match UNION ALL SELECT country_id, home_player_2 FROM Match UNION ALL SELECT country_id, home_player_3 FROM Match UNION ALL SELECT country_id, home_player_4 FROM Match UNION ALL SELECT country_id, home_player_5 FROM Match UNION ALL SELECT country_id, home_player_6 FROM Match UNION ALL SELECT country_id, home_player_7 FROM Match UNION ALL SELECT country_id, home_player_8 FROM Match UNION ALL SELECT country_id, home_player_9 FROM Match UNION ALL SELECT country_id, home_player_10 FROM Match UNION ALL SELECT country_id, home_player_11 FROM Match UNION ALL SELECT country_id, away_player_1 FROM Match UNION ALL SELECT country_id, away_player_2 FROM Match UNION ALL SELECT country_id, away_player_3 FROM Match UNION ALL SELECT country_id, away_player_4 FROM Match UNION ALL SELECT country_id, away_player_5 FROM Match UNION ALL SELECT country_id, away_player_6 FROM Match UNION ALL SELECT country_id, away_player_7 FROM Match UNION ALL SELECT country_id, away_player_8 FROM Match UNION ALL SELECT country_id, away_player_9 FROM Match UNION ALL SELECT country_id, away_player_10 FROM Match UNION ALL SELECT country_id, away_player_11 FROM Match ), country_players AS ( SELECT DISTINCT country_id, player_api_id FROM appearances ) SELECT c.name FROM country_players cp JOIN Player p ON p.player_api_id = cp.player_api_id JOIN Country c ON c.id = cp.country_id GROUP BY cp.country_id, c.name ORDER BY AVG(p.weight) DESC LIMIT 1	european_football_2
SELECT DISTINCT Team.team_long_name FROM Team JOIN Team_Attributes ON Team.team_api_id = Team_Attributes.team_api_id WHERE Team_Attributes.buildUpPlaySpeedClass = 'Slow'	european_football_2
SELECT DISTINCT T.team_short_name FROM Team_Attributes TA JOIN Team T ON TA.team_api_id = T.team_api_id WHERE TA.chanceCreationPassingClass = 'Safe'	european_football_2
WITH italy_matches AS ( SELECT m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5, m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11, m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5, m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11 FROM Match m JOIN Country c ON m.country_id = c.id WHERE c.name = 'Italy' ), participants AS ( SELECT home_player_1 AS player_api_id FROM italy_matches UNION SELECT home_player_2 FROM italy_matches UNION SELECT home_player_3 FROM italy_matches UNION SELECT home_player_4 FROM italy_matches UNION SELECT home_player_5 FROM italy_matches UNION SELECT home_player_6 FROM italy_matches UNION SELECT home_player_7 FROM italy_matches UNION SELECT home_player_8 FROM italy_matches UNION SELECT home_player_9 FROM italy_matches UNION SELECT home_player_10 FROM italy_matches UNION SELECT home_player_11 FROM italy_matches UNION SELECT away_player_1 FROM italy_matches UNION SELECT away_player_2 FROM italy_matches UNION SELECT away_player_3 FROM italy_matches UNION SELECT away_player_4 FROM italy_matches UNION SELECT away_player_5 FROM italy_matches UNION SELECT away_player_6 FROM italy_matches UNION SELECT away_player_7 FROM italy_matches UNION SELECT away_player_8 FROM italy_matches UNION SELECT away_player_9 FROM italy_matches UNION SELECT away_player_10 FROM italy_matches UNION SELECT away_player_11 FROM italy_matches ) SELECT AVG(p.height) AS avg_height FROM participants JOIN Player p ON p.player_api_id = participants.player_api_id	european_football_2
SELECT player_name FROM ( SELECT player_name, height FROM Player WHERE height > 180 ORDER BY height DESC LIMIT 3 ) AS top_players ORDER BY player_name ASC	european_football_2
SELECT COUNT(*) FROM Player WHERE player_name LIKE 'Aaron%' AND birthday > '1990'	european_football_2
SELECT (SELECT jumping FROM Player_Attributes WHERE id = 6) - (SELECT jumping FROM Player_Attributes WHERE id = 23) AS jumping_difference	european_football_2
SELECT p.player_api_id FROM Player AS p JOIN Player_Attributes AS pa ON p.player_api_id = pa.player_api_id WHERE pa.preferred_foot = 'right' GROUP BY p.player_api_id ORDER BY MIN(pa.potential) ASC LIMIT 5	european_football_2
SELECT COUNT(DISTINCT player_api_id) AS player_count FROM Player_Attributes WHERE preferred_foot = 'left' AND crossing = (SELECT MAX(crossing) FROM Player_Attributes WHERE preferred_foot = 'left')	european_football_2
SELECT CAST(COUNT(DISTINCT p.player_api_id) AS REAL) * 100 / (SELECT COUNT(*) FROM Player) AS percentage FROM Player p JOIN Player_Attributes pa ON pa.player_api_id = p.player_api_id WHERE pa.strength > 80 AND pa.stamina > 80	european_football_2
SELECT Country.name FROM League JOIN Country ON League.country_id = Country.id WHERE League.name = 'Poland Ekstraklasa'	european_football_2
SELECT m.home_team_goal, m.away_team_goal FROM Match m JOIN League l ON m.league_id = l.id WHERE m.date LIKE '2008-09-24%' AND l.name = 'Belgium Jupiler League'	european_football_2
SELECT pa.sprint_speed, pa.agility, pa.acceleration FROM Player_Attributes pa JOIN Player p ON p.player_api_id = pa.player_api_id WHERE p.player_name = 'Alexis Blin' ORDER BY pa.date DESC LIMIT 1	european_football_2
SELECT ta.buildUpPlaySpeedClass FROM Team_Attributes ta JOIN Team t ON ta.team_api_id = t.team_api_id WHERE t.team_long_name = 'KSV Cercle Brugge' ORDER BY ta.date DESC LIMIT 1	european_football_2
SELECT COUNT(*) AS games_played FROM Match JOIN League ON Match.league_id = League.id WHERE League.name = 'Italy Serie A' AND Match.season = '2015/2016'	european_football_2
SELECT MAX(M.home_team_goal) AS highest_home_team_score FROM Match M JOIN League L ON M.league_id = L.id WHERE L.name = 'Netherlands Eredivisie'	european_football_2
SELECT pa.finishing, pa.curve FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.weight = (SELECT MAX(weight) FROM Player)	european_football_2
SELECT League.name FROM Match JOIN League ON Match.league_id = League.id WHERE Match.season = '2015/2016' GROUP BY League.name ORDER BY COUNT(Match.id) DESC LIMIT 4	european_football_2
SELECT t.team_long_name FROM Match m JOIN Team t ON t.team_api_id = m.away_team_api_id ORDER BY m.away_team_goal DESC LIMIT 1	european_football_2
SELECT Player.player_name FROM Player_Attributes JOIN Player ON Player_Attributes.player_api_id = Player.player_api_id ORDER BY Player_Attributes.overall_rating DESC LIMIT 1	european_football_2
SELECT CAST(COUNT(DISTINCT CASE WHEN PA.overall_rating > 70 THEN P.id END) AS REAL) * 100.0 / COUNT(DISTINCT P.id) AS percentage FROM Player P LEFT JOIN Player_Attributes PA ON P.player_api_id = PA.player_api_id WHERE P.height < 180	european_football_2
SELECT CAST(COUNT(CASE WHEN Admission = '+' THEN ID END) AS REAL) * 100 / COUNT(CASE WHEN Admission = '-' THEN ID END) AS percentage FROM Patient WHERE SEX = 'M'	thrombosis_prediction
SELECT CAST(SUM(CASE WHEN STRFTIME('%Y', Birthday) > '1930' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(ID) AS percentage FROM Patient WHERE Sex = 'F'	thrombosis_prediction
SELECT 100.0 * SUM(CASE WHEN "Admission" = '+' THEN 1 ELSE 0 END) / COUNT(*) AS percentage FROM "Patient" WHERE "Birthday" >= '1930-01-01' AND "Birthday" <= '1940-12-31'	thrombosis_prediction
SELECT CAST(COUNT(CASE WHEN "Admission" = '-' THEN "ID" END) AS REAL) / COUNT(CASE WHEN "Admission" = '+' THEN "ID" END) AS outpatient_inpatient_ratio FROM "Patient" WHERE TRIM("Diagnosis") = 'SLE'	thrombosis_prediction
SELECT Patient.Diagnosis, Laboratory.Date FROM Patient JOIN Laboratory ON Patient.ID = Laboratory.ID WHERE Patient.ID = 30609 ORDER BY Laboratory.Date	thrombosis_prediction
