SELECT DISTINCT Patient.ID, CAST(STRFTIME('%Y', 'now') AS INTEGER) - CAST(STRFTIME('%Y', Patient.Birthday) AS INTEGER) AS Age FROM Examination JOIN Patient ON Examination.ID = Patient.ID WHERE Examination.RVVT = '+'	thrombosis_prediction
SELECT DISTINCT Patient.ID, Patient.SEX, Patient.Diagnosis FROM Examination JOIN Patient ON Examination.ID = Patient.ID WHERE Examination.Thrombosis = 2	thrombosis_prediction
SELECT DISTINCT "Patient"."ID" FROM "Patient" INNER JOIN "Laboratory" ON "Patient"."ID" = "Laboratory"."ID" WHERE STRFTIME('%Y', "Patient"."Birthday") = '1937' AND "Laboratory"."T-CHO" >= 250	thrombosis_prediction
