SELECT AVG(E."aCL IgG") AS avg_igg FROM Examination E JOIN Patient P ON E."ID" = P."ID" WHERE P."Admission" = '+' AND (CAST(STRFTIME('%Y', E."Examination Date") AS INTEGER) - CAST(STRFTIME('%Y', P."Birthday") AS INTEGER)) >= 50	thrombosis_prediction
