SELECT MAX(CAST(STRFTIME('%Y', Patient.Birthday) AS INTEGER)) - MIN(CAST(STRFTIME('%Y', Patient.Birthday) AS INTEGER)) AS age_gap FROM Patient JOIN Laboratory ON Patient.ID = Laboratory.ID WHERE Laboratory.TG >= 200	thrombosis_prediction
