SELECT CAST(COUNT(Laboratory.ID) AS REAL) / 12.0 AS avg_male_patients_per_month FROM Laboratory JOIN Patient ON Laboratory.ID = Patient.ID WHERE Patient.SEX = 'M' AND Laboratory.Date BETWEEN '1998-01-01' AND '1998-12-31'	thrombosis_prediction
SELECT (SELECT MAX(l."Date") FROM Laboratory l WHERE l."ID" = p."ID") AS latest_lab_date, (CAST(STRFTIME('%Y', p."First Date") AS INTEGER) - CAST(STRFTIME('%Y', p."Birthday") AS INTEGER)) AS age_at_arrival FROM Patient p WHERE p."Diagnosis" = 'SJS' ORDER BY p."Birthday" ASC LIMIT 1	thrombosis_prediction
