SELECT COUNT(*) AS cnt FROM (SELECT p.ID, MIN(date(e."Examination Date")) AS first_exam_date, date(p."First Date") AS first_visit_date FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE p."First Date" IS NOT NULL GROUP BY p.ID) t WHERE julianday(t.first_exam_date) - julianday(t.first_visit_date) >= 365	thrombosis_prediction
