SELECT CAST(STRFTIME('%Y', l.Date) AS INTEGER) - CAST(STRFTIME('%Y', p.Birthday) AS INTEGER) AS Age, p.Diagnosis FROM Laboratory AS l JOIN Patient AS p ON l.ID = p.ID ORDER BY l.HGB DESC LIMIT 1	thrombosis_prediction
