SELECT COUNT(DISTINCT Laboratory.ID) AS patient_count FROM Laboratory WHERE Laboratory.Date BETWEEN '1987-07-06' AND '1996-01-31' AND Laboratory.GPT > 30 AND Laboratory.ALB < 4	thrombosis_prediction
