SELECT CAST(COUNT(DISTINCT CASE WHEN p.Diagnosis = 'SLE' THEN l.ID END) AS REAL) / COUNT(DISTINCT l.ID) AS percentage FROM Laboratory l JOIN Patient p ON l.ID = p.ID WHERE l.GOT >= 60	thrombosis_prediction
