SELECT COUNT(DISTINCT Patient.ID) AS patient_count FROM Patient JOIN Laboratory ON Patient.ID = Laboratory.ID WHERE TRIM(Patient.Diagnosis) = 'SJS' AND Laboratory.TP > 6.0 AND Laboratory.TP < 8.5	thrombosis_prediction
