SELECT CAST(SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN Currency = 'CZK' THEN 1 ELSE 0 END) AS ratio FROM customers	debit_card_specializing
SELECT c.CustomerID FROM customers c JOIN yearmonth y ON y.CustomerID = c.CustomerID WHERE c.Segment = 'LAM' AND y.Date BETWEEN '201201' AND '201212' GROUP BY c.CustomerID ORDER BY SUM(y.Consumption) ASC LIMIT 1	debit_card_specializing
SELECT AVG(y.Consumption) / 12 AS avg_monthly_consumption FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE c.Segment = 'SME' AND y.Date BETWEEN '201301' AND '201312'	debit_card_specializing
SELECT c.CustomerID FROM customers c JOIN yearmonth y ON c.CustomerID = y.CustomerID WHERE c.Currency = 'CZK' AND y.Date BETWEEN '201101' AND '201112' GROUP BY c.CustomerID ORDER BY SUM(y.Consumption) DESC LIMIT 1	debit_card_specializing
SELECT COUNT(*) AS customer_count FROM (SELECT c.CustomerID FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Segment = 'KAM' AND ym.Date BETWEEN '201201' AND '201212' GROUP BY c.CustomerID HAVING SUM(ym.Consumption) < 30000) AS t	debit_card_specializing
SELECT SUM(CASE WHEN c.Currency = 'CZK' THEN y.Consumption ELSE 0 END) - SUM(CASE WHEN c.Currency = 'EUR' THEN y.Consumption ELSE 0 END) AS consumption_difference FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE y.Date BETWEEN '201201' AND '201212'	debit_card_specializing
SELECT CAST(SUBSTR(ym.Date, 1, 4) AS INTEGER) AS year FROM yearmonth ym JOIN customers c ON ym.CustomerID = c.CustomerID WHERE c.Currency = 'EUR' GROUP BY year ORDER BY SUM(ym.Consumption) DESC LIMIT 1	debit_card_specializing
SELECT c.Segment FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID GROUP BY c.Segment ORDER BY SUM(y.Consumption) ASC LIMIT 1	debit_card_specializing
SELECT SUBSTR(y.Date, 1, 4) AS year FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE c.Currency = 'CZK' GROUP BY SUBSTR(y.Date, 1, 4) ORDER BY SUM(y.Consumption) DESC LIMIT 1	debit_card_specializing
SELECT substr(y.Date, 5, 2) AS PeakMonth FROM yearmonth y JOIN customers c ON c.CustomerID = y.CustomerID WHERE c.Segment = 'SME' AND y.Date BETWEEN '201301' AND '201312' GROUP BY substr(y.Date, 5, 2) ORDER BY SUM(y.Consumption) DESC LIMIT 1	debit_card_specializing
WITH annual AS ( SELECT c.Segment, ym.CustomerID, SUM(ym.Consumption) AS total_consumption FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Currency = 'CZK' AND ym.Date BETWEEN '201301' AND '201312' GROUP BY c.Segment, ym.CustomerID ), seg_min AS ( SELECT Segment, MIN(total_consumption) AS min_consumption FROM annual GROUP BY Segment ) SELECT MAX(CASE WHEN Segment = 'SME' THEN min_consumption END) - MAX(CASE WHEN Segment = 'LAM' THEN min_consumption END) AS SME_LAM_difference, MAX(CASE WHEN Segment = 'LAM' THEN min_consumption END) - MAX(CASE WHEN Segment = 'KAM' THEN min_consumption END) AS LAM_KAM_difference, MAX(CASE WHEN Segment = 'KAM' THEN min_consumption END) - MAX(CASE WHEN Segment = 'SME' THEN min_consumption END) AS KAM_SME_difference FROM seg_min	debit_card_specializing
WITH seg AS ( SELECT c.Segment, SUM(CASE WHEN substr(y.Date,1,4)='2012' THEN y.Consumption ELSE 0 END) AS cons_2012, SUM(CASE WHEN substr(y.Date,1,4)='2013' THEN y.Consumption ELSE 0 END) AS cons_2013 FROM customers c JOIN yearmonth y ON c.CustomerID = y.CustomerID WHERE c.Currency = 'EUR' AND c.Segment IN ('SME','LAM','KAM') GROUP BY c.Segment ), pct AS ( SELECT Segment, (cons_2013 - cons_2012) * 100.0 / cons_2012 AS pct_increase FROM seg ) SELECT Segment FROM (SELECT Segment, pct_increase FROM pct ORDER BY pct_increase DESC LIMIT 1) UNION ALL SELECT Segment FROM (SELECT Segment, pct_increase FROM pct ORDER BY pct_increase ASC LIMIT 1)	debit_card_specializing
