SELECT c.Segment FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE y.Date = '201309' GROUP BY c.Segment ORDER BY SUM(y.Consumption) ASC LIMIT 1	debit_card_specializing
SELECT c.CustomerID FROM customers c JOIN yearmonth y ON c.CustomerID = y.CustomerID WHERE c.Segment = 'SME' AND y.Date = '201206' ORDER BY y.Consumption ASC LIMIT 1	debit_card_specializing
SELECT MAX(Consumption) AS highest_monthly_consumption FROM yearmonth WHERE Date BETWEEN '201201' AND '201212'	debit_card_specializing
SELECT MAX(ym.Consumption) AS biggest_monthly_consumption FROM yearmonth ym JOIN customers c ON ym.CustomerID = c.CustomerID WHERE c.Currency = 'EUR'	debit_card_specializing
SELECT DISTINCT TRIM(p.Description) AS Description FROM yearmonth ym JOIN transactions_1k t ON t.CustomerID = ym.CustomerID JOIN products p ON p.ProductID = t.ProductID WHERE ym.Date = '201309'	debit_card_specializing
SELECT DISTINCT g.Country FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE t.Date LIKE '2012-08%'	debit_card_specializing
SELECT DISTINCT gasstations.ChainID FROM transactions_1k JOIN customers ON transactions_1k.CustomerID = customers.CustomerID JOIN gasstations ON transactions_1k.GasStationID = gasstations.GasStationID WHERE customers.Currency = 'EUR'	debit_card_specializing
SELECT DISTINCT TRIM(p.Description) AS Description FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID JOIN products p ON t.ProductID = p.ProductID WHERE c.Currency = 'EUR'	debit_card_specializing
SELECT AVG("Amount" * "Price") AS avg_total_price FROM transactions_1k WHERE "Date" LIKE '%2012-01%'	debit_card_specializing
SELECT COUNT(DISTINCT c.CustomerID) AS num_customers FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Currency = 'EUR' AND ym.Consumption > 1000	debit_card_specializing
SELECT p.Description FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID JOIN products p ON t.ProductID = p.ProductID WHERE g.Country = 'CZE'	debit_card_specializing
SELECT DISTINCT t.Time FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE g.ChainID = 11	debit_card_specializing
SELECT COUNT(*) FROM transactions_1k JOIN gasstations ON transactions_1k.GasStationID = gasstations.GasStationID WHERE gasstations.Country = 'CZE' AND transactions_1k.Price > 1000	debit_card_specializing
SELECT COUNT(*) FROM transactions_1k JOIN gasstations ON transactions_1k.GasStationID = gasstations.GasStationID WHERE gasstations.Country = 'CZE' AND transactions_1k.Date > '2012-01-01'	debit_card_specializing
SELECT AVG(t.Amount * t.Price) AS avg_total_price FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE g.Country = 'CZE'	debit_card_specializing
SELECT AVG(t.Amount * t.Price) AS avg_total_price FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID WHERE c.Currency = 'EUR'	debit_card_specializing
SELECT CustomerID FROM transactions_1k WHERE Date LIKE '2012-08-25%' GROUP BY CustomerID ORDER BY SUM(Amount * Price) DESC LIMIT 1	debit_card_specializing
SELECT g.Country FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE t.Date LIKE '2012-08-25%' AND t.Amount > 0 ORDER BY t.Time ASC, t.TransactionID ASC LIMIT 1	debit_card_specializing
SELECT DISTINCT customers.Currency FROM transactions_1k JOIN customers ON transactions_1k.CustomerID = customers.CustomerID WHERE transactions_1k.Date LIKE '2012-08-24%' AND transactions_1k.Time = '16:25:00'	debit_card_specializing
SELECT c.Segment FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID WHERE t.Date = '2012-08-23' AND t.Time = '21:20:00'	debit_card_specializing
SELECT COUNT(*) FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID WHERE c.Currency = 'CZK' AND t.Date LIKE '2012-08-26%' AND t.Time < '13:00:00'	debit_card_specializing
SELECT c.Segment FROM transactions_1k t JOIN customers c ON c.CustomerID = t.CustomerID ORDER BY t.Date ASC, t.Time ASC LIMIT 1	debit_card_specializing
SELECT DISTINCT g.Country FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE DATE(t.Date) = '2012-08-24' AND t.Time = '12:42:00'	debit_card_specializing
SELECT ProductID FROM transactions_1k WHERE Date = '2012-08-23' AND Time = '21:20:00'	debit_card_specializing
SELECT ym.Date, ym.Consumption FROM yearmonth ym WHERE ym.CustomerID IN (SELECT CustomerID FROM transactions_1k WHERE Date LIKE '2012-08-24%' AND Price = 124.05) AND ym.Date = '201201'	debit_card_specializing
SELECT COUNT(*) AS transaction_count FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE DATE(t.Date) = '2012-08-26' AND t.Time BETWEEN '08:00:00' AND '09:00:00' AND g.Country = 'CZE'	debit_card_specializing
SELECT c.Currency FROM yearmonth y JOIN customers c ON y.CustomerID = c.CustomerID WHERE y.Date = '201306' AND y.Consumption = 214582.17	debit_card_specializing
SELECT DISTINCT g.Country FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE t.CardID = 667467	debit_card_specializing
SELECT g.Country FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE t.Date LIKE '2012-08-24%' AND t.Price = 548.4	debit_card_specializing
SELECT 100.0 * COUNT(DISTINCT CASE WHEN c.Currency = 'EUR' THEN t.CustomerID END) / COUNT(DISTINCT t.CustomerID) AS percentage FROM transactions_1k t JOIN customers c ON c.CustomerID = t.CustomerID WHERE t.Date LIKE '2012-08-25%'	debit_card_specializing
SELECT (y2012.total - y2013.total) / y2012.total AS decrease_rate FROM ( SELECT SUM(Consumption) AS total FROM yearmonth WHERE CustomerID = ( SELECT CustomerID FROM transactions_1k WHERE SUBSTR(Date, 1, 10) = '2012-08-25' AND Price = 634.8 ) AND SUBSTR(Date, 1, 4) = '2012' ) AS y2012, ( SELECT SUM(Consumption) AS total FROM yearmonth WHERE CustomerID = ( SELECT CustomerID FROM transactions_1k WHERE SUBSTR(Date, 1, 10) = '2012-08-25' AND Price = 634.8 ) AND SUBSTR(Date, 1, 4) = '2013' ) AS y2013	debit_card_specializing
SELECT "GasStationID" FROM "transactions_1k" GROUP BY "GasStationID" ORDER BY SUM("Amount" * "Price") DESC LIMIT 1	debit_card_specializing
SELECT AVG(CASE WHEN Segment = 'Premium' THEN 100.0 ELSE 0 END) AS premium_percentage FROM gasstations WHERE Country = 'SVK'	debit_card_specializing
SELECT (SELECT SUM(t.Amount * t.Price) FROM transactions_1k AS t WHERE t.CustomerID = 38508) AS total_spent_gas_stations, (SELECT y.Consumption FROM yearmonth AS y WHERE y.CustomerID = 38508 AND y.Date = '201201') AS spent_january_2012	debit_card_specializing
SELECT TRIM(p.Description) AS full_name FROM ( SELECT ProductID, SUM(Amount) AS total_amount FROM transactions_1k GROUP BY ProductID ORDER BY total_amount DESC LIMIT 5 ) AS top_products JOIN products p ON p.ProductID = top_products.ProductID ORDER BY top_products.total_amount DESC	debit_card_specializing
SELECT t.CustomerID, SUM(t.Price) / SUM(t.Amount) AS avg_price_per_item, c.Currency FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID GROUP BY t.CustomerID, c.Currency ORDER BY SUM(t.Price) DESC LIMIT 1	debit_card_specializing
SELECT g.Country FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE t.ProductID = 2 ORDER BY t.Price DESC LIMIT 1	debit_card_specializing
SELECT y.Consumption FROM yearmonth y WHERE y.Date = '201208' AND y.CustomerID IN ( SELECT t.CustomerID FROM transactions_1k t WHERE t.ProductID = 5 AND t.Price / t.Amount > 29.0 )	debit_card_specializing
